    def cmd_portscan(self, ip: str):
        common_ports = [21, 22, 23, 25, 53, 80, 110, 135, 139, 143,
                        443, 445, 3306, 3389, 5900, 8080, 8443]
        self._info(f"Scanning common ports on {Fore.YELLOW}{ip}{Fore.WHITE}...")
        open_ports = []
        lock = threading.Lock()

        def check(port):
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(1.0)
                if s.connect_ex((ip, port)) == 0:
                    with lock:
                        open_ports.append(port)
                s.close()
            except Exception:
                pass

        threads = [threading.Thread(target=check, args=(p,), daemon=True) for p in common_ports]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=5)

        self._sep(f"PORT SCAN: {ip}")
        if open_ports:
            for p in sorted(open_ports):
                services = {21:'FTP',22:'SSH',23:'Telnet',25:'SMTP',53:'DNS',80:'HTTP',
                            110:'POP3',135:'MSRPC',139:'NetBIOS',143:'IMAP',443:'HTTPS',
                            445:'SMB',3306:'MySQL',3389:'RDP',5900:'VNC',8080:'HTTP-Alt',8443:'HTTPS-Alt'}
                svc = services.get(p, "Unknown")
                print(f"  {Fore.GREEN}[OPEN] {Fore.WHITE}Port {Fore.CYAN}{p:<6}{Fore.WHITE} {svc}")
        else:
            self._warn("No open ports found.")
        self._sep()

    def cmd_portcheck(self, ip):
        if not ip:
            self._err("Usage: portcheck <ip|hostname>")
            return
        target = ip
        try:
            import ipaddress
            ipaddress.ip_address(ip)
        except ValueError:
            try:
                ip = socket.gethostbyname(ip)
            except socket.gaierror:
                self._err(f"Could not resolve '{target}'.")
                return
        self._info(f"Scanning all 65,535 ports on "
                   f"{Fore.YELLOW}{ip}{Fore.WHITE} ...")

        from concurrent.futures import ThreadPoolExecutor, as_completed

        total = 65535
        open_ports = set()
        try:
            _cpus = psutil.cpu_count() or 4
        except Exception:
            _cpus = 4
        CONC = max(600, min(2400, _cpus * 150))
        OVERALL = 120.0
        mintime = time.time()
        deadline = mintime + OVERALL
        done = 0

        def probe(port, timeout):
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(timeout)
            try:
                rc = s.connect_ex((ip, port))
                if rc == 0:
                    return 'open'
                return 'closed'
            except (socket.timeout, OSError):
                return 'timeout'
            finally:
                s.close()

        prev_rate_t = mintime
        prev_rate_done = 0
        rate = 0.0

        def status(label, done_n):
            nonlocal prev_rate_t, prev_rate_done, rate
            now = time.time()
            if now > prev_rate_t:
                rate = (done_n - prev_rate_done) / (now - prev_rate_t)
            prev_rate_t = now
            prev_rate_done = done_n
            pct = done_n * 100.0 / total
            bar = self._ux_bar(pct, 14)
            refused = max(done_n - len(open_ports), 0)
            print(f"\r  {Fore.CYAN}PORTCHECK{Fore.WHITE} {ip}   {label}  "
                  f"{bar} {pct:3.0f}%   "
                  f"{done_n:,}/{total:,}   "
                  f"{Fore.GREEN}{len(open_ports)} open{Style.RESET_ALL}"
                  f"   refused {refused:,}   "
                  f"{Fore.YELLOW}~{rate:,.0f}/s{Style.RESET_ALL}"
                  f"   {now - mintime:.1f}s",
                  end="", flush=True)

        def clear_status():
            print(f"\r{' ' * 120}\r", end="", flush=True)

        pending = list(range(1, total + 1))
        try:
            for pass_idx, to in enumerate((2.5, 8.0)):
                if not pending or time.time() > deadline:
                    break
                new_pending = []
                ex = ThreadPoolExecutor(max_workers=CONC)
                futs = {ex.submit(probe, p, to): p for p in pending}
                observed = 0
                prev_bucket = -1
                try:
                    for fut in as_completed(futs):
                        observed += 1
                        port = futs.pop(fut)
                        outcome = fut.result()
                        done += 1
                        if outcome == 'open':
                            open_ports.add(port)
                        elif outcome == 'timeout':
                            new_pending.append(port)
                        bucket = done // 8192
                        if bucket != prev_bucket:
                            prev_bucket = bucket
                            status(f"P{pass_idx + 1}", done)
                        if time.time() > deadline:
                            break
                except Exception as e:
                    self._err(f"Scan error: {e}")
                    return
                finally:
                    try:
                        ex.shutdown(wait=False, cancel_futures=True)
                    except TypeError:
                        ex.shutdown(wait=False)
                leftover = list(futs.keys())
                pending = leftover + new_pending
                if not pending:
                    break
        except Exception as e:
            self._err(f"Scan error: {e}")
            return

        local_ish = ip in ("127.0.0.1", "::1") or ip.startswith("127.")
        if (not local_ish and not pending and len(open_ports) <= 2):
            self._info(f"{Fore.YELLOW}Target resists rapid scans "
                       f"(anti-scan filtering). Stealth-sweeping in small "
                       f"bursts with gaps - a few minutes...{Style.RESET_ALL}")
            ver_deadline = time.time() + 540.0
            v_done = 0
            to = 2.0
            for start in range(1, total + 1, 2048):
                if time.time() > ver_deadline:
                    break
                end = min(start + 2048, total + 1)
                ex = ThreadPoolExecutor(max_workers=400)
                try:
                    futs = {ex.submit(probe, p, to): p for p in range(start, end)}
                    for fu in as_completed(futs):
                        p = futs.pop(fu)
                        v_done += 1
                        if fu.result() == 'open':
                            open_ports.add(p)
                finally:
                    try:
                        ex.shutdown(wait=False, cancel_futures=True)
                    except TypeError:
                        ex.shutdown(wait=False)
                status("ST", done + v_done)
                time.sleep(5)
            clear_status()
            done = min(total, done + v_done)

        elapsed = time.time() - mintime
        clear_status()
        leftover = total - done

        print()
        info_lines = [
            f"Target      {ip}",
            f"Checked     {done:,} / {total:,}",
            f"Open        {Fore.GREEN}{len(open_ports)}{Style.RESET_ALL}",
            f"Closed      refused + timeout: {done - len(open_ports):,}",
            f"Skipped     {leftover:,}   (deadline hit)",
            f"Time        {elapsed:.2f} s",
        ]
        print(self._ux_box(
            "PORTCHECK COMPLETE", info_lines,
            title_color=Fore.GREEN, accent=Fore.CYAN))

        all_open = sorted(open_ports)
        if all_open:
            print()
            rows = []
            for p in all_open:
                try:
                    svc = socket.getservbyport(p, 'tcp')
                except OSError:
                    svc = "?"
                rows.append([f"{p}", "OPEN", f"{svc}"])
            shown = 0
            if len(rows) > 60:
                shown = len(rows) - 60
                rows = rows[:60]
            print(self._ux_box(
                f"OPEN PORTS ({len(all_open)})",
                self._ux_table(["Port", "State", "Service"], rows, width=44),
                accent=Fore.YELLOW))
            if shown:
                print(f"  {Fore.YELLOW}... {shown} more open ports not shown"
                      f"{Style.RESET_ALL}")
        else:
            print()
            print(self._ux_box("RESULT",
                               ["No open ports found on all 65,535."],
                               accent=Fore.CYAN))

    def cmd_speedtest(self):
        self._info("Testing internet speed (this may take a moment)...")

        try:
            try:
                import speedtest as _st
            except ImportError:
                _st = None

            if _st and hasattr(_st, 'Speedtest'):
                st = _st.Speedtest(secure=True)
                st.get_best_server()
                print(f"{Fore.YELLOW}Testing download...", end=' ', flush=True)
                dl = st.download() / 1_000_000
                print(f"{Fore.GREEN}{dl:.2f} Mbps")
                print(f"{Fore.YELLOW}Testing upload... ", end=' ', flush=True)
                ul = st.upload()   / 1_000_000
                print(f"{Fore.GREEN}{ul:.2f} Mbps")
                ping = getattr(getattr(st, 'results', None), 'ping', None)
                if ping is not None:
                    print(f"  {Fore.CYAN}Ping    : {Fore.WHITE}{ping:.2f} ms")
                return

            if _st is None:
                self._info("Optional speedtest-cli is not installed; using the built-in HTTP fallback.")

        except Exception as lib_err:
            self._warn(f"speedtest-cli unavailable ({lib_err}). Using HTTP fallback...")

        try:
            import time as _time

            DL_URL = "https://speed.cloudflare.com/__down?bytes=10000000"
            print(f"{Fore.YELLOW}Testing download (HTTP)...", end=' ', flush=True)
            t0 = _time.perf_counter()
            r  = _lazy_requests().get(DL_URL, stream=True, timeout=30)
            received = sum(len(chunk) for chunk in r.iter_content(chunk_size=65536))
            dt = _time.perf_counter() - t0
            dl_mbps = (received * 8) / (dt * 1_000_000) if dt > 0 else 0
            print(f"{Fore.GREEN}{dl_mbps:.2f} Mbps")

            UL_URL  = "https://speed.cloudflare.com/__up"
            payload = b'0' * 5_000_000
            print(f"{Fore.YELLOW}Testing upload (HTTP)...  ", end=' ', flush=True)
            t0 = _time.perf_counter()
            _lazy_requests().post(UL_URL, data=payload, timeout=30)
            dt = _time.perf_counter() - t0
            ul_mbps = (len(payload) * 8) / (dt * 1_000_000) if dt > 0 else 0
            print(f"{Fore.GREEN}{ul_mbps:.2f} Mbps")

            PING_URL = "https://speed.cloudflare.com/__down?bytes=1"
            samples  = []
            for _ in range(6):
                t0 = _time.perf_counter()
                _lazy_requests().head(PING_URL, timeout=5)
                samples.append((_time.perf_counter() - t0) * 1000)
            avg_ping = sum(sorted(samples)[1:-1]) / max(len(samples) - 2, 1)
            print(f"  {Fore.CYAN}Ping    : {Fore.WHITE}{avg_ping:.1f} ms (avg)")

        except requests.ConnectionError:
            self._err("No internet connection.")
        except Exception as e:
            self._err(f"Speed test failed: {e}")

    def cmd_wifi_list(self):
        try:
            self._info("Retrieving saved Wi-Fi profiles...")
            r = subprocess.run(['netsh', 'wlan', 'show', 'profiles'],
                               capture_output=True, encoding='utf-8', errors='replace')
            profiles = re.findall(r"All User Profile\s*:\s*(.+)", r.stdout)
            if not profiles:
                self._warn("No saved Wi-Fi profiles found.")
                return
            self._sep("SAVED WI-FI NETWORKS")
            for profile in profiles:
                name = profile.strip()
                try:
                    p = subprocess.run(
                        ['netsh', 'wlan', 'show', 'profile', name, 'key=clear'],
                        capture_output=True, encoding='utf-8', errors='replace')
                    pwd_match = re.search(r"Key Content\s*:\s*(.+)", p.stdout)
                    pwd = pwd_match.group(1).strip() if pwd_match else "(no password / hidden)"
                    print(f"  {Fore.CYAN}{name:<35} {Fore.YELLOW}{pwd}")
                except Exception:
                    print(f"  {Fore.CYAN}{name:<35} {Fore.RED}(error retrieving password)")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_download(self, url: str):
        # If it looks like a package name (no scheme), route to install
        if url and not url.startswith('http://') and not url.startswith('https://'):
            pkg = url.lower().strip()
            if not IS_WINDOWS and pkg in self._pkg_native_catalog():
                self._pkg_download_native(package=pkg)
                return
            if pkg in self.PACKAGES:
                self._info(f"'{pkg}' is a package - routing to install...")
                self.cmd_install(pkg)
                return
            else:
                matches = [k for k in self.PACKAGES if k.startswith(pkg[:3])]
                hint = f"  Did you mean: {', '.join(matches[:5])}" if matches else ""
                self._err(f"'{pkg}' is not a URL and not a known package.{hint}")
                self._info("For packages use: install <name>  |  pkgs  to list all")
                self._info("For URLs use:     download https://example.com/file.exe")
                return
        try:
            self._info(f"Downloading: {Fore.YELLOW}{url}")
            from urllib.parse import urlparse
            fname = Path(urlparse(url).path).name or f"download_{int(time.time())}"
            fname = re.sub(r'[^A-Za-z0-9._-]+', '_', fname)
            dest = self.current_path / fname
            r = _lazy_requests().get(url, stream=True, timeout=30, allow_redirects=True,
                             headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
            r.raise_for_status()
            total = int(r.headers.get('content-length', 0))
            downloaded = 0
            with open(dest, 'wb') as f:
                for chunk in r.iter_content(chunk_size=65536):
                    if chunk:
                        f.write(chunk)
                        downloaded += len(chunk)
                        if total:
                            self.progress_bar(downloaded, total,
                                              prefix=f"{Fore.MAGENTA}Download:",
                                              suffix=f"{downloaded//1024}KB")
            print()
            self._ok(f"Saved to: {Fore.YELLOW}{dest}")
        except requests.HTTPError as e:
            self._err(f"HTTP error: {e}")
        except requests.ConnectionError:
            self._err("Connection failed.")
        except Exception as e:
            self._err(str(e))

    def cmd_net_scan(self):
        try:
            import ipaddress
            self._info("Scanning local network...")
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.connect(("8.8.8.8", 80))
            local_ip = s.getsockname()[0]
            s.close()
            network = '.'.join(local_ip.split('.')[:3])
            found = []
            lock = threading.Lock()

            def ping_host(ip):
                ping_args = ['ping', '-n', '1', '-w', '500', ip] if IS_WINDOWS else ['ping', '-c', '1', '-W', '1', ip]
                r = subprocess.run(ping_args,
                                   capture_output=True)
                if r.returncode == 0:
                    with lock:
                        found.append(ip)

            threads = []
            self._info(f"Scanning {network}.1 - {network}.254 ...")
            for i in range(1, 255):
                t = threading.Thread(target=ping_host, args=(f"{network}.{i}",), daemon=True)
                threads.append(t)
                t.start()
                if len(threads) % 50 == 0:
                    for th in threads[-50:]:
                        th.join(timeout=2)
            for t in threads:
                t.join(timeout=2)

            self._sep("LOCAL NETWORK DEVICES")
            for ip in sorted(found, key=lambda x: int(x.split('.')[-1])):
                try:
                    hostname = socket.gethostbyaddr(ip)[0]
                except Exception:
                    hostname = "N/A"
                marker = f"{Fore.GREEN}(YOU)" if ip == local_ip else ""
                print(f"  {Fore.CYAN}{ip:<16} {Fore.WHITE}{hostname} {marker}")
            print(f"\n  {Fore.YELLOW}Total: {len(found)} device(s) found.")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_dns_over_https(self):
        try:
            self._info("Enabling DNS over HTTPS (Cloudflare)...")
            ifaces = ['Ethernet', 'Wi-Fi', 'Local Area Connection']
            ok_count = 0
            for iface in ifaces:
                r1 = subprocess.run(
                    ['netsh', 'interface', 'ip', 'set', 'dns',
                     f'name={iface}', 'static', '1.1.1.1'],
                    capture_output=True)
                if r1.returncode == 0:
                    subprocess.run(
                        ['netsh', 'interface', 'ip', 'add', 'dns',
                         f'name={iface}', '1.0.0.1', 'index=2'],
                        capture_output=True)
                    ok_count += 1
            subprocess.run(['ipconfig', '/flushdns'], capture_output=True)
            if ok_count:
                self._ok("DNS set to Cloudflare 1.1.1.1 & 1.0.0.1. DNS cache flushed.")
            else:
                self._warn("No matching adapter found. Try: netsh interface show interface")
        except Exception as e:
            self._err(str(e))

