    def cmd_tempdel(self):
        temp_dirs = []
        if IS_WINDOWS:
            for env_key in ('TEMP', 'TMP'):
                val = os.environ.get(env_key)
                if val:
                    temp_dirs.append(Path(val))
            temp_dirs.append(Path(r"C:\Windows\Temp"))
        else:
            val = os.environ.get('TMPDIR')
            if val:
                temp_dirs.append(Path(val))
            temp_dirs.append(Path(tempfile.gettempdir()))
            temp_dirs.append(Path('/tmp'))
        total = 0
        self._info("Cleaning temporary files...")
        for td in temp_dirs:
            if not td.exists():
                continue
            for item in td.iterdir():
                try:
                    if item.is_file():
                        size = item.stat().st_size
                        item.unlink()
                        total += size
                    elif item.is_dir():
                        size = sum(f.stat().st_size for f in item.rglob('*') if f.is_file())
                        shutil.rmtree(item, ignore_errors=True)
                        total += size
                except Exception:
                    pass
        mb = total / (1024**2)
        self._ok(f"Freed {mb:.2f} MB of temporary files.")

