    def cmd_closeall(self):
        self._warn("Closing all user applications...")
        skipped = {'explorer.exe', 'taskmgr.exe', 'python.exe', 'python3.exe',
                   'cmd.exe', 'powershell.exe', 'conhost.exe', 'svchost.exe'}
        closed = 0
        current_pid = os.getpid()
        for proc in psutil.process_iter(['pid', 'name']):
            try:
                if proc.info['pid'] == current_pid:
                    continue
                pname = (proc.info['name'] or '').lower()
                if not pname or pname in skipped:
                    continue
                proc.terminate()
                closed += 1
                print(f"  {Fore.YELLOW}Closed: {proc.info['name']}")
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        self._ok(f"Closed {closed} application(s).")

    def _wcm_read(self):
        """Read camera/microphone usage from CapabilityAccessManager (HKCU)."""
        base = r"Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore"
        known = {
            'microsoft.gamingapp': 'Xbox',
            'microsoft.windowscamera': 'Camera',
            'microsoftteams': 'MS Teams',
            'msteams': 'MS Teams',
            'discordinc.discord': 'Discord',
            'google.chrome': 'Chrome',
            'microsoft.microsoftedge': 'Edge',
            'clipchamp.clipchamp': 'Clipchamp',
            'zoom.zoom': 'Zoom',
            'whatsapp.desktop': 'WhatsApp',
            'telegram.telegramdesktop': 'Telegram',
            'spotify.ab': 'Spotify',
        }
        out = []
        for dev, label in (('microphone', 'MIC'), ('webcam', 'CAM')):
            for nonpackaged in (False, True):
                path = f"{base}\\{dev}" + ("\\nonpackaged" if nonpackaged else "")
                try:
                    key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, path)
                except OSError:
                    continue
                try:
                    n = winreg.QueryInfoKey(key)[0]
                    for i in range(n):
                        try:
                            raw = winreg.EnumKey(key, i)
                        except OSError:
                            continue
                        try:
                            sk = winreg.OpenKey(key, raw)
                        except OSError:
                            continue
                        try:
                            try:
                                start = winreg.QueryValueEx(sk, 'LastUsedTimeStart')[0]
                            except OSError:
                                start = 0
                            try:
                                stop = winreg.QueryValueEx(sk, 'LastUsedTimeStop')[0]
                            except OSError:
                                stop = 0
                        finally:
                            winreg.CloseKey(sk)
                        if not start:
                            continue
                        if nonpackaged:
                            exe_path = raw.replace('#', '\\')
                            name = exe_path.rsplit('\\', 1)[-1]
                            path_disp = exe_path
                            family = ''
                        else:
                            family = raw.split('_')[0]
                            name = known.get(family.lower())
                            if not name:
                                name = family.rsplit('.', 1)[-1]
                            path_disp = ''
                        try:
                            when = datetime.fromtimestamp(start / 10_000_000 - 11_644_473_600)
                        except (OSError, OverflowError, ValueError):
                            when = None
                        out.append({
                            'device': label, 'name': name, 'path': path_disp,
                            'family': family, 'start': start, 'stop': stop,
                            'active': stop == 0, 'when': when,
                        })
                finally:
                    winreg.CloseKey(key)
        return out

    @staticmethod
    def _wcm_dur(seconds):
        secs = int(max(0, seconds))
        if secs < 60:
            return f"{secs}s"
        if secs < 3600:
            return f"{secs // 60}m {secs % 60:02d}s"
        return f"{secs // 3600}h {(secs % 3600) // 60:02d}m"

    def cmd_who_called_me(self, mode: str = None):
        """Camera/mic audit: who-called-me [all|now|mic|camera|watch]"""
        mode = (mode or 'all').lower()
        if mode == 'watch':
            self._wcm_watch()
            return
        only = None
        if mode in ('mic', 'microphone'):
            only = 'MIC'
        elif mode in ('cam', 'camera', 'webcam'):
            only = 'CAM'
        elif mode not in ('all', 'now', 'history'):
            self._err("Usage: who-called-me [all|now|mic|camera|watch]")
            self._info("no arg = full report · watch = live alerts · mic/camera = filter")
            return
        events = self._wcm_read()
        if only:
            events = [e for e in events if e['device'] == only]
        active = [e for e in events if e['active']]
        past = sorted((e for e in events if not e['active']),
                      key=lambda e: e['start'], reverse=True)

        if mode != 'history':
            self._sep("IN USE RIGHT NOW")
            if active:
                for e in active:
                    icon = Fore.CYAN + 'MIC' if e['device'] == 'MIC' else Fore.RED + 'CAM'
                    print(f"  {Fore.RED + Style.BRIGHT}!! {icon} {Fore.YELLOW + Style.BRIGHT}{e['name']}{Style.RESET_ALL}")
                    if e['path']:
                        print(f"     {Fore.LIGHTBLACK_EX}{e['path']}{Style.RESET_ALL}")
                print(f"\n  {Fore.RED + Style.BRIGHT}An app is using your device RIGHT NOW.{Style.RESET_ALL}")
            else:
                print(f"  {Fore.GREEN}Nothing is using your camera or microphone.")
            print()

        if mode != 'now':
            self._sep("LAST USE")
            if not past:
                print(f"  {Fore.YELLOW}(no recorded usage)")
            for e in past[:20]:
                devcolor = Fore.RED if e['device'] == 'CAM' else Fore.CYAN
                dur = self._wcm_dur((e['stop'] - e['start']) / 10_000_000)
                when = f"{e['when']:%Y-%m-%d %H:%M}" if e['when'] else '?'
                print(f"  {devcolor}[{e['device']}] {Fore.WHITE}{e['name']:<28} "
                      f"{when}  {Fore.GREEN}{dur}{Style.RESET_ALL}")
                if e['path']:
                    print(f"         {Fore.LIGHTBLACK_EX}{e['path']}{Style.RESET_ALL}")
            if len(past) > 20:
                print(f"  {Fore.YELLOW}... and {len(past) - 20} older entries")
        self._sep()
        if mode == 'all':
            self._info("Tip: 'who-called-me watch' alerts you the moment an app opens your mic/camera.")

    def _wcm_watch(self):
        self._info("Watching camera/microphone — Ctrl+C to stop.")
        time.sleep(0.5)
        prev_active = set()
        try:
            while True:
                events = self._wcm_read()
                now_active = {(e['device'], e['name'], e['path']) for e in events if e['active']}
                new = now_active - prev_active
                self._clear()
                self._ux_frame("DEVICE WATCH — MIC & CAMERA",
                               right=datetime.now().strftime('%H:%M:%S'))
                act = [e for e in events if e['active']]
                if act:
                    for e in act:
                        icon = Fore.CYAN + 'MIC' if e['device'] == 'MIC' else Fore.RED + 'CAM'
                        print(f"  {Fore.RED + Style.BRIGHT}!! {icon} in use: "
                              f"{Fore.YELLOW + Style.BRIGHT}{e['name']}{Style.RESET_ALL}")
                        if e['path']:
                            print(f"     {Fore.LIGHTBLACK_EX}{e['path']}{Style.RESET_ALL}")
                else:
                    print(f"  {Fore.GREEN}Idle — no app is using your camera or microphone.")
                if new:
                    print()
                    ts = datetime.now().strftime('%H:%M:%S')
                    for dev, name, p in new:
                        print(f"  {Fore.RED + Style.BRIGHT}[{ts}] ALERT: {name} just opened your "
                              f"{'microphone' if dev == 'MIC' else 'camera'}!{Style.RESET_ALL}")
                        if p:
                            print(f"    {Fore.LIGHTBLACK_EX}{p}{Style.RESET_ALL}")
                    for _ in range(3):
                        print('\a', end='', flush=True)
                        time.sleep(0.15)
                prev_active = now_active
                print(f"\n  {Fore.LIGHTBLACK_EX}polling every 2s · Ctrl+C to stop{Style.RESET_ALL}")
                time.sleep(2)
        except KeyboardInterrupt:
            print()
            self._ok("Stopped watching.")

    # ─────────────────────── power options ────────────────────────────────────

    def cmd_shutdown(self):
        if input(f"{Fore.YELLOW}Shut down the computer now? (Y/N): {Fore.WHITE}").strip().lower() != 'y':
            self._info("Shutdown cancelled.")
            return
        self._warn("Shutting down in 5 seconds... Press Ctrl+C to cancel.")
        try:
            for i in range(5, 0, -1):
                sys.stdout.write(f"\r{Fore.YELLOW}Shutdown in {i}s... ")
                sys.stdout.flush()
                time.sleep(1)
            if IS_WINDOWS:
                os.system("shutdown /s /t 0")
            else:
                os.system("shutdown -h now")
        except KeyboardInterrupt:
            print(f"\n{Fore.GREEN}Shutdown cancelled.")

    def cmd_sleep(self):
        if input(f"{Fore.YELLOW}Put the computer to sleep? (Y/N): {Fore.WHITE}").strip().lower() != 'y':
            self._info("Cancelled.")
            return
        self._info("Putting computer to sleep...")
        if IS_WINDOWS:
            os.system("rundll32.exe powrprof.dll,SetSuspendState 0,1,0")
        else:
            for cmd in (['systemctl', 'suspend'], ['pm-suspend']):
                if shutil.which(cmd[0]):
                    result = subprocess.run(cmd)
                    if result.returncode == 0:
                        self._ok("Sleep command completed.")
                    else:
                        self._err(f"Sleep command exited with code {result.returncode}.")
                    return
            self._err("No suspend tool found (systemctl / pm-suspend).")

    def cmd_lock(self):
        self._info("Locking workstation...")
        if IS_WINDOWS:
            ctypes.windll.user32.LockWorkStation()
        else:
            for cmd in (['xdg-screensaver', 'lock'],
                        ['loginctl', 'lock-session'],
                        ['gnome-screensaver', '-l']):
                if shutil.which(cmd[0]):
                    subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    break
            else:
                self._err("No lock tool found (install xdg-screensaver).")
                return
        self._ok("Workstation locked.")

    def cmd_logout(self):
        if input(f"{Fore.YELLOW}Log out of this session? (Y/N): {Fore.WHITE}").strip().lower() != 'y':
            self._info("Logout cancelled.")
            return
        self._warn("Logging out in 3 seconds...")
        time.sleep(3)
        if IS_WINDOWS:
            os.system("shutdown /l")
        else:
            for cmd in (['gnome-session-quit', '--logout', '--no-prompt'],
                        ['loginctl', 'terminate-user', self.username],
                        ['killall', '-u', self.username]):
                if shutil.which(cmd[0]):
                    subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    return
            self._err("Could not determine how to log out on this desktop.")

    # ─────────────────────── monitoring ───────────────────────────────────────

    def _check_device_usage(self, device_type: str):
        reg_map = {
            'camera': r"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\webcam",
            'microphone': r"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone",
        }
        reg_path = reg_map.get(device_type.lower())
        if not reg_path:
            self._err("Unknown device type.")
            return
        self._info(f"Checking {device_type} usage...")
        now = datetime.now()
        active = []
        try:
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, reg_path)
            for i in range(winreg.QueryInfoKey(key)[0]):
                try:
                    sub_name = winreg.EnumKey(key, i)
                    sub = winreg.OpenKey(key, sub_name)
                    try:
                        start_raw = winreg.QueryValueEx(sub, "LastUsedTimeStart")[0]
                        stop_raw  = winreg.QueryValueEx(sub, "LastUsedTimeStop")[0]
                        start_dt  = datetime.fromtimestamp(start_raw / 10_000_000 - 11_644_473_600)
                        stop_dt   = datetime.fromtimestamp(stop_raw  / 10_000_000 - 11_644_473_600)
                        if stop_raw <= start_raw and (now - start_dt).seconds < 3600:
                            active.append(sub_name)
                    except Exception:
                        pass
                    winreg.CloseKey(sub)
                except Exception:
                    pass
            winreg.CloseKey(key)
        except Exception as e:
            self._err(str(e))
            return

        self._sep(f"{device_type.upper()} USAGE")
        if active:
            for app in active:
                print(f"  {Fore.RED}[ACTIVE] {Fore.WHITE}{app}")
        else:
            self._ok(f"No apps currently detected using {device_type}.")
        self._sep()

    def cmd_cam_check(self):
        self._check_device_usage('camera')

    def cmd_mic_check(self):
        self._check_device_usage('microphone')

    def cmd_startup_check(self):
        self._info("Reading startup programs...")
        startup_keys = [
            (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
            (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"),
        ]
        self._sep("STARTUP PROGRAMS")
        for hive, path in startup_keys:
            hive_name = "HKCU" if hive == winreg.HKEY_CURRENT_USER else "HKLM"
            try:
                key = winreg.OpenKey(hive, path)
                count = winreg.QueryInfoKey(key)[1]
                for i in range(count):
                    try:
                        name, val, _ = winreg.EnumValue(key, i)
                        print(f"  {Fore.CYAN}[{hive_name}] {Fore.WHITE}{name:<30} {Fore.YELLOW}{val[:60]}")
                    except Exception:
                        pass
                winreg.CloseKey(key)
            except Exception:
                pass
        startup_folder = Path(f"C:\\Users\\{self.username}\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup")
        if startup_folder.exists():
            for item in startup_folder.iterdir():
                print(f"  {Fore.CYAN}[Folder] {Fore.WHITE}{item.name}")
        self._sep()

    def cmd_activeapps(self):
        self._info("Running applications:")
        self._sep("ACTIVE APPLICATIONS")
        seen = set()
        for proc in psutil.process_iter(['pid', 'name', 'status', 'cpu_percent', 'memory_info']):
            try:
                name = proc.info['name']
                if name in seen:
                    continue
                seen.add(name)
                cpu = proc.cpu_percent(interval=0)
                mem = proc.info['memory_info'].rss / (1024**2) if proc.info['memory_info'] else 0
                print(f"  {Fore.CYAN}{name:<35} {Fore.GREEN}CPU:{cpu:5.1f}% {Fore.YELLOW}MEM:{mem:6.1f}MB")
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        self._sep()

    def cmd_autorun(self, state: str):
        state = state.lower()
        if state not in ('on', 'off'):
            self._err("Usage: autorun <on/off>")
            return
        try:
            script_path = str(Path(sys.argv[0]).resolve())
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                 r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
                                 0, winreg.KEY_SET_VALUE)
            if state == 'on':
                winreg.SetValueEx(key, "EUFTerminal", 0, winreg.REG_SZ,
                                  f'"{sys.executable}" "{script_path}"')
                self._ok("EUF Terminal added to startup.")
            else:
                try:
                    winreg.DeleteValue(key, "EUFTerminal")
                    self._ok("EUF Terminal removed from startup.")
                except FileNotFoundError:
                    self._warn("Not found in startup.")
            winreg.CloseKey(key)
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── process tree & ports ─────────────────────────────

    def cmd_process_tree(self):
        self._info("Building process tree...")
        try:
            procs = {}
            children = {}
            for proc in psutil.process_iter(['pid', 'ppid', 'name', 'status', 'cpu_percent', 'memory_info']):
                try:
                    info = proc.info
                    procs[info['pid']] = info
                    children.setdefault(info['ppid'], []).append(info['pid'])
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass

            def render(pid, prefix="", is_last=True, visited=None):
                visited = visited or set()
                if pid in visited:
                    print(f"{Fore.YELLOW}{prefix}└─ [cycle detected: PID {pid}]{Style.RESET_ALL}")
                    return
                visited.add(pid)
                proc = procs.get(pid)
                if not proc:
                    return
                connector = "└─ " if is_last else "├─ "
                mem_mb = (proc['memory_info'].rss / (1024**2)) if proc.get('memory_info') else 0
                name   = proc.get('name') or '?'
                status = proc.get('status') or ''
                status_color = Fore.GREEN if status == 'running' else Fore.YELLOW
                print(f"{Fore.CYAN}{prefix}{connector}{Fore.WHITE}{name:<28}"
                      f" {Fore.BLUE}PID:{Fore.WHITE}{pid:<7}"
                      f" {status_color}{status:<10}"
                      f" {Fore.YELLOW}{mem_mb:5.1f}MB{Style.RESET_ALL}")
                kids = children.get(pid, [])
                ext  = "   " if is_last else "│  "
                for i, child_pid in enumerate(kids):
                    render(child_pid, prefix + ext, i == len(kids) - 1, visited)

            self._sep("PROCESS TREE  (name | PID | status | memory)")
            roots = [pid for pid in procs if procs[pid].get('ppid', 0) not in procs
                     or procs[pid].get('ppid', 0) == 0]
            roots = sorted(set(roots))
            for i, root_pid in enumerate(roots):
                render(root_pid, "", i == len(roots) - 1)
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_listening_ports(self):
        self._info("Scanning listening ports...")
        try:
            conns = psutil.net_connections(kind='inet')
            listening = [c for c in conns if c.status == psutil.CONN_LISTEN]
            if not listening:
                self._warn("No listening ports found.")
                return

            self._sep("LISTENING PORTS")
            print(f"  {Fore.CYAN}{'Port':<8} {'Proto':<7} {'Address':<22} {'PID':<8} {'Process'}{Style.RESET_ALL}")
            print(f"  {Fore.BLUE}{'-'*65}{Style.RESET_ALL}")

            seen = set()
            for c in sorted(listening, key=lambda x: x.laddr.port if x.laddr else 0):
                port  = c.laddr.port if c.laddr else '?'
                addr  = c.laddr.ip   if c.laddr else '?'
                proto = 'TCP' if c.type == socket.SOCK_STREAM else 'UDP'
                pid   = c.pid or 0
                key   = (port, proto)
                if key in seen:
                    continue
                seen.add(key)
                try:
                    pname = psutil.Process(pid).name() if pid else 'System'
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pname = 'N/A'
                port_color = Fore.GREEN if (isinstance(port, int) and port < 1024) else Fore.YELLOW
                print(f"  {port_color}{port:<8}{Fore.WHITE}{proto:<7}{addr:<22}"
                      f"{Fore.BLUE}{pid:<8}{Fore.CYAN}{pname}{Style.RESET_ALL}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── utilities ────────────────────────────────────────

    def cmd_timer(self, unit: str, value: str):
        try:
            val = int(value)
            if val <= 0:
                raise ValueError("Must be positive")
            unit_map = {'h': 3600, 'm': 60, 's': 1}
            if unit.lower() not in unit_map:
                self._err("Unit must be h, m, or s.")
                return
            secs = val * unit_map[unit.lower()]
            self._info(f"Timer set for {val}{unit.lower()} ({secs}s). Press Ctrl+C to cancel.")
            try:
                for elapsed in range(secs + 1):
                    remaining = secs - elapsed
                    m, s = divmod(remaining, 60)
                    h, m = divmod(m, 60)
                    label = f"{h:02d}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"
                    self.progress_bar(elapsed, secs, prefix=f"{Fore.MAGENTA}Timer:", suffix=label)
                    if elapsed < secs:
                        time.sleep(1)
                print()
                self._ok("Timer finished!")
                for _ in range(3):
                    print('\a', end='', flush=True)
                    time.sleep(0.3)
            except KeyboardInterrupt:
                print()
                self._warn("Timer cancelled.")
        except ValueError as e:
            self._err(f"Invalid value: {e}")
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── extra commands ───────────────────────────────────

    def cmd_sysinfo_full(self):
        try:
            self._sep("FULL SYSTEM SNAPSHOT")
            print(f"\n{Fore.YELLOW}[ OS ]{Style.RESET_ALL}")
            print(f"  {Fore.CYAN}Name      {Fore.WHITE}{self._get_windows_version()}")
            print(f"  {Fore.CYAN}Platform  {Fore.WHITE}{platform.architecture()[0]}  |  {platform.machine()}")
            print(f"  {Fore.CYAN}Node      {Fore.WHITE}{socket.gethostname()}")

            print(f"\n{Fore.YELLOW}[ CPU ]{Style.RESET_ALL}")
            print(f"  {Fore.CYAN}Model     {Fore.WHITE}{self._get_cpu_name_short()}")
            temps = {}
            try:
                temps = psutil.sensors_temperatures()
            except Exception:
                pass
            if temps:
                for sensor, readings in temps.items():
                    for r in readings:
                        print(f"  {Fore.CYAN}Temp ({sensor})  {Fore.WHITE}{r.current}°C")

            print(f"\n{Fore.YELLOW}[ RAM ]{Style.RESET_ALL}")
            vm = psutil.virtual_memory()
            sw = psutil.swap_memory()
            print(f"  {Fore.CYAN}Total     {Fore.WHITE}{vm.total/(1024**3):.2f} GB")
            print(f"  {Fore.CYAN}Used      {Fore.WHITE}{vm.used/(1024**3):.2f} GB  ({vm.percent}%)")
            print(f"  {Fore.CYAN}Available {Fore.WHITE}{vm.available/(1024**3):.2f} GB")
            print(f"  {Fore.CYAN}Swap      {Fore.WHITE}{sw.used/(1024**3):.2f} / {sw.total/(1024**3):.2f} GB")

            print(f"\n{Fore.YELLOW}[ DISKS ]{Style.RESET_ALL}")
            for part in psutil.disk_partitions():
                try:
                    usage = psutil.disk_usage(part.mountpoint)
                    bar_len = 20
                    filled = int(bar_len * usage.percent / 100)
                    bar = f"{Fore.GREEN}{'#'*filled}{Fore.RED}{'-'*(bar_len-filled)}{Fore.WHITE}"
                    print(f"  {Fore.CYAN}{part.device:<6}{Fore.WHITE} [{bar}] "
                          f"{usage.percent:5.1f}%  "
                          f"{usage.used/(1024**3):.1f}/{usage.total/(1024**3):.1f} GB  "
                          f"{Fore.YELLOW}{part.fstype}")
                except PermissionError:
                    pass

            print(f"\n{Fore.YELLOW}[ NETWORK INTERFACES ]{Style.RESET_ALL}")
            addrs = psutil.net_if_addrs()
            stats = psutil.net_if_stats()
            for iface, addr_list in addrs.items():
                st = stats.get(iface)
                up = f"{Fore.GREEN}UP" if st and st.isup else f"{Fore.RED}DOWN"
                for addr in addr_list:
                    if addr.family == socket.AF_INET:
                        print(f"  {Fore.CYAN}{iface:<20}{Fore.WHITE}{addr.address:<18}{up}{Style.RESET_ALL}")

            print(f"\n{Fore.YELLOW}[ GPU ]{Style.RESET_ALL}")
            print(f"  {Fore.CYAN}Name  {Fore.WHITE}{self._get_gpu()}")

            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_netstat(self):
        self._info("Reading network connections...")
        try:
            conns = psutil.net_connections(kind='inet')
            self._sep("NETWORK CONNECTIONS")
            print(f"  {Fore.CYAN}{'Proto':<6}{'Local':<26}{'Remote':<26}{'Status':<14}{'PID':<7}Process{Style.RESET_ALL}")
            print(f"  {Fore.BLUE}{'-'*90}{Style.RESET_ALL}")
            for c in sorted(conns, key=lambda x: x.laddr.port if x.laddr else 0):
                proto  = 'TCP' if c.type == socket.SOCK_STREAM else 'UDP'
                local  = f"{c.laddr.ip}:{c.laddr.port}" if c.laddr else '-'
                remote = f"{c.raddr.ip}:{c.raddr.port}" if c.raddr else '-'
                status = c.status or '-'
                pid    = c.pid or 0
                try:
                    pname = psutil.Process(pid).name() if pid else '-'
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pname = '-'
                s_color = Fore.GREEN if status == 'ESTABLISHED' else (
                          Fore.YELLOW if status == 'LISTEN' else Fore.WHITE)
                print(f"  {Fore.CYAN}{proto:<6}{Fore.WHITE}{local:<26}{remote:<26}"
                      f"{s_color}{status:<14}{Fore.BLUE}{pid:<7}{Fore.CYAN}{pname}{Style.RESET_ALL}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_kill(self, target: str):
        if input(f"{Fore.YELLOW}Kill process '{target}'? (Y/N): {Fore.WHITE}").strip().lower() != 'y':
            self._info("Cancelled.")
            return
        try:
            killed = 0
            try:
                pid = int(target)
                proc = psutil.Process(pid)
                name = proc.name()
                proc.kill()
                self._ok(f"Killed PID {pid} ({name})")
                return
            except ValueError:
                pass
            except psutil.NoSuchProcess:
                self._err(f"No process with PID {target}")
                return
            except psutil.AccessDenied:
                self._err(f"Access denied killing PID {target}. Try 'root' first.")
                return

            for proc in psutil.process_iter(['pid', 'name']):
                try:
                    pname = (proc.info['name'] or '').lower()
                    if pname and pname == target.lower():
                        proc.kill()
                        print(f"  {Fore.GREEN}Killed: {Fore.WHITE}{proc.info['name']} "
                              f"(PID {proc.info['pid']})")
                        killed += 1
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
            if killed == 0:
                self._err(f"No process found named '{target}'")
            else:
                self._ok(f"Killed {killed} process(es).")
        except Exception as e:
            self._err(str(e))

    def cmd_env(self, var: str = None):
        self._sep("ENVIRONMENT VARIABLES")
        env = os.environ
        items = sorted(env.items())
        if var:
            items = [(k, v) for k, v in items if var.lower() in k.lower()]
            if not items:
                self._warn(f"No variable matching '{var}'")
                return
        for k, v in items:
            print(f"  {Fore.CYAN}{k:<35}{Fore.WHITE}{v[:80]}")
        self._sep()

    def cmd_hash_file(self, name: str):
        import hashlib
        try:
            target = self._resolve(name)
            if not target.exists() or not target.is_file():
                self._err(f"File not found: {name}")
                return
            self._info(f"Hashing: {Fore.YELLOW}{target.name}")
            data = target.read_bytes()
            self._sep(f"HASHES: {target.name}")
            print(f"  {Fore.CYAN}MD5    {Fore.WHITE}{hashlib.md5(data).hexdigest()}")
            print(f"  {Fore.CYAN}SHA1   {Fore.WHITE}{hashlib.sha1(data).hexdigest()}")
            print(f"  {Fore.CYAN}SHA256 {Fore.WHITE}{hashlib.sha256(data).hexdigest()}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_clipboard(self, action: str = None, text: str = None):
        try:
            import subprocess as sp
            if not action or action.lower() == 'get':
                r = sp.run(['powershell', '-Command', 'Get-Clipboard'],
                           capture_output=True, encoding='utf-8', errors='replace')
                content = r.stdout.strip()
                self._sep("CLIPBOARD CONTENTS")
                print(f"{Fore.WHITE}{content if content else '(empty)'}")
                self._sep()
            elif action.lower() == 'set':
                if not text:
                    self._err("Usage: clipboard set <text>")
                    return
                escaped = text.replace("'", "''")
                r = sp.run(['powershell', '-Command', f"Set-Clipboard -Value '{escaped}'"],
                           capture_output=True, encoding='utf-8', errors='replace')
                if r.returncode == 0:
                    self._ok("Clipboard updated.")
                else:
                    self._err(f"Set-Clipboard failed: {(r.stderr or '').strip() or 'unknown error'}")
            elif action.lower() == 'clear':
                sp.run(['powershell', '-Command', 'Set-Clipboard -Value ""'],
                       capture_output=True)
                self._ok("Clipboard cleared.")
            else:
                self._err("Usage: clipboard [get|set <text>|clear]")
        except Exception as e:
            self._err(str(e))

    def cmd_sysmon(self):
        self._info("Live system monitor — Ctrl+C to stop.")
        bar_len = 24

        def bar(pct, length=bar_len):
            pct = max(0.0, min(100.0, float(pct)))
            filled = int(length * pct / 100)
            color = (Fore.GREEN if pct < 50 else
                     Fore.YELLOW if pct < 80 else Fore.RED)
            full, empty = '\u2588', '\u2591'
            return (f"{Fore.CYAN}[{color}{full * filled}"
                    f"{empty * (length - filled)}{Fore.CYAN}]{Style.RESET_ALL}")

        try:
            boot = psutil.boot_time()
        except Exception:
            boot = time.time()
        last_net = None
        last_disk = None
        last_t = None
        try:
            while True:
                cpu = psutil.cpu_percent(interval=0.3)
                vm = psutil.virtual_memory()
                try:
                    sw = psutil.swap_memory()
                except Exception:
                    sw = None
                try:
                    per_cpu = psutil.cpu_percent(interval=0.1, percpu=True)
                    cores_used = sum(1 for c in per_cpu if c > 5)
                except Exception:
                    per_cpu, cores_used = None, 0
                try:
                    freq = psutil.cpu_freq()
                    ghz = f"{freq.current / 1000:.1f} GHz" if freq else "n/a"
                except Exception:
                    ghz = "n/a"

                net = psutil.net_io_counters()
                disk = psutil.disk_io_counters()
                now = time.time()
                if last_net is not None and net is not None and (now - last_t) > 0:
                    dt = now - last_t
                    net_dl = (net.bytes_recv - last_net.bytes_recv) / dt / 1024 / 1024
                    net_up = (net.bytes_sent - last_net.bytes_sent) / dt / 1024 / 1024
                    if disk is not None and last_disk is not None:
                        disk_rd = (disk.read_bytes - last_disk.read_bytes) / dt / 1024 / 1024
                        disk_wr = (disk.write_bytes - last_disk.write_bytes) / dt / 1024 / 1024
                    else:
                        disk_rd = disk_wr = 0.0
                else:
                    net_dl = net_up = disk_rd = disk_wr = 0.0
                last_net, last_disk, last_t = net, disk, now

                up = int(now - boot)
                up_s = f"{up % 60:02d}"
                up_m = (up // 60) % 60
                up_h = up // 3600
                uptime = (f"{up_h}h {up_m:02d}m {up_s}s" if up_h else
                          f"{up_m}m {up_s}s")

                try:
                    host = f"{self.username}@{self.hostname}"
                except Exception:
                    host = socket.gethostname()
                try:
                    ncores = psutil.cpu_count() or 1
                    hw = f"{ncores} core(s)"
                except Exception:
                    hw = ""

                self._clear()
                date_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                row2 = (f"{Fore.WHITE}UP {Fore.GREEN}{uptime}{Style.RESET_ALL}"
                        f"  {Fore.MAGENTA}│{Style.RESET_ALL}  "
                        f"{Fore.WHITE}{date_str}{Style.RESET_ALL}"
                        f"{Fore.MAGENTA}   {ghz}{Style.RESET_ALL}")
                self._ux_frame("LIVE SYSTEM MONITOR", right=host, row2=row2)

                print(f"  {Fore.CYAN}CPU {bar(cpu)} {Fore.WHITE}{cpu:5.1f}%"
                      f"{Fore.BLUE}  {cores_used}/{ncores} busy{Style.RESET_ALL}")
                print(f"  {Fore.CYAN}RAM {bar(vm.percent)} {Fore.WHITE}{vm.percent:5.1f}%"
                      f"{Fore.WHITE}  {vm.used/(1024**3):5.1f} / {vm.total/(1024**3):.1f} GB"
                      f"{Style.RESET_ALL}")
                if sw and sw.total:
                    print(f"  {Fore.CYAN}SWP {bar(sw.percent)} {Fore.WHITE}{sw.percent:5.1f}%"
                          f"{Fore.WHITE}  {sw.used/(1024**3):5.1f} / {sw.total/(1024**3):.1f} GB"
                          f"{Style.RESET_ALL}")

                parts = []
                try:
                    for p in psutil.disk_partitions(all=False):
                        try:
                            u = psutil.disk_usage(p.mountpoint)
                            if p.mountpoint not in (i[0] for i in parts):
                                parts.append((p.mountpoint, u.percent, u.used, u.total))
                        except (PermissionError, OSError):
                            pass
                except Exception:
                    pass
                if parts:
                    print(f"\n  {Fore.MAGENTA}── DISK USAGE ──{Style.RESET_ALL}")
                    for mp, pct, used, total in parts[:4]:
                        letter = mp[:2].rstrip('\\')
                        print(f"  {Fore.CYAN}{letter:<5}{bar(pct, 18)} {Fore.WHITE}{pct:5.1f}%"
                              f"  {used/(1024**3):6.1f} / {total/(1024**3):.1f} GB{Style.RESET_ALL}")

                print(f"\n  {Fore.MAGENTA}── I/O ──{Style.RESET_ALL}")
                print(f"  {Fore.CYAN}Disk  {Fore.GREEN}\u25bc{Fore.WHITE} {disk_rd:6.2f} MB/s"
                      f"  {Fore.RED}\u25b2{Fore.WHITE} {disk_wr:6.2f} MB/s"
                      f"  {Fore.CYAN} Net  {Fore.GREEN}\u25bc{Fore.WHITE} {net_dl:6.2f} MB/s"
                      f"  {Fore.RED}\u25b2{Fore.WHITE} {net_up:6.2f} MB/s{Style.RESET_ALL}")

                WINDOWS_SYS = {
                    'system idle process', 'system',
                    'smss.exe', 'csrss.exe', 'wininit.exe', 'winlogon.exe',
                    'services.exe', 'lsass.exe', 'lsaiso.exe', 'svchost.exe',
                    'dwm.exe', 'fontdrvhost.exe', 'audiodg.exe', 'taskhostw.exe',
                    'sihost.exe', 'spoolsv.exe', 'wudfhost.exe', 'wmiprvse.exe',
                    'wmiaprvse.exe', 'runtimebroker.exe', 'conhost.exe',
                    'dllhost.exe', 'backgroundtaskhost.exe', 'taskmgr.exe',
                    'registry', 'memory compression',
                    'shellhost.exe', 'crossdeviceresume.exe', 'searchhost.exe',
                    'startmenuexperiencehost.exe', 'usercorebroker.exe',
                    'phoneexperiencehost.exe', 'searchui.exe', 'shellexperiencehost.exe',
                    'nvdisplay.container.exe', 'nvcontainer.exe', 'nvcontainerwrapper.exe',
                    'dashost.exe', 'wlanexthost.exe', 'wlanmediator.exe',
                }
                WINDOWS_DIRS = (
                    'c:\\windows',
                    'c:\\program files\\windowsapps',
                    'c:\\programdata\\microsoft',
                    'c:\\windows\\microsoft.net',
                    'c:\\windows\\systemapps',
                )
                top = []
                for pr in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_info', 'exe']):
                    try:
                        info = pr.info
                        pname = (info.get('name') or '').strip()
                        if pname.lower() in WINDOWS_SYS or not pname:
                            continue
                        exe = (info.get('exe') or '').lower()
                        if not exe or any(exe.startswith(d) for d in WINDOWS_DIRS):
                            continue
                        top.append((info['cpu_percent'] or 0,
                                    (info['memory_info'].rss or 0) / (1024**2),
                                    pname, info['pid']))
                    except Exception:
                        pass
                if top:
                    top.sort(reverse=True)
                    print(f"\n  {Fore.MAGENTA}── TOP 10 (non-Windows) ──{Style.RESET_ALL}")
                    for i, (cp, mem, name, pid) in enumerate(top[:10], 1):
                        print(f"  {Fore.CYAN}{i:<3}{Fore.YELLOW}{name:<22}"
                              f"{Fore.WHITE}{cp:6.1f}%{Style.RESET_ALL}"
                              f"  {Fore.GREEN}{mem:8.1f} MB{Style.RESET_ALL}"
                              f"  {Fore.BLUE}pid {pid}{Style.RESET_ALL}")
                time.sleep(0.5)
        except KeyboardInterrupt:
            self._clear()
            self._ok("Monitor stopped.")

    def cmd_health(self):
        self._info("System health dashboard — Ctrl+C to stop.")
        last_net = None
        last_t = None
        try:
            boot = psutil.boot_time()
        except Exception:
            boot = time.time()
        try:
            while True:
                cpu = psutil.cpu_percent(interval=0.4)
                vm = psutil.virtual_memory()
                try:
                    sw = psutil.swap_memory()
                except Exception:
                    sw = None
                try:
                    freq = psutil.cpu_freq()
                    ghz = f"{freq.current / 1000:.2f} GHz" if freq else "n/a"
                except Exception:
                    ghz = "n/a"
                try:
                    ncores = psutil.cpu_count() or 1
                    per_cpu = psutil.cpu_percent(interval=0.1, percpu=True)
                    busy = sum(1 for c in per_cpu if c > 5)
                except Exception:
                    ncores, busy = 1, 0
                temps = ""
                try:
                    ts = psutil.sensors_temperatures()
                    rds = [r for rds in ts.values() for r in rds]
                    if rds:
                        temps = f"  ·  {max(r.current for r in rds):.0f}°C"
                except Exception:
                    temps = ""

                net_dl = net_up = 0.0
                try:
                    net = psutil.net_io_counters()
                    now = time.time()
                    if last_net is not None and (now - last_t) > 0:
                        dt = now - last_t
                        net_dl = (net.bytes_recv - last_net.bytes_recv) / dt / 1024 / 1024
                        net_up = (net.bytes_sent - last_net.bytes_sent) / dt / 1024 / 1024
                    last_net, last_t = net, now
                except Exception:
                    pass

                parts = []
                try:
                    for p in psutil.disk_partitions(all=False):
                        mp = p.mountpoint
                        if mp in (i[0] for i in parts):
                            continue
                        try:
                            u = psutil.disk_usage(mp)
                            parts.append((mp, u))
                        except (PermissionError, OSError):
                            pass
                except Exception:
                    pass

                batt_lines = None
                try:
                    b = psutil.sensors_battery()
                    if b is not None:
                        pct_color = (Fore.GREEN if b.percent > 50 else
                                     Fore.YELLOW if b.percent > 20 else Fore.RED)
                        bl = [f"{self._ux_bar(b.percent)} "
                              f"{pct_color}{b.percent:.0f}%{Style.RESET_ALL}"]
                        if b.power_plugged:
                            bl.append(f"Power: {Fore.GREEN}AC (charging)"
                                      f"{Style.RESET_ALL}")
                        else:
                            bl.append(f"Power: {Fore.RED}Discharging"
                                      f"{Style.RESET_ALL}")
                        if (not b.power_plugged and b.secsleft > 0
                                and b.secsleft != psutil.POWER_TIME_UNKNOWN):
                            bh, bm = divmod(int(b.secsleft // 60), 60)
                            bl.append(f"Remaining: {bh}h {bm}m")
                        batt_lines = bl
                except Exception:
                    batt_lines = None

                up = int(time.time() - boot)
                up_s = f"{up % 60:02d}"
                up_m = (up // 60) % 60
                up_h = up // 3600
                uptime = (f"{up_h}h {up_m:02d}m {up_s}s" if up_h else
                          f"{up_m}m {up_s}s")
                date_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

                self._clear()
                row2 = (f"{Fore.WHITE}UP {Fore.GREEN}{uptime}{Style.RESET_ALL}"
                        f"  {Fore.MAGENTA}│{Style.RESET_ALL}  "
                        f"{Fore.WHITE}{date_str}{Style.RESET_ALL}"
                        f"{Fore.MAGENTA}  {ghz}{Style.RESET_ALL}")
                self._ux_frame("SYSTEM HEALTH",
                               right=datetime.now().strftime('%H:%M:%S'),
                               row2=row2)
                print(self._ux_box(
                    "CPU",
                    [f"{self._ux_bar(cpu)} {cpu:5.1f}%",
                     f"{ghz}  ·  {busy}/{ncores} cores busy{temps}"],
                    accent=Fore.GREEN))
                print()
                mem_lines = [f"RAM {self._ux_bar(vm.percent)} "
                             f"{vm.percent:5.1f}%",
                             f"{vm.used/(1024**3):.1f} / "
                             f"{vm.total/(1024**3):.1f} GB"]
                if sw and sw.total:
                    mem_lines.append(f"Swap {sw.used/(1024**3):.1f} / "
                                     f"{sw.total/(1024**3):.1f} GB  "
                                     f"({sw.percent:.1f}%)")
                print(self._ux_box("MEMORY", mem_lines, accent=Fore.YELLOW))
                print()
                disk_lines = []
                for p, u in parts[:3]:
                    label = p[:2].rstrip('\\')
                    disk_lines.append(
                        f"{label:<3} {self._ux_bar(u.percent, 18)} {u.percent:5.1f}%"
                        f"  {u.used/(1024**3):6.1f} / {u.total/(1024**3):.1f} GB")
                if not disk_lines:
                    disk_lines = ["(no partitions found)"]
                print(self._ux_box("STORAGE", disk_lines, accent=Fore.CYAN))
                print()
                print(self._ux_box(
                    "NETWORK",
                    [f"{Fore.GREEN}\u25bc{Style.RESET_ALL} {net_dl:6.2f} MB/s down "
                     f"  {Fore.RED}\u25b2{Style.RESET_ALL} {net_up:6.2f} MB/s up"],
                    accent=Fore.MAGENTA))
                if batt_lines:
                    print()
                    print(self._ux_box("BATTERY", batt_lines, accent=Fore.GREEN))

                top = []
                for pr in psutil.process_iter(
                        ['pid', 'name', 'cpu_percent', 'memory_info']):
                    try:
                        top.append((pr.info['cpu_percent'] or 0,
                                    (pr.info['memory_info'].rss or 0) / (1024**2),
                                    pr.info['name'], pr.info['pid']))
                    except Exception:
                        pass
                top.sort(reverse=True)
                rows = []
                for i, (cp, mem, name, pid) in enumerate(top[:5], 1):
                    rows.append([f"{i}", f"{name[:12]}",
                                 f"{mem:.0f} MB", f"{cp:.1f}%", f"{pid}"])
                if rows:
                    print()
                    print(self._ux_box(
                        "TOP PROCESSES",
                        self._ux_table(["#", "Process", "Memory", "CPU", "PID"],
                                       rows, width=54),
                        accent=Fore.BLUE))
        except KeyboardInterrupt:
            self._clear()
            self._ok("Health monitor stopped.")

    # ─────────────────────── net-connections ────────────────────────────────

    def cmd_net_connections(self, filter_proto: str = None):
        self._info("Showing active network connections with process info...")
        try:
            conns = psutil.net_connections(kind='inet')
            self._sep("NET CONNECTIONS")
            print(f"  {Fore.CYAN}{'Proto':<6}{'Local':<24}{'Remote':<24}{'Status':<14}{'PID':<7}{'Process':<20}{'Path'}{Style.RESET_ALL}")
            print(f"  {Fore.BLUE}{'-'*100}{Style.RESET_ALL}")
            count = 0
            for c in sorted(conns, key=lambda x: x.laddr.port if x.laddr else 0):
                proto = 'TCP' if c.type == socket.SOCK_STREAM else 'UDP'
                if filter_proto and proto.lower() != filter_proto.lower():
                    continue
                local = f"{c.laddr.ip}:{c.laddr.port}" if c.laddr else '-'
                remote = f"{c.raddr.ip}:{c.raddr.port}" if c.raddr else '-'
                status = c.status or '-'
                pid = c.pid or 0
                pname = '-'
                ppath = ''
                try:
                    proc = psutil.Process(pid)
                    pname = proc.name()
                    ppath = proc.exe()[:40]
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
                s_color = (Fore.GREEN if status == 'ESTABLISHED' else
                           Fore.YELLOW if status == 'LISTEN' else Fore.WHITE)
                print(f"  {Fore.CYAN}{proto:<6}{Fore.WHITE}{local:<24}{remote:<24}"
                      f"{s_color}{status:<14}{Fore.BLUE}{pid:<7}"
                      f"{Fore.CYAN}{pname:<20}{Fore.YELLOW}{ppath}{Style.RESET_ALL}")
                count += 1
            print(f"\n  {Fore.GREEN}Total: {count} connection(s){Style.RESET_ALL}")
            self._sep()
        except psutil.AccessDenied:
            self._err("Access denied. Try 'root' first for full connection list.")
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── system-restore ─────────────────────────────────

    def cmd_system_restore(self, action: str = None):
        self._info("System Restore Manager...")
        if not action:
            action = "list"
        action = action.lower()

        if action == 'list':
            self._sep("SYSTEM RESTORE POINTS")
            try:
                r = subprocess.run(
                    ['powershell', '-Command',
                     'Get-ComputerRestorePoint | Select-Object SequenceNumber, '
                     'CreationTime, Description, RestorePointType | '
                     'Format-Table -AutoSize'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=15)
                if r.returncode == 0 and r.stdout.strip():
                    print(f"{Fore.WHITE}{r.stdout}")
                else:
                    self._warn("No restore points found or access denied.")
            except Exception as e:
                self._err(f"Failed to list restore points: {e}")
            self._sep()

        elif action == 'create':
            self._warn("Creating a system restore point (requires admin)...")
            restore_desc = f"EUF Terminal Restore {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
            try:
                r = subprocess.run(
                    ['powershell', '-Command',
                     f'Enable-ComputerRestore -Drive "C:\\"; '
                     f'Checkpoint-Computer -Description "{restore_desc}" '
                     '-RestorePointType MODIFY_SETTINGS'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=30)
                if r.returncode == 0:
                    self._ok("Restore point created successfully.")
                else:
                    err = r.stderr.strip() if r.stderr else r.stdout.strip()
                    if 'Access Denied' in err or 'elevation' in err.lower():
                        self._err("Admin privileges required. Use 'root' first.")
                    else:
                        self._err(f"Failed: {err[:200]}")
            except Exception as e:
                self._err(f"Failed to create restore point: {e}")

        elif action == 'status':
            self._sep("SYSTEM RESTORE STATUS")
            try:
                r = subprocess.run(
                    ['powershell', '-Command',
                     'Get-ComputerRestoreStatus | Format-List *'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=10)
                if r.returncode == 0 and r.stdout.strip():
                    print(f"{Fore.WHITE}{r.stdout}")
                else:
                    self._warn("Could not retrieve restore status.")
            except Exception as e:
                self._err(f"Failed: {e}")
            self._sep()

        else:
            self._err("Usage: system-restore <list|create|status>")
            print(f"  {Fore.CYAN}list{Style.RESET_ALL}   - List all restore points")
            print(f"  {Fore.CYAN}create{Style.RESET_ALL} - Create a new restore point")
            print(f"  {Fore.CYAN}status{Style.RESET_ALL} - Check if System Restore is enabled")

    # ─────────────────────── gpu-monitor ────────────────────────────────────

    def cmd_gpu_monitor(self):
        self._info("Live GPU monitor — Ctrl+C to stop.")

        def bar(pct, length=20):
            pct = max(0.0, min(100.0, float(pct)))
            filled = int(length * pct / 100)
            color = (Fore.GREEN if pct < 50 else
                     Fore.YELLOW if pct < 80 else Fore.RED)
            return (f"{Fore.CYAN}[{color}{'█' * filled}"
                    f"{'░' * (length - filled)}{Fore.CYAN}]{Style.RESET_ALL}")

        def get_gpu_info():
            gpus = []
            try:
                r = subprocess.run(
                    ['powershell', '-Command',
                     'nvidia-smi --query-gpu=name,temperature.gpu,utilization.gpu,'
                     'utilization.memory,memory.used,memory.total,power.draw,'
                     'fan.speed --format=csv,noheader,nounits'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                if r.returncode == 0 and r.stdout.strip():
                    for line in r.stdout.strip().splitlines():
                        parts = [p.strip() for p in line.split(',')]
                        if len(parts) >= 7:
                            gpus.append({
                                'name': parts[0],
                                'temp': float(parts[1]) if parts[1] else 0,
                                'gpu_util': float(parts[2]) if parts[2] else 0,
                                'mem_util': float(parts[3]) if parts[3] else 0,
                                'mem_used': float(parts[4]) if parts[4] else 0,
                                'mem_total': float(parts[5]) if parts[5] else 0,
                                'power': float(parts[6]) if parts[6] else 0,
                                'fan': float(parts[7]) if len(parts) > 7 and parts[7] else 0,
                            })
                    return gpus
            except Exception:
                pass

            try:
                r = subprocess.run(
                    ['powershell', '-Command',
                     'Get-CimInstance Win32_VideoController | Select-Object '
                     'Name, AdapterRAM, DriverVersion, '
                     'CurrentHorizontalResolution, CurrentVerticalResolution | '
                     'Format-List'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                if r.returncode == 0 and r.stdout.strip():
                    current = {}
                    for line in r.stdout.splitlines():
                        line = line.strip()
                        if ':' in line:
                            k, v = line.split(':', 1)
                            current[k.strip()] = v.strip()
                        elif current:
                            gpus.append({
                                'name': current.get('Name', 'Unknown'),
                                'temp': 0,
                                'gpu_util': 0,
                                'mem_util': 0,
                                'mem_used': 0,
                                'mem_total': int(current.get('AdapterRAM', '0') or '0') / (1024**2),
                                'power': 0,
                                'fan': 0,
                                'driver': current.get('DriverVersion', 'N/A'),
                                'resolution': f"{current.get('CurrentHorizontalResolution', '?')}x{current.get('CurrentVerticalResolution', '?')}",
                            })
                            current = {}
                    if current:
                        gpus.append({
                            'name': current.get('Name', 'Unknown'),
                            'temp': 0,
                            'gpu_util': 0,
                            'mem_util': 0,
                            'mem_used': 0,
                            'mem_total': int(current.get('AdapterRAM', '0') or '0') / (1024**2),
                            'power': 0,
                            'fan': 0,
                            'driver': current.get('DriverVersion', 'N/A'),
                            'resolution': f"{current.get('CurrentHorizontalResolution', '?')}x{current.get('CurrentVerticalResolution', '?')}",
                        })
                    return gpus
            except Exception:
                pass
            return gpus

        try:
            while True:
                gpus = get_gpu_info()
                self._clear()
                self._ux_frame("GPU MONITOR",
                               right=datetime.now().strftime('%H:%M:%S'))

                if not gpus:
                    print(f"  {Fore.YELLOW}No NVIDIA GPU detected via nvidia-smi.{Style.RESET_ALL}")
                    try:
                        r = subprocess.run(
                            ['powershell', '-Command',
                             'Get-CimInstance Win32_VideoController | '
                             'Select-Object Name, AdapterRAM, DriverVersion, '
                             'CurrentHorizontalResolution, CurrentVerticalResolution'],
                            capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                        if r.stdout.strip():
                            print(f"\n  {Fore.CYAN}Detected GPU(s):{Style.RESET_ALL}")
                            print(f"{Fore.WHITE}{r.stdout}")
                    except Exception:
                        pass
                    print(f"\n  {Fore.YELLOW}Install NVIDIA drivers + nvidia-smi for live GPU stats.{Style.RESET_ALL}")
                    print(f"  {Fore.CYAN}Tip: nvidia-smi comes with GeForce Experience or CUDA Toolkit.{Style.RESET_ALL}")
                    time.sleep(5)
                    continue

                for i, g in enumerate(gpus):
                    name = g.get('name', 'Unknown GPU')[:40]
                    print(f"  {Fore.BLUE + Style.BRIGHT}GPU {i+1}: {Fore.WHITE}{name}{Style.RESET_ALL}")
                    if g.get('temp', 0) > 0:
                        temp = g['temp']
                        tc = (Fore.GREEN if temp < 60 else
                              Fore.YELLOW if temp < 80 else Fore.RED)
                        print(f"    {Fore.CYAN}Temp:   {tc}{temp:.0f}°C{Style.RESET_ALL}")
                    if g.get('gpu_util', 0) > 0:
                        print(f"    {Fore.CYAN}GPU:    {bar(g['gpu_util'])} {Fore.WHITE}{g['gpu_util']:5.1f}%{Style.RESET_ALL}")
                    if g.get('mem_total', 0) > 0:
                        mu = g.get('mem_util', 0)
                        print(f"    {Fore.CYAN}Memory: {bar(mu)} {Fore.WHITE}{g['mem_used']:.0f} / {g['mem_total']:.0f} MB{Style.RESET_ALL}")
                    if g.get('power', 0) > 0:
                        print(f"    {Fore.CYAN}Power:  {Fore.WHITE}{g['power']:.1f} W{Style.RESET_ALL}")
                    if g.get('fan', 0) > 0:
                        print(f"    {Fore.CYAN}Fan:    {Fore.WHITE}{g['fan']:.0f}%{Style.RESET_ALL}")
                    if g.get('driver'):
                        print(f"    {Fore.CYAN}Driver: {Fore.WHITE}{g['driver']}{Style.RESET_ALL}")
                    if g.get('resolution'):
                        print(f"    {Fore.CYAN}Screen: {Fore.WHITE}{g['resolution']}{Style.RESET_ALL}")
                    print()
                time.sleep(1)
        except KeyboardInterrupt:
            self._clear()
            self._ok("GPU monitor stopped.")

    # ─────────────────────── qr-code ───────────────────────────────────────

    def cmd_qr_code(self, text: str = None, filename: str = None):
        if not text:
            self._err("Usage: qr-code <text|url> [filename]")
            return
        try:
            import qrcode
            from PIL import Image
        except ImportError:
            self._info("Installing required packages...")
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'qrcode', 'pillow', '--quiet'])
            import qrcode
            from PIL import Image

        try:
            if not filename:
                safe_name = re.sub(r'[^\w\-_]', '_', text[:30])
                filename = f"{safe_name}_qr.png"
            dest = self.current_path / filename

            qr = qrcode.QRCode(
                version=1,
                error_correction=qrcode.constants.ERROR_CORRECT_H,
                box_size=10,
                border=4,
            )
            qr.add_data(text)
            qr.make(fit=True)
            img = qr.make_image(fill_color="black", back_color="white")
            img.save(str(dest))

            self._ok(f"QR code saved: {Fore.YELLOW}{dest}")
            print(f"  {Fore.CYAN}Content: {Fore.WHITE}{text[:80]}")
            print(f"  {Fore.CYAN}Size:    {Fore.WHITE}{img.pixel_size[0]}x{img.pixel_size[1]} px")

            # show in terminal as ASCII art
            matrix = qr.get_matrix()
            print(f"\n  {Fore.CYAN}Preview:{Style.RESET_ALL}")
            for row in matrix:
                line = ''.join('██' if cell else '  ' for cell in row)
                print(f"    {Fore.WHITE}{line}{Style.RESET_ALL}")
            print()

            try:
                os.startfile(str(dest))
                self._info(f"Opened {filename}")
            except Exception:
                pass
        except Exception as e:
            self._err(f"Failed to generate QR code: {e}")

