    def cmd_sshtunnel(self, remote_host: str = None, remote_port: str = None,
                      local_port: str = None):
        if not remote_host or not remote_port:
            self._err("Usage: sshtunnel <remote_host> <remote_port> [local_port]")
            self._info("Creates a local port forward: localhost:local_port -> remote_host:remote_port")
            self._info("Example: sshtunnel 192.168.1.100 3389 13389")
            return
        try:
            local_port = local_port or str(int(remote_port) + 1000)
        except ValueError:
            self._err("Ports must be numbers.")
            return
        self._info(f"Opening SSH tunnel: localhost:{local_port} -> {remote_host}:{remote_port}")
        self._info("Press Ctrl+C to stop the tunnel.\n")
        try:
            subprocess.call(['ssh', '-L', f'{local_port}:{remote_host}:{remote_port}',
                             '-N', remote_host])
            self._ok(f"Tunnel closed: localhost:{local_port} -> {remote_host}:{remote_port}")
        except FileNotFoundError:
            self._warn("SSH not found in PATH. Trying PowerShell SSH...")
            try:
                cmd = f'ssh -L {local_port}:{remote_host}:{remote_port} -N {remote_host}'
                self._info(f"Run this manually: {cmd}")
                subprocess.call(['powershell', '-Command', cmd])
            except Exception as e:
                self._err(f"SSH not available: {e}")
                self._info("Install OpenSSH from Windows Settings > Apps > Optional Features")
        except KeyboardInterrupt:
            self._ok("Tunnel stopped.")
        except Exception as e:
            self._err(f"Tunnel failed: {e}")

    def cmd_port_forward(self, local_port: str = None, remote_host: str = None,
                         remote_port: str = None):
        if not local_port or not remote_host or not remote_port:
            self._err("Usage: port-forward <local_port> <remote_host> <remote_port>")
            self._info("Forward local port to a remote host:port")
            self._info("Example: port-forward 8080 google.com 80")
            return
        self._info(f"Port forward: localhost:{local_port} -> {remote_host}:{remote_port}")
        self._info("Press Ctrl+C to stop.\n")
        try:
            import socket as _sock
            server = _sock.socket(_sock.AF_INET, _sock.SOCK_STREAM)
            server.setsockopt(_sock.SOL_SOCKET, _sock.SO_REUSEADDR, 1)
            server.bind(('127.0.0.1', int(local_port)))
            server.listen(5)
            self._ok(f"Listening on localhost:{local_port}")

            def forward(src, dst):
                try:
                    while True:
                        data = src.recv(4096)
                        if not data:
                            break
                        dst.sendall(data)
                except Exception:
                    pass
                finally:
                    src.close()
                    dst.close()

            def accept():
                while True:
                    client, addr = server.accept()
                    remote = _sock.socket(_sock.AF_INET, _sock.SOCK_STREAM)
                    try:
                        remote.connect((remote_host, int(remote_port)))
                        threading.Thread(target=forward, args=(client, remote), daemon=True).start()
                        threading.Thread(target=forward, args=(remote, client), daemon=True).start()
                    except Exception as e:
                        self._err(f"Connection to {remote_host}:{remote_port} failed: {e}")
                        remote.close()
                        client.close()

            t = threading.Thread(target=accept, daemon=True)
            t.start()
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            self._ok("Port forward stopped.")
        except Exception as e:
            self._err(f"Failed: {e}")

    def cmd_ssl_check(self, host: str = None):
        if not host:
            self._err("Usage: ssl-check <hostname>")
            self._info("Example: ssl-check google.com")
            return
        self._info(f"Checking SSL certificate for {Fore.YELLOW}{host}{Fore.WHITE}...")
        try:
            import ssl
            ctx = ssl.create_default_context()
            with ctx.wrap_socket(socket.socket(), server_hostname=host) as s:
                s.settimeout(10)
                s.connect((host, 443))
                cert = s.getpeercert()
                version = s.version()
                cipher = s.cipher()
            self._sep(f"SSL CERTIFICATE: {host}")
            print(f"  {Fore.CYAN}Subject:{Style.RESET_ALL}   {cert.get('subject', 'N/A')}")
            print(f"  {Fore.CYAN}Issuer:{Style.RESET_ALL}    {cert.get('issuer', 'N/A')}")
            print(f"  {Fore.CYAN}Serial:{Style.RESET_ALL}    {cert.get('serialNumber', 'N/A')}")
            not_before = cert.get('notBefore', 'N/A')
            not_after = cert.get('notAfter', 'N/A')
            print(f"  {Fore.CYAN}Valid From:{Style.RESET_ALL} {not_before}")
            print(f"  {Fore.CYAN}Valid To:{Style.RESET_ALL}   {not_after}")
            san = cert.get('subjectAltName', [])
            if san:
                domains = [d[1] for d in san[:10]]
                print(f"  {Fore.CYAN}SANs:{Style.RESET_ALL}      {', '.join(domains)}")
                if len(san) > 10:
                    print(f"              ... and {len(san)-10} more")
            print(f"  {Fore.CYAN}TLS:{Style.RESET_ALL}       {version}")
            print(f"  {Fore.CYAN}Cipher:{Style.RESET_ALL}    {cipher[0]} ({cipher[2]} bit)")
            self._sep()
            self._ok("Certificate is valid.")
        except ssl.SSLCertVerificationError as e:
            self._err(f"Certificate verification FAILED: {e}")
        except Exception as e:
            self._err(f"SSL check failed: {e}")

    def cmd_banner_grab(self, host: str = None, port: str = None):
        if not host:
            self._err("Usage: banner-grab <host> [port]")
            self._info("Example: banner-grab 192.168.1.1 22")
            return
        try:
            ports = [int(port)] if port else [21, 22, 23, 25, 80, 110, 143, 443, 993, 995, 3306, 3389, 8080]
        except ValueError:
            self._err("Port must be a number.")
            return
        self._info(f"Grabbing banners from {Fore.YELLOW}{host}{Fore.WHITE}...\n")
        print(f"  {Fore.CYAN}{'Port':<8}{'Service':<14}Banner{Style.RESET_ALL}")
        print(f"  {Fore.BLUE}{'-'*70}{Style.RESET_ALL}")
        for p in ports:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(2)
                s.connect((host, p))
                try:
                    s.send(b'HEAD / HTTP/1.0\r\nHost: %b\r\n\r\n' % host.encode())
                except Exception:
                    pass
                banner = s.recv(1024).decode('utf-8', errors='replace').strip()
                s.close()
                try:
                    svc = socket.getservbyport(p, 'tcp')
                except OSError:
                    svc = 'unknown'
                if banner:
                    print(f"  {Fore.GREEN}{p:<8}{Fore.WHITE}{svc:<14}{Fore.YELLOW}{banner[:60]}{Style.RESET_ALL}")
                else:
                    print(f"  {Fore.RED}{p:<8}{Fore.WHITE}{svc:<14}(no banner){Style.RESET_ALL}")
            except Exception:
                pass
        print()

    def cmd_dns_recon(self, domain: str = None):
        if not domain:
            self._err("Usage: dns-recon <domain>")
            self._info("Example: dns-recon example.com")
            return
        self._info(f"DNS reconnaissance for {Fore.YELLOW}{domain}{Fore.WHITE}...\n")
        self._sep(f"DNS RECON: {domain}")
        try:
            ip = socket.gethostbyname(domain)
            print(f"  {Fore.CYAN}A Record:{Style.RESET_ALL}     {Fore.WHITE}{ip}{Style.RESET_ALL}")
        except Exception:
            print(f"  {Fore.RED}A Record:     failed{Style.RESET_ALL}")

        record_types = ['NS', 'MX', 'TXT', 'SOA']
        for rtype in record_types:
            try:
                r = subprocess.run(
                    ['nslookup', '-type=' + rtype, domain],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                lines = [l.strip() for l in r.stdout.split('\n')
                         if 'internet address' in l.lower() or 'nameserver' in l.lower()
                         or 'mail exchanger' in l.lower() or 'text' in l.lower()]
                if lines:
                    for l in lines[:5]:
                        print(f"  {Fore.CYAN}{rtype} Record:{Style.RESET_ALL} {Fore.WHITE}{l}{Style.RESET_ALL}")
                else:
                    print(f"  {Fore.CYAN}{rtype} Record:{Style.RESET_ALL} {Fore.YELLOW}(none found){Style.RESET_ALL}")
            except Exception:
                pass
        try:
            r = subprocess.run(['nslookup', '-type=AAAA', domain],
                               capture_output=True, encoding='utf-8', errors='replace', timeout=8)
            for l in r.stdout.split('\n'):
                if 'address' in l.lower() and ':' in l:
                    print(f"  {Fore.CYAN}AAAA:{Style.RESET_ALL}       {Fore.WHITE}{l.strip()}{Style.RESET_ALL}")
        except Exception:
            pass
        self._sep()

