    def cmd_mimetype(self, name: str):
        try:
            target = self._resolve(name)
            if not target.exists():
                self._err(f"Not found: {name}")
                return
            raw = target.read_bytes()[:4096]
            mime = 'application/octet-stream'
            if raw.startswith(b'\x89PNG'):
                mime = 'image/png'
            elif raw.startswith(b'\xff\xd8\xff'):
                mime = 'image/jpeg'
            elif raw.startswith(b'GIF8'):
                mime = 'image/gif'
            elif raw.startswith(b'%PDF'):
                mime = 'application/pdf'
            elif raw.startswith(b'PK\x03\x04'):
                mime = 'application/zip'
            elif raw.startswith(b'\x1f\x8b'):
                mime = 'application/gzip'
            elif raw.startswith(b'\x7fELF'):
                mime = 'application/x-executable'
            elif raw.startswith(b'RIFF') and raw[8:12] == b'WEBP':
                mime = 'image/webp'
            elif raw.startswith(b'\x00\x00\x01\x00'):
                mime = 'image/x-icon'
            elif raw.startswith(b'{') or raw.startswith(b'['):
                mime = 'application/json'
            elif raw.startswith(b'<?xml'):
                mime = 'application/xml'
            elif raw.startswith(b'<!DOCTYPE') or raw.startswith(b'<html'):
                mime = 'text/html'
            else:
                try:
                    raw.decode('utf-8')
                    mime = 'text/plain'
                except UnicodeDecodeError:
                    pass
            self._sep(f"MIMETYPE: {target.name}")
            print(f"  {Fore.CYAN}File : {Fore.WHITE}{target}")
            print(f"  {Fore.CYAN}MIME : {Fore.GREEN}{mime}")
            print(f"  {Fore.CYAN}Size : {Fore.WHITE}{self._fmt_size(target.stat().st_size)}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_dirstat(self, path: str = None):
        try:
            target = self._resolve(path) if path else self.current_path
            if not target.is_dir():
                self._err(f"Not a directory: {path or '.'}")
                return
            total_size = 0
            file_count = 0
            dir_count = 0
            max_depth = 0
            largest_file = (0, None)
            ext_counts = {}
            for p in target.rglob('*'):
                try:
                    rel = p.relative_to(target)
                    depth = len(rel.parts)
                    if p.is_dir():
                        dir_count += 1
                        max_depth = max(max_depth, depth)
                    elif p.is_file():
                        sz = p.stat().st_size
                        total_size += sz
                        file_count += 1
                        max_depth = max(max_depth, depth)
                        if sz > largest_file[0]:
                            largest_file = (sz, p.name)
                        ext = p.suffix.lower() or '(none)'
                        ext_counts[ext] = ext_counts.get(ext, 0) + 1
                except OSError:
                    pass
            self._sep(f"DIRSTAT: {target.name or str(target)}")
            print(f"  {Fore.CYAN}Path        : {Fore.WHITE}{target}")
            print(f"  {Fore.CYAN}Total size  : {Fore.GREEN}{self._fmt_size(total_size)}")
            print(f"  {Fore.CYAN}Files       : {Fore.WHITE}{file_count}")
            print(f"  {Fore.CYAN}Directories : {Fore.WHITE}{dir_count}")
            print(f"  {Fore.CYAN}Max depth   : {Fore.WHITE}{max_depth}")
            if largest_file[1]:
                print(f"  {Fore.CYAN}Largest file: {Fore.YELLOW}{largest_file[1]} ({self._fmt_size(largest_file[0])})")
            if ext_counts:
                top = sorted(ext_counts.items(), key=lambda x: -x[1])[:5]
                ext_str = ', '.join(f"{k} ({v})" for k, v in top)
                print(f"  {Fore.CYAN}Top types   : {Fore.WHITE}{ext_str}")
            self._sep()
        except Exception as e:
            self._err(str(e))

