    def cmd_sed(self, args):
        """Stream editor: sed s/old/new/g <file> or sed /pattern/d <file>"""
        import re as _re
        if len(args) < 2:
            self._err("Usage: sed s/old/new/g <file>  |  sed /pattern/d <file>")
            return
        expr, fname = args[0], args[-1]
        p = self._resolve(fname)
        if not p.exists():
            self._err(f"File not found: {fname}")
            return
        try:
            text = p.read_text(encoding='utf-8', errors='replace')
            lines = text.splitlines(keepends=True)
            if expr.startswith('/') and expr.endswith('/d'):
                pattern = expr[1:-2]
                rx = _re.compile(pattern)
                out = [l for l in lines if not rx.search(l)]
            elif expr.startswith('s/') and '/g' in expr:
                parts = expr.split('/')
                if len(parts) >= 4:
                    old, new = parts[1], parts[2]
                    flags = parts[3] if len(parts) > 3 else ''
                    if 'i' in flags:
                        rx = _re.compile(_re.escape(old), _re.IGNORECASE)
                        out = [_re.sub(rx, new, l) for l in lines]
                    else:
                        out = [l.replace(old, new) if 'g' in flags else l.replace(old, new, 1) for l in lines]
                else:
                    self._err(f"Bad sed expression: {expr}")
                    return
            else:
                self._err(f"Unsupported sed expression: {expr}")
                return
            changed = sum(1 for a, b in zip(lines, out) if a != b)
            p.write_text(''.join(out), encoding='utf-8')
            self._ok(f"sed: {changed} line(s) changed in {fname}")
        except Exception as e:
            self._err(f"sed: {e}")

    def cmd_awk(self, args):
        """Simplified awk: awk '{print $N}' file or awk '{sum+=$1} END{print sum}' file"""
        if not args:
            self._err("Usage: awk '{print $1}' <file>")
            return
        # Shell splits {print $1} into multiple args — rejoin them
        if len(args) > 1 and not args[-1].count('.') and not args[-1].count('/'):
            # Could be: ['{print', '$1}', 'file.txt'] or ['{print', '$1}', 'file']
            # Try to detect file as last arg with common extensions
            pass
        # Rejoin all args that look like pattern parts, last is file if it exists
        fname = None
        if len(args) > 1:
            last = args[-1]
            if self._resolve(last).exists():
                fname = last
                pattern = ' '.join(args[:-1])
            else:
                pattern = ' '.join(args)
        else:
            pattern = args[0]
        if fname:
            p = self._resolve(fname)
            if not p.exists():
                self._err(f"File not found: {fname}")
                return
            lines = p.read_text(encoding='utf-8', errors='replace').splitlines()
        else:
            lines = sys.stdin.read().splitlines() if not sys.stdin.isatty() else []
            if not lines:
                self._err("No input. Provide a file: awk '{print $1}' file.txt")
                return
        # {print $N} pattern
        m = re.match(r'\{print\s+\$([\d,]+)\}', pattern.replace(' ', ''))
        if m:
            fields = [int(x) for x in m.group(1).split(',')]
            for line in lines:
                parts = line.split()
                result = ' '.join(parts[f - 1] for f in fields if f <= len(parts))
                print(f"  {Fore.WHITE}{result}")
            return
        # {print} — whole line
        if pattern.replace(' ', '') in ('{print}', '{print$0}'):
            for line in lines:
                print(f"  {Fore.WHITE}{line}")
            return
        # SUM pattern: {sum+=$N} END{print sum}
        m = re.match(r'\{(\w+)\+=\$\d+\}\s*END\s*\{\s*print\s+\1\s*\}', pattern.replace(' ', ''))
        if m:
            total = 0
            for line in lines:
                parts = line.split()
                if parts:
                    try: total += float(parts[0])
                    except ValueError: pass
            print(f"  {Fore.GREEN}{total:g}")
            return
        self._err(f"Unsupported awk pattern: {pattern}")

