    def cmd_cowsay(self, text):
        if not text:
            self._err("Usage: cowsay <text>")
            return
        width = min(len(text) + 2, 50)
        import textwrap
        lines = textwrap.wrap(text, width=width - 2) or ['']
        top    = ' ' + '_' * (width + 2)
        bottom = ' ' + '-' * (width + 2)
        print(f"\n  {Fore.YELLOW}{top}{Style.RESET_ALL}")
        for i, line in enumerate(lines):
            if len(lines) == 1:
                print(f"  {Fore.YELLOW}<{Style.RESET_ALL}{Fore.WHITE} {line} {Style.RESET_ALL}{Fore.YELLOW}>{Style.RESET_ALL}")
            elif i == 0:
                print(f"  {Fore.YELLOW}/{Style.RESET_ALL}{Fore.WHITE} {line} {' ' * (width - len(line))}{Style.RESET_ALL}{Fore.YELLOW}\\{Style.RESET_ALL}")
            elif i == len(lines) - 1:
                print(f"  {Fore.YELLOW}\\{Style.RESET_ALL}{Fore.WHITE} {line} {' ' * (width - len(line))}{Style.RESET_ALL}{Fore.YELLOW}/{Style.RESET_ALL}")
            else:
                print(f"  {Fore.YELLOW}|{Style.RESET_ALL}{Fore.WHITE} {line} {' ' * (width - len(line))}{Style.RESET_ALL}{Fore.YELLOW}|{Style.RESET_ALL}")
        print(f"  {Fore.YELLOW}{bottom}{Style.RESET_ALL}")
        eye_r = len(lines)
        print(f"  {Fore.YELLOW}        \\   ^__^{Style.RESET_ALL}")
        print(f"  {Fore.YELLOW}         \\  (oo)\\_______{Style.RESET_ALL}")
        print(f"  {Fore.YELLOW}            (__)\\       )\\/\\{Style.RESET_ALL}")
        print(f"  {Fore.YELLOW}                ||----w |{Style.RESET_ALL}")
        print(f"  {Fore.YELLOW}                ||     ||{Style.RESET_ALL}")
        print()

