    def cmd_hash(self, target, algo='sha256'):
        try:
            p = self._resolve(target)
            if p.is_file():
                h = hashlib.new(algo)
                with open(p, 'rb') as f:
                    for chunk in iter(lambda: f.read(65536), b''):
                        h.update(chunk)
                digest = h.hexdigest()
                self._sep(f"{algo.upper()}: {p.name}")
                print(f"  {Fore.CYAN}Hash   : {Fore.WHITE}{digest}")
                print(f"  {Fore.CYAN}Size   : {Fore.WHITE}{self._fmt_size(p.stat().st_size)}")
                self._sep()
            else:
                h = hashlib.new(algo, target.encode()).hexdigest()
                self._sep(f"{algo.upper()}")
                print(f"  {Fore.CYAN}Input  : {Fore.WHITE}{target[:60]}")
                print(f"  {Fore.CYAN}Hash   : {Fore.WHITE}{h}")
                self._sep()
        except Exception as e:
            self._err(f"{algo}: {e}")

