    def cmd_taskkill(self, target):
        if IS_WINDOWS:
            if target.isdigit():
                rc, out, err = self._run_cmd(['taskkill', '/PID', target, '/F'], timeout=15)
            else:
                rc, out, err = self._run_cmd(['taskkill', '/IM', target, '/F'], timeout=15)
            if rc == 0:
                self._ok(f"Killed: {target}")
            else:
                self._err(err.strip() or f"Failed to kill {target}")
        else:
            if target.isdigit():
                rc, out, err = self._run_cmd(['kill', '-9', target], timeout=10)
            else:
                rc, out, err = self._run_cmd(['pkill', '-9', target], timeout=10)
            if rc == 0:
                self._ok(f"Killed: {target}")
            else:
                self._err(err.strip() or f"Failed to kill {target}")

