    def cmd_battery(self):
        try:
            batt = psutil.sensors_battery()
            if batt is None:
                self._warn("No battery detected (desktop PC or driver missing).")
                return
            pct    = batt.percent
            plugged = batt.power_plugged
            secs   = batt.secsleft
            pct_color = Fore.GREEN if pct > 50 else (Fore.YELLOW if pct > 20 else Fore.RED)
            bar_len   = 25
            filled    = int(bar_len * pct / 100)
            bar = (f"{Fore.CYAN}[{pct_color}{'#'*filled}"
                   f"{Fore.RED}{'-'*(bar_len-filled)}{Fore.CYAN}]")
            self._sep("BATTERY")
            print(f"  {Fore.CYAN}Charge    {bar} {pct_color}{pct:.1f}%{Style.RESET_ALL}")
            print(f"  {Fore.CYAN}Plugged   {Fore.WHITE}{'Yes (charging)' if plugged else 'No'}")
            if not plugged and secs != psutil.POWER_TIME_UNKNOWN:
                h, rem = divmod(secs, 3600)
                m = rem // 60
                print(f"  {Fore.CYAN}Remaining {Fore.WHITE}{h}h {m}m")
            self._sep()
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── quick navigation ─────────────────────────────────

    def _goto(self, folder: str):
        candidates = [
            Path(f"C:\\Users\\{self.username}\\{folder}"),
            Path(os.environ.get('USERPROFILE', '')) / folder,
        ]
        for p in candidates:
            if p.exists():
                os.chdir(p)
                self.current_path = p
                self._ok(f"Moved to: {Fore.YELLOW}{p}")
                return
        self._err(f"Folder '{folder}' not found.")

    def cmd_desktop(self):
        self._goto("Desktop")

    def cmd_downloads(self):
        self._goto("Downloads")

    def cmd_documents(self):
        self._goto("Documents")

    def cmd_music(self):
        self._goto("Music")

    def cmd_pictures(self):
        self._goto("Pictures")

    def cmd_videos(self):
        self._goto("Videos")

    def cmd_appdata(self):
        p = Path(os.environ.get('APPDATA', f"C:\\Users\\{self.username}\\AppData\\Roaming"))
        if p.exists():
            os.chdir(p)
            self.current_path = p
            self._ok(f"Moved to: {Fore.YELLOW}{p}")
        else:
            self._err("AppData not found.")

    # ─────────────────────── system tools ─────────────────────────────────────

    def cmd_taskmgr(self):
        if IS_WINDOWS:
            try:
                subprocess.Popen(['taskmgr'])
                self._ok("Task Manager opened.")
            except Exception as e:
                self._err(str(e))
        else:
            for tool in ('htop', 'btop', 'top'):
                if shutil.which(tool):
                    self._info(f"Opening {tool}... (q to quit)")
                    subprocess.call([tool])
                    return
            self._err("No process manager found (install htop).")

    def cmd_services(self):
        self._info("Reading services...")
        if not IS_WINDOWS:
            if shutil.which('systemctl'):
                r = subprocess.run(
                    ['systemctl', 'list-units', '--type=service', '--no-pager', '--no-legend'],
                    capture_output=True, encoding='utf-8', errors='replace', timeout=20)
                self._sep("SYSTEM SERVICES")
                for line in r.stdout.splitlines()[:60]:
                    parts = line.split(None, 4)
                    if len(parts) < 4:
                        continue
                    active = parts[2] if len(parts) > 2 else ''
                    color = Fore.GREEN if active == 'active' else Fore.RED
                    print(f"  {color}{active:<10}{Fore.WHITE}{parts[0]:<45} "
                          f"{parts[3] if len(parts) > 3 else ''}")
                self._sep()
            else:
                self._err("systemctl not found.")
            return
        try:
            r = subprocess.run(
                ['powershell', '-Command',
                 'Get-Service | Select-Object Name,Status,DisplayName | Sort-Object Status'],
                capture_output=True, encoding='utf-8', errors='replace', timeout=20)
            if r.returncode != 0:
                self._err("Could not query services.")
                return
            self._sep("WINDOWS SERVICES")
            for line in r.stdout.strip().splitlines()[3:]:
                line = line.strip()
                if not line:
                    continue
                parts = line.split(None, 2)
                if len(parts) < 2:
                    continue
                name, status = parts[0], parts[1]
                disp = parts[2] if len(parts) > 2 else ''
                color = Fore.GREEN if status == 'Running' else Fore.RED
                print(f"  {color}{status:<12}{Fore.WHITE}{name:<35}{Fore.YELLOW}{disp}")
            self._sep()
        except subprocess.TimeoutExpired:
            self._err("Query timed out.")
        except Exception as e:
            self._err(str(e))

    def cmd_service_ctrl(self, action: str, name: str):
        action = action.lower()
        if action not in ('start', 'stop', 'restart'):
            self._err("Usage: service <start|stop|restart> <name>")
            return
        if not IS_WINDOWS:
            if not shutil.which('systemctl'):
                self._err("systemctl not found.")
                return
            self._info(f"{action.capitalize()}ing service '{name}'...")
            r = subprocess.run(['systemctl', action, name],
                               capture_output=True, encoding='utf-8', errors='replace', timeout=30)
            if r.returncode == 0:
                self._ok(f"Service '{name}' {action}ed.")
            else:
                self._err((r.stderr or r.stdout).strip() or
                          f"Failed (need sudo? try 'root' first).")
            return
        try:
            if not re.fullmatch(r'[A-Za-z0-9_.-]{1,128}', name or ''):
                self._err("Invalid service name. Use letters, numbers, '.', '_' or '-'.")
                return
            self._info(f"{action.capitalize()}ing service '{name}'...")
            commands = [['sc.exe', action, name]] if action != 'restart' else [['sc.exe', 'stop', name], ['sc.exe', 'start', name]]
            results = [subprocess.run(command, capture_output=True, encoding='utf-8', errors='replace', timeout=30) for command in commands]
            r = results[-1]
            if all(result.returncode == 0 for result in results):
                self._ok(f"Service '{name}' {action}ed.")
            else:
                self._err(r.stderr.strip() or f"Failed to {action} service '{name}'.")
        except subprocess.TimeoutExpired:
            self._err("Timed out.")
        except Exception as e:
            self._err(str(e))

    def cmd_regedit_read(self, path: str):
        hive_map = {
            'HKCU': winreg.HKEY_CURRENT_USER,
            'HKLM': winreg.HKEY_LOCAL_MACHINE,
            'HKCR': winreg.HKEY_CLASSES_ROOT,
            'HKU':  winreg.HKEY_USERS,
        }
        try:
            parts = path.replace('/', '\\').split('\\', 1)
            if len(parts) < 2 or parts[0].upper() not in hive_map:
                self._err("Format: regedit <HKCU|HKLM|HKCR>\\path\\to\\key")
                return
            hive   = hive_map[parts[0].upper()]
            subkey = parts[1]
            key    = winreg.OpenKey(hive, subkey)
            self._sep(f"REGISTRY: {path}")
            i = 0
            while True:
                try:
                    name, data, dtype = winreg.EnumValue(key, i)
                    print(f"  {Fore.CYAN}{name or '(Default)':<35}{Fore.WHITE}{str(data)[:60]}")
                    i += 1
                except OSError:
                    break
            winreg.CloseKey(key)
            self._sep()
        except FileNotFoundError:
            self._err(f"Key not found: {path}")
        except PermissionError:
            self._err("Access denied. Try 'root' first.")
        except Exception as e:
            self._err(str(e))

    def cmd_hosts(self):
        hosts_path = Path(r"C:\Windows\System32\drivers\etc\hosts") if IS_WINDOWS \
            else Path('/etc/hosts')
        try:
            if not hosts_path.exists():
                self._err("Hosts file not found.")
                return
            self._sep("HOSTS FILE")
            lines = hosts_path.read_text(encoding='utf-8', errors='replace').splitlines()
            for line in lines:
                if line.startswith('#'):
                    print(f"  {Fore.BLUE}{line}{Style.RESET_ALL}")
                elif line.strip():
                    print(f"  {Fore.GREEN}{line}{Style.RESET_ALL}")
            self._sep()
        except PermissionError:
            self._err("Access denied reading hosts file.")
        except Exception as e:
            self._err(str(e))

    def cmd_traceroute(self, host: str):
        if not host:
            self._err("Usage: traceroute <host>")
            return
        try:
            target_ip = socket.gethostbyname(host)
        except OSError:
            target_ip = host
        self._info(f"Tracing route to {Fore.YELLOW}{host}{Fore.WHITE} ({target_ip})"
                   f" — max 20 hops, 1s per probe (Ctrl+C to abort)")
        start = time.time()
        if IS_WINDOWS:
            argv = ['tracert', '-d', '-h', '20', '-w', '1000', host]
        elif shutil.which('traceroute'):
            argv = ['traceroute', '-n', '-w', '1', '-m', '20', host]
        elif shutil.which('tracepath'):
            argv = ['tracepath', '-n', host]
        else:
            self._err("Neither traceroute nor tracepath is installed.")
            return
        try:
            r = subprocess.run(argv,
                               capture_output=True, encoding='utf-8', errors='replace', timeout=180)
        except subprocess.TimeoutExpired:
            self._err("Trace timed out after 3 minutes.")
            return
        except Exception as e:
            self._err(str(e))
            return
        elapsed = time.time() - start
        lines = (r.stdout or '').splitlines()
        if r.returncode != 0 and not lines:
            self._err((r.stderr or '').strip() or "tracert failed.")
            return
        hop_re = re.compile(r'^\s*(\d+)\s+(.*)$')
        self._ux_frame("TRACEROUTE", right=datetime.now().strftime('%H:%M:%S'),
                       row2=(f"{Fore.WHITE}{host}{Fore.MAGENTA} │{Style.RESET_ALL} "
                             f"{target_ip}"))
        hops = 0
        replies = 0
        reached = False
        for line in lines:
            m = hop_re.match(line)
            if not m:
                continue
            num = int(m.group(1))
            rest = m.group(2).strip()
            if not rest:
                continue
            hops = num
            times = re.findall(r'(\d+(?:\.\d+)?)\s*ms', rest)
            ip_m = re.search(r'\((\d{1,3}(?:\.\d{1,3}){3})\)', rest) \
                or re.search(r'(\d{1,3}(?:\.\d{1,3}){3})\s*$', rest)
            ip = ip_m.group(1) if ip_m else ''
            if times:
                replies += 1
                avg = sum(float(t) for t in times) / len(times)
                col = (Fore.GREEN if avg < 100 else
                       Fore.YELLOW if avg < 300 else Fore.RED)
                label = ip if ip else '?'
                print(f"  {Fore.CYAN}{num:>2}.{Style.RESET_ALL} {label:<15} "
                      f"{col}{avg:5.0f} ms{Style.RESET_ALL}   ({' / '.join(times)} ms)")
                if ip == target_ip:
                    reached = True
            else:
                print(f"  {Fore.CYAN}{num:>2}.{Style.RESET_ALL} "
                      f"{Fore.YELLOW}* * *   no reply (router hides from ICMP){Style.RESET_ALL}")
        print()
        if reached:
            self._ok(f"Destination reached in {hops} hop(s), {replies} replied — {elapsed:.1f}s.")
        else:
            self._warn(f"No reply from destination after {hops} hop(s) — {elapsed:.1f}s.")
            self._info("Routers marked * simply block ICMP — that is normal and does not mean the host is down.")

    def cmd_flush_dns(self):
        try:
            if IS_WINDOWS:
                r = subprocess.run(['ipconfig', '/flushdns'], capture_output=True, encoding='utf-8', errors='replace')
                if r.returncode == 0:
                    self._ok("DNS cache flushed.")
                else:
                    self._err(r.stderr.strip())
            else:
                for argv in (['resolvectl', 'flush-caches'],
                             ['systemd-resolve', '--flush-caches']):
                    if shutil.which(argv[0]):
                        subprocess.run(argv, capture_output=True, timeout=10)
                        self._ok("DNS cache flushed.")
                        return
                self._info("No DNS cache to flush on this system (or tool missing).")
        except Exception as e:
            self._err(str(e))

    def cmd_ip_config(self):
        try:
            if IS_WINDOWS:
                r = subprocess.run(['ipconfig', '/all'], capture_output=True, encoding='utf-8', errors='replace')
                self._sep("NETWORK CONFIGURATION")
                adapter = None
                for line in r.stdout.splitlines():
                    stripped = line.strip()
                    if not stripped:
                        continue
                    if not line.startswith(' ') and not line.startswith('\t') and stripped.endswith(':'):
                        adapter = stripped.rstrip(':')
                        print(f"\n  {Fore.CYAN}{adapter}{Style.RESET_ALL}")
                    elif ':' in stripped:
                        key, _, val = stripped.partition(':')
                        key = key.strip()
                        val = val.strip()
                        if val:
                            if 'IPv4' in key or 'IP Address' in key:
                                print(f"    {Fore.CYAN}{key:<22}{Fore.GREEN}{val}")
                            elif 'Subnet' in key or 'Gateway' in key:
                                print(f"    {Fore.CYAN}{key:<22}{Fore.YELLOW}{val}")
                            elif 'DNS' in key or 'DHCP' in key or 'Server' in key:
                                print(f"    {Fore.CYAN}{key:<22}{Fore.WHITE}{val}")
                            elif 'MAC' in key or 'Physical' in key:
                                print(f"    {Fore.CYAN}{key:<22}{Fore.LIGHTBLACK_EX}{val}")
                            else:
                                print(f"    {Fore.CYAN}{key:<22}{Fore.WHITE}{val}")
                self._sep()
            else:
                for cmd in (['ip', 'addr'], ['ifconfig']):
                    if shutil.which(cmd[0]):
                        r = subprocess.run(cmd, capture_output=True, encoding='utf-8', errors='replace', timeout=15)
                        self._sep("NETWORK INTERFACES")
                        for line in r.stdout.splitlines():
                            if not line.strip():
                                continue
                            if line[0] not in (' ', '\t'):
                                print(f"  {Fore.CYAN}{line.strip()}")
                            elif 'inet ' in line or 'inet6 ' in line:
                                print(f"    {Fore.GREEN}{line.strip()}")
                            elif 'link/' in line:
                                print(f"    {Fore.LIGHTBLACK_EX}{line.strip()}")
                            else:
                                print(f"    {Fore.WHITE}{line.strip()}")
                        self._sep()
                        return
                self._err("Neither 'ip' nor 'ifconfig' found.")
        except Exception as e:
            self._err(str(e))

    def cmd_count_files(self, directory: str = None):
        target = self._resolve(directory) if directory else self.current_path
        if not target.is_dir():
            self._err(f"Not a directory: {target}")
            return
        self._info(f"Counting in '{target}'...")
        try:
            files = dirs = total_size = 0
            ext_counts: dict = {}
            for item in target.rglob('*'):
                try:
                    if item.is_file():
                        files += 1
                        sz = item.stat().st_size
                        total_size += sz
                        ext = item.suffix.lower() or '(no ext)'
                        ext_counts[ext] = ext_counts.get(ext, 0) + 1
                    elif item.is_dir():
                        dirs += 1
                except PermissionError:
                    pass
            self._sep("COUNT")
            print(f"  {Fore.CYAN}Files       {Fore.WHITE}{files:,}")
            print(f"  {Fore.CYAN}Folders     {Fore.WHITE}{dirs:,}")
            mb = total_size / (1024**2)
            print(f"  {Fore.CYAN}Total size  {Fore.WHITE}{mb:.2f} MB")
            if ext_counts:
                top = sorted(ext_counts.items(), key=lambda x: x[1], reverse=True)[:8]
                print(f"\n  {Fore.YELLOW}Top extensions:")
                for ext, cnt in top:
                    print(f"    {Fore.CYAN}{ext:<15}{Fore.WHITE}{cnt:,}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_find_large(self, directory: str = None, min_mb: str = "50"):
        target = self._resolve(directory) if directory else self.current_path
        if not target.is_dir():
            self._err(f"Not a directory: {target}")
            return
        try:
            threshold = float(min_mb) * 1024 * 1024
        except ValueError:
            self._err("min_mb must be a number.")
            return
        self._info(f"Searching for files > {min_mb} MB in '{target}'...")
        found = []
        try:
            for f in target.rglob('*'):
                try:
                    if f.is_file() and f.stat().st_size >= threshold:
                        found.append((f.stat().st_size, f))
                except PermissionError:
                    pass
        except Exception as e:
            self._err(str(e))
            return
        found.sort(reverse=True)
        self._sep(f"LARGE FILES (> {min_mb} MB)")
        if not found:
            self._warn("No large files found.")
        else:
            for sz, p in found[:30]:
                mb = sz / (1024**2)
                print(f"  {Fore.YELLOW}{mb:8.1f} MB  {Fore.WHITE}{p}")
        self._sep()

    def cmd_recent(self):
        try:
            items = []
            for f in self.current_path.rglob('*'):
                try:
                    if f.is_file():
                        items.append((f.stat().st_mtime, f))
                except (PermissionError, OSError):
                    pass
            items.sort(key=lambda x: x[0], reverse=True)
            self._sep("RECENTLY MODIFIED FILES")
            if not items:
                self._warn("No files found.")
                return
            now = time.time()
            for mtime, f in items[:20]:
                dt = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M')
                ago = int(now - mtime)
                if ago < 60:
                    lbl = "just now"
                elif ago < 3600:
                    lbl = f"{ago // 60} min ago"
                elif ago < 86400:
                    lbl = f"{ago // 3600} h ago"
                else:
                    lbl = f"{ago // 86400} d ago"
                try:
                    sz = f.stat().st_size
                    sz_str = (f"{sz/(1024**2):.1f} MB" if sz >= 1024**2
                              else f"{sz/1024:.1f} KB" if sz >= 1024 else f"{sz} B")
                except Exception:
                    sz_str = "?"
                print(f"  {Fore.CYAN}{lbl:<10}{Fore.YELLOW}{f.name:<42}"
                      f"{Fore.GREEN}{sz_str:>10}  {Fore.WHITE}{f.parent}"
                      f"{Fore.RED}  {dt}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_calc(self, expr: str):
        import ast, math, operator
        allowed = {
            'abs': abs, 'round': round, 'min': min, 'max': max, 'pow': pow,
            'sqrt': math.sqrt, 'ceil': math.ceil, 'floor': math.floor,
            'log': math.log, 'log10': math.log10, 'sin': math.sin,
            'cos': math.cos, 'tan': math.tan, 'pi': math.pi, 'e': math.e,
        }
        binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
                  ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv,
                  ast.Mod: operator.mod, ast.Pow: operator.pow}
        unary = {ast.UAdd: operator.pos, ast.USub: operator.neg}
        def evaluate(node):
            if isinstance(node, ast.Expression): return evaluate(node.body)
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)): return node.value
            if isinstance(node, ast.Name) and node.id in allowed and not callable(allowed[node.id]): return allowed[node.id]
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in allowed and callable(allowed[node.func.id]):
                return allowed[node.func.id](*(evaluate(arg) for arg in node.args))
            if isinstance(node, ast.BinOp) and type(node.op) in binary: return binary[type(node.op)](evaluate(node.left), evaluate(node.right))
            if isinstance(node, ast.UnaryOp) and type(node.op) in unary: return unary[type(node.op)](evaluate(node.operand))
            raise ValueError('unsupported expression')
        try:
            result = evaluate(ast.parse(expr, mode='eval'))
            print(f"  {Fore.CYAN}{expr} {Fore.WHITE}= {Fore.GREEN}{result}{Style.RESET_ALL}")
        except ZeroDivisionError:
            self._err("Division by zero.")
        except Exception:
            self._err(f"Invalid expression: {expr}")

    def cmd_note(self, action: str = None, *args):
        notes_file = self.home_path / '.euf_notes.txt'
        action = (action or 'list').lower()
        try:
            if action == 'add':
                text = ' '.join(args)
                if not text:
                    self._err("Usage: note add <text>")
                    return
                ts = datetime.now().strftime('%Y-%m-%d %H:%M')
                with open(notes_file, 'a', encoding='utf-8') as f:
                    f.write(f"[{ts}] {text}\n")
                self._ok("Note saved.")
            elif action == 'list':
                if not notes_file.exists() or not notes_file.read_text(encoding='utf-8').strip():
                    self._warn("No notes yet. Use 'note add <text>'.")
                    return
                self._sep("NOTES")
                lines = notes_file.read_text(encoding='utf-8').splitlines()
                for line in lines:
                    print(f"  {Fore.CYAN}{line}{Style.RESET_ALL}")
                self._sep()
            elif action == 'clear':
                if notes_file.exists():
                    notes_file.unlink()
                self._ok("All notes cleared.")
            else:
                self._err("Usage: note <add|list|clear>")
        except Exception as e:
            self._err(str(e))

    def cmd_alias_run(self, name: str, *cmd_parts):
        if not hasattr(self, '_aliases'):
            self._aliases: dict = {}
        name_l = (name or '').lower()
        if name_l == 'list':
            if not self._aliases:
                self._warn("No custom aliases defined.")
                self._info("Create one: alias gs \"git status\"")
            else:
                self._sep("CUSTOM ALIASES")
                print(f"  {Fore.CYAN}{'ALIAS':<20} {'EXPANDS TO'}")
                print(f"  {Fore.LIGHTBLACK_EX}{'-'*20} {'-'*40}")
                for k, v in sorted(self._aliases.items()):
                    print(f"  {Fore.GREEN}{k:<20} {Fore.WHITE}{v}")
                self._sep()
                self._info(f"{len(self._aliases)} custom alias(es). Type 'help <cmd>' for built-ins.")
        elif name_l == 'show':
            target = (cmd_parts[0] if cmd_parts else '').lower()
            if target in self._aliases:
                self._sep(f"ALIAS: {target}")
                print(f"  {Fore.CYAN}Expands to : {Fore.WHITE}{self._aliases[target]}")
                self._sep()
            elif target in self._aliases or target in self.cmd_aliases:
                built = self.cmd_aliases.get(target, [target])
                self._sep(f"ALIAS: {target}")
                print(f"  {Fore.CYAN}Built-in    : {Fore.WHITE}{', '.join(built)}")
                self._sep()
            else:
                self._err(f"Alias '{target}' not found.")
        elif name_l == 'del' or name_l == 'rm' or name_l == 'remove':
            target_alias = cmd_parts[0] if cmd_parts else ''
            if target_alias in self._aliases:
                del self._aliases[target_alias]
                self._save_user_aliases()
                self._ok(f"Alias '{target_alias}' removed.")
            else:
                self._err(f"Alias '{target_alias}' not found. Try 'alias list'.")
        elif cmd_parts:
            if name_l in ('list', 'del', 'rm', 'show', 'remove'):
                self._err(f"'{name_l}' is reserved. Choose another alias name.")
                return
            self._aliases[name_l] = ' '.join(cmd_parts)
            self._save_user_aliases()
            self._ok(f"Alias created: {name_l} -> {' '.join(cmd_parts)}")
        else:
            self._sep("ALIAS USAGE")
            print(f"  {Fore.CYAN}alias <name> <command>     {Fore.WHITE}Create a custom alias")
            print(f"  {Fore.CYAN}alias list                 {Fore.WHITE}List your custom aliases")
            print(f"  {Fore.CYAN}alias show <name>          {Fore.WHITE}Show what an alias expands to")
            print(f"  {Fore.CYAN}alias del <name>           {Fore.WHITE}Remove a custom alias")
            self._sep()
            print(f"  {Fore.LIGHTBLACK_EX}Example: alias gs \"git status\"  then type: gs")

    def _save_user_aliases(self):
        try:
            p = self.euf_path / 'aliases.json'
            p.write_text(json.dumps(self._aliases, indent=2), encoding='utf-8')
        except Exception:
            pass

    def _load_user_aliases(self):
        try:
            p = self.euf_path / 'aliases.json'
            if p.exists():
                data = json.loads(p.read_text(encoding='utf-8'))
                if isinstance(data, dict):
                    self._aliases.update({str(k).lower(): str(v) for k, v in data.items()})
        except Exception:
            pass

    def cmd_diskusage(self):
        self._sep("DISK USAGE")
        try:
            for part in psutil.disk_partitions(all=False):
                try:
                    usage = psutil.disk_usage(part.mountpoint)
                    bar_len = 25
                    filled  = int(bar_len * usage.percent / 100)
                    color   = (Fore.GREEN if usage.percent < 70
                               else Fore.YELLOW if usage.percent < 90
                               else Fore.RED)
                    bar = (f"{Fore.CYAN}[{color}{'#'*filled}"
                           f"{Fore.RED}{'-'*(bar_len-filled)}{Fore.CYAN}]")
                    free_gb  = usage.free  / (1024**3)
                    total_gb = usage.total / (1024**3)
                    print(f"  {Fore.YELLOW}{part.device:<6}{Fore.WHITE} {bar} "
                          f"{color}{usage.percent:5.1f}%  "
                          f"{Fore.WHITE}{free_gb:.1f} GB free / {total_gb:.1f} GB"
                          f"  {Fore.BLUE}{part.fstype}{Style.RESET_ALL}")
                except (PermissionError, OSError):
                    pass
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_uptime(self):
        try:
            boot   = datetime.fromtimestamp(psutil.boot_time())
            uptime = datetime.now() - boot
            days   = uptime.days
            hours, rem = divmod(uptime.seconds, 3600)
            mins  = rem // 60
            self._sep("UPTIME")
            print(f"  {Fore.CYAN}Boot time  {Fore.WHITE}{boot.strftime('%Y-%m-%d  %H:%M:%S')}")
            print(f"  {Fore.CYAN}Uptime     {Fore.WHITE}{days}d  {hours}h  {mins}m")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_clear_history(self):
        self._history.clear()
        self._history_save()
        self._ok("History cleared.")

    def cmd_ping_sweep(self, subnet: str = None):
        try:
            if not subnet:
                s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                s.connect(("8.8.8.8", 80))
                local_ip = s.getsockname()[0]
                s.close()
                subnet = '.'.join(local_ip.split('.')[:3])
            self._info(f"Sweeping {subnet}.1-254 ...")
            found = []
            lock  = threading.Lock()

            def _ping(ip):
                ping_args = ['ping', '-n', '1', '-w', '400', ip] if IS_WINDOWS else ['ping', '-c', '1', '-W', '1', ip]
                r = subprocess.run(
                    ping_args,
                    capture_output=True)
                if r.returncode == 0:
                    with lock:
                        found.append(ip)

            threads = [threading.Thread(target=_ping,
                       args=(f"{subnet}.{i}",), daemon=True)
                       for i in range(1, 255)]
            for t in threads:
                t.start()
            for t in threads:
                t.join(timeout=3)

            self._sep(f"PING SWEEP: {subnet}.0/24")
            if found:
                for ip in sorted(found, key=lambda x: int(x.split('.')[-1])):
                    try:
                        name = socket.gethostbyaddr(ip)[0]
                    except Exception:
                        name = ''
                    print(f"  {Fore.GREEN}[UP]  {Fore.CYAN}{ip:<18}{Fore.WHITE}{name}")
            else:
                self._warn("No hosts responded.")
            print(f"\n  {Fore.YELLOW}{len(found)} host(s) found.")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_open_terminal_here(self):
        try:
            if IS_WINDOWS:
                subprocess.Popen(['cmd.exe'], cwd=str(self.current_path))
                label = 'CMD'
            else:
                shell = os.environ.get('SHELL') or shutil.which('bash') or '/bin/sh'
                subprocess.Popen([shell], cwd=str(self.current_path))
                label = Path(shell).name
            self._ok(f"New {label} opened at: {Fore.YELLOW}{self.current_path}")
        except Exception as e:
            self._err(str(e))

    def cmd_file_diff(self, file1: str, file2: str):
        import difflib
        try:
            t1 = self._resolve(file1)
            t2 = self._resolve(file2)
            for f, n in [(t1, file1), (t2, file2)]:
                if not f.exists():
                    self._err(f"File not found: {n}")
                    return
            lines1 = t1.read_text(encoding='utf-8', errors='replace').splitlines()
            lines2 = t2.read_text(encoding='utf-8', errors='replace').splitlines()
            diff   = list(difflib.unified_diff(
                lines1, lines2,
                fromfile=file1, tofile=file2, lineterm=''))
            self._sep(f"DIFF: {file1}  vs  {file2}")
            if not diff:
                self._ok("Files are identical.")
            else:
                for line in diff:
                    if line.startswith('+') and not line.startswith('+++'):
                        print(f"{Fore.GREEN}{line}{Style.RESET_ALL}")
                    elif line.startswith('-') and not line.startswith('---'):
                        print(f"{Fore.RED}{line}{Style.RESET_ALL}")
                    elif line.startswith('@@'):
                        print(f"{Fore.CYAN}{line}{Style.RESET_ALL}")
                    else:
                        print(f"{Fore.WHITE}{line}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_zip_list(self, name: str):
        try:
            target = self._resolve(name)
            if not target.exists():
                self._err(f"File not found: {name}")
                return
            with zipfile.ZipFile(target, 'r') as zf:
                infos = zf.infolist()
            self._sep(f"ZIP CONTENTS: {target.name}  ({len(infos)} items)")
            total = 0
            for info in sorted(infos, key=lambda x: x.filename):
                sz   = info.file_size
                total += sz
                sz_s = (f"{sz/(1024**2):.1f}MB" if sz >= 1024**2
                        else f"{sz//1024}KB" if sz >= 1024 else f"{sz}B")
                color = Fore.BLUE if info.filename.endswith('/') else Fore.WHITE
                print(f"  {color}{info.filename:<50}{Fore.GREEN}{sz_s:>8}{Style.RESET_ALL}")
            print(f"\n  {Fore.YELLOW}Total uncompressed: {total/(1024**2):.2f} MB")
            self._sep()
        except zipfile.BadZipFile:
            self._err("Not a valid zip file.")
        except Exception as e:
            self._err(str(e))

    def cmd_run(self, filename: str = None):
        if not filename:
            runnable_exts = {'.py', '.js', '.html', '.htm', '.bat',
                             '.cmd', '.ps1', '.exe', '.vbs', '.jar'}
            items = [f for f in self.current_path.iterdir()
                     if f.is_file() and f.suffix.lower() in runnable_exts]
            if not items:
                self._warn("No runnable files found in current directory.")
                return
            self._sep("RUNNABLE FILES")
            for i, f in enumerate(items, 1):
                print(f"  {Fore.CYAN}{i:>2}. {Fore.WHITE}{f.name}")
            self._sep()
            try:
                choice = input(f"{Fore.CYAN}Pick number (or name): {Fore.WHITE}").strip()
            except (EOFError, KeyboardInterrupt):
                return
            if choice.isdigit():
                idx = int(choice) - 1
                if 0 <= idx < len(items):
                    filename = items[idx].name
                else:
                    self._err("Invalid number.")
                    return
            else:
                filename = choice

        target = self._resolve(filename)
        if not target.exists():
            self._err(f"File not found: {filename}")
            return
        if not target.is_file():
            self._err(f"Not a file: {filename}")
            return

        ext = target.suffix.lower()
        self._info(f"Running: {Fore.YELLOW}{target.name}")
        sep = f"{Fore.BLUE}{'─'*50}{Style.RESET_ALL}"

        try:
            if ext == '.py':
                print(sep)
                r = subprocess.run([sys.executable, str(target)],
                                   cwd=str(target.parent), timeout=300)
                print(sep)
                code = r.returncode
            elif ext == '.js':
                print(sep)
                r = subprocess.run(['cscript', '//Nologo', str(target)],
                                   cwd=str(target.parent), timeout=60)
                print(sep)
                code = r.returncode
            elif ext in ('.html', '.htm'):
                os.startfile(str(target))
                self._ok(f"Opened in browser: {target.name}")
                return
            elif ext in ('.bat', '.cmd'):
                print(sep)
                r = subprocess.run(['cmd', '/c', str(target)],
                                   cwd=str(target.parent), timeout=120)
                print(sep)
                code = r.returncode
            elif ext == '.ps1':
                print(sep)
                r = subprocess.run(
                    ['powershell', '-ExecutionPolicy', 'Bypass',
                     '-File', str(target)],
                    cwd=str(target.parent), timeout=120)
                print(sep)
                code = r.returncode
            elif ext == '.exe':
                print(sep)
                r = subprocess.run([str(target)],
                                   cwd=str(target.parent), timeout=300)
                print(sep)
                code = r.returncode
            elif ext == '.vbs':
                print(sep)
                r = subprocess.run(['cscript', '//Nologo', str(target)],
                                   cwd=str(target.parent), timeout=60)
                print(sep)
                code = r.returncode
            else:
                os.startfile(str(target))
                self._ok(f"Opened: {target.name}")
                return

            if code == 0:
                self._ok(f"'{target.name}' finished  (exit 0).")
            else:
                self._warn(f"'{target.name}' exited with code {code}.")

        except subprocess.TimeoutExpired:
            self._err("Execution timed out.")
        except FileNotFoundError as e:
            self._err(f"Runtime not found: {e}")
        except PermissionError:
            self._err("Permission denied. Try 'root' first.")
        except Exception as e:
            self._err(str(e))

    def cmd_history(self, n: str = None):
        history = getattr(self, '_history', [])
        if not history:
            self._warn("No history yet.")
            return
        limit = int(n) if n and n.isdigit() else len(history)
        self._sep("COMMAND HISTORY")
        start = max(0, len(history) - limit)
        for i, cmd in enumerate(history[start:], start + 1):
            print(f"  {Fore.CYAN}{i:>4}  {Fore.WHITE}{cmd}")
        self._sep()

    # ─────────────────────── new commands ────────────────────────────────────

    def cmd_whoami(self):
        try:
            self._sep("WHOAMI")
            print(f"  {Fore.CYAN}User      {Fore.WHITE}{self.username}")
            print(f"  {Fore.CYAN}Hostname  {Fore.WHITE}{self.hostname}")
            print(f"  {Fore.CYAN}Home      {Fore.WHITE}{self.home_path}")
            is_adm = self._is_admin()
            priv_color = Fore.RED if is_adm else Fore.GREEN
            print(f"  {Fore.CYAN}Admin     {priv_color}{'YES - Elevated' if is_adm else 'No'}{Style.RESET_ALL}")
            if IS_WINDOWS:
                r = subprocess.run(['net', 'user', self.username],
                                   capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                for line in r.stdout.splitlines():
                    if 'Local Group' in line or 'Global Group' in line:
                        print(f"  {Fore.CYAN}Groups    {Fore.WHITE}{line.split('*')[-1].strip()}")
            else:
                r = subprocess.run(['id'], capture_output=True, encoding='utf-8', errors='replace', timeout=8)
                if r.stdout.strip():
                    print(f"  {Fore.CYAN}id        {Fore.WHITE}{r.stdout.strip()}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_path(self):
        self._sep("PATH")
        for p in os.environ.get('PATH', '').split(os.pathsep):
            p = p.strip()
            if not p:
                continue
            exists = Path(p).exists()
            color  = Fore.GREEN if exists else Fore.RED
            mark   = '' if exists else '  (not found)'
            print(f"  {color}{p}{Fore.YELLOW}{mark}{Style.RESET_ALL}")
        self._sep()

    def cmd_find_text(self, pattern: str, directory: str = None):
        target = self._resolve(directory) if directory else self.current_path
        if not target.is_dir():
            self._err(f"Not a directory: {target}")
            return
        self._info(f"Searching for '{Fore.YELLOW}{pattern}{Fore.WHITE}' in '{target}'...")
        found = 0
        total_hits = 0
        rows = []
        try:
            for f in target.rglob('*'):
                if not f.is_file():
                    continue
                if f.suffix.lower() in {'.exe','.dll','.bin','.png','.jpg',
                                         '.jpeg','.gif','.zip','.mp3','.mp4'}:
                    continue
                try:
                    text = f.read_text(encoding='utf-8', errors='ignore')
                    hits = [i+1 for i, ln in enumerate(text.splitlines())
                            if pattern.lower() in ln.lower()]
                    if hits:
                        total_hits += len(hits)
                        found += 1
                        rel = f.relative_to(target)
                        hit_str = ', '.join(str(h) for h in hits[:8])
                        if len(hits) > 8:
                            hit_str += f', +{len(hits)-8} more'
                        rows.append([str(rel), str(len(hits)), hit_str])
                except Exception:
                    pass
        except Exception as e:
            self._err(str(e))
            return
        if rows:
            self._table(['FILE', 'HITS', 'LINES'], rows,
                        title=f'GREP: "{pattern}"', col_align=['<', '>', '<'])
        self._ok(f"Found {total_hits} match(es) in {found} file(s).")

    def cmd_wlan_info(self):
        try:
            r = subprocess.run(['netsh', 'wlan', 'show', 'interfaces'],
                               capture_output=True, encoding='utf-8', errors='replace', timeout=8)
            self._sep("WI-FI INFO")
            for line in r.stdout.splitlines():
                line = line.strip()
                if not line or ':' not in line:
                    continue
                key, _, val = line.partition(':')
                key = key.strip()
                val = val.strip()
                if key and val:
                    print(f"  {Fore.CYAN}{key:<28}{Fore.WHITE}{val}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_proxy(self, action: str = None, server: str = None):
        reg_path = r"Software\Microsoft\Windows\CurrentVersion\Internet Settings"
        try:
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, reg_path,
                                 0, winreg.KEY_READ | winreg.KEY_WRITE)
            action = (action or 'show').lower()
            if action == 'show':
                self._sep("PROXY SETTINGS")
                for field in ['ProxyEnable', 'ProxyServer', 'ProxyOverride']:
                    try:
                        val = winreg.QueryValueEx(key, field)[0]
                        print(f"  {Fore.CYAN}{field:<20}{Fore.WHITE}{val}")
                    except FileNotFoundError:
                        print(f"  {Fore.CYAN}{field:<20}{Fore.RED}(not set)")
                self._sep()
            elif action == 'off':
                winreg.SetValueEx(key, 'ProxyEnable', 0, winreg.REG_DWORD, 0)
                self._ok("Proxy disabled.")
            elif action == 'on':
                if not server:
                    self._err("Usage: proxy on <host:port>")
                    return
                winreg.SetValueEx(key, 'ProxyServer', 0, winreg.REG_SZ, server)
                winreg.SetValueEx(key, 'ProxyEnable', 0, winreg.REG_DWORD, 1)
                self._ok(f"Proxy enabled: {server}")
            else:
                winreg.SetValueEx(key, 'ProxyServer', 0, winreg.REG_SZ, action)
                winreg.SetValueEx(key, 'ProxyEnable', 0, winreg.REG_DWORD, 1)
                self._ok(f"Proxy set to {action}")
            winreg.CloseKey(key)
        except PermissionError:
            self._err("Access denied. Try 'root' first.")
        except Exception as e:
            self._err(str(e))

    def cmd_startup_add(self, name: str, path: str):
        try:
            key = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
                0, winreg.KEY_SET_VALUE)
            winreg.SetValueEx(key, name, 0, winreg.REG_SZ, path)
            winreg.CloseKey(key)
            self._ok(f"'{name}' added to startup.")
        except PermissionError:
            self._err("Access denied. Try 'root' first.")
        except Exception as e:
            self._err(str(e))

    def cmd_startup_remove(self, name: str):
        try:
            key = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
                0, winreg.KEY_SET_VALUE)
            try:
                winreg.DeleteValue(key, name)
                self._ok(f"'{name}' removed from startup.")
            except FileNotFoundError:
                self._err(f"'{name}' not found in startup.")
            winreg.CloseKey(key)
        except Exception as e:
            self._err(str(e))

    def cmd_cpu_cores(self, mode=None):
        watching = mode and mode.lower() in ('watch', 'live', '-w')
        if watching:
            self._info("Per-core CPU usage — Ctrl+C to stop.")
        try:
            while True:
                self._clear()
                cores = psutil.cpu_percent(interval=0.5, percpu=True)
                self._sep("CPU CORES")
                for i, pct in enumerate(cores):
                    bar_len = 30
                    filled  = int(bar_len * pct / 100)
                    color   = (Fore.GREEN if pct < 50
                               else Fore.YELLOW if pct < 80 else Fore.RED)
                    bar = (f"{Fore.CYAN}[{color}{'#'*filled}"
                           f"{Fore.RED}{'-'*(bar_len-filled)}{Fore.CYAN}]")
                    print(f"  {Fore.CYAN}Core {i:<3}{bar} {color}{pct:5.1f}%{Style.RESET_ALL}")
                freq = psutil.cpu_freq()
                if freq:
                    print(f"\n  {Fore.CYAN}Freq  {Fore.WHITE}{freq.current:.0f} MHz  (max {freq.max:.0f} MHz)")
                print(f"\n  {Fore.YELLOW}Ctrl+C to stop{Style.RESET_ALL}")
                self._sep()
                if not watching:
                    break
        except KeyboardInterrupt:
            self._clear()
            self._ok("Stopped.")

    def cmd_tcp_block(self, port: str):
        try:
            port_int = int(port)
            rule_name = f"EUFBlock_{port_int}"
            r = subprocess.run([
                'netsh', 'advfirewall', 'firewall', 'add', 'rule',
                f'name={rule_name}',
                'dir=in', 'action=block',
                'protocol=TCP', f'localport={port_int}'
            ], capture_output=True, encoding='utf-8', errors='replace', timeout=15)
            if r.returncode == 0:
                self._ok(f"TCP port {port_int} blocked  (rule: {rule_name}).")
            else:
                self._err(r.stderr.strip() or "Failed. Try 'root' first.")
        except ValueError:
            self._err("Port must be a number.")
        except Exception as e:
            self._err(str(e))

    def cmd_tcp_unblock(self, port: str):
        try:
            port_int  = int(port)
            rule_name = f"EUFBlock_{port_int}"
            r = subprocess.run([
                'netsh', 'advfirewall', 'firewall', 'delete', 'rule',
                f'name={rule_name}'
            ], capture_output=True, encoding='utf-8', errors='replace', timeout=15)
            if r.returncode == 0:
                self._ok(f"TCP port {port_int} unblocked.")
            else:
                self._err(f"Rule '{rule_name}' not found or access denied.")
        except ValueError:
            self._err("Port must be a number.")
        except Exception as e:
            self._err(str(e))

    def cmd_mac_address(self):
        self._sep("MAC ADDRESSES")
        try:
            addrs = psutil.net_if_addrs()
            import psutil as _ps
            AF_LINK = _ps.AF_LINK
            for iface, addr_list in addrs.items():
                for addr in addr_list:
                    if addr.family == AF_LINK and addr.address:
                        print(f"  {Fore.CYAN}{iface:<25}{Fore.WHITE}{addr.address.upper()}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_installed_apps(self):
        if not IS_WINDOWS:
            # Auto-fallback: installed-apps → package manager on Linux
            for pm, args in [('dpkg', ['dpkg', '-l']),
                             ('rpm', ['rpm', '-qa', '--qf', '%{NAME}\n']),
                             ('pacman', ['pacman', '-Q']),
                             ('apk', ['apk', 'info'])]:
                if shutil.which(pm):
                    rc, out, err = self._run_cmd(args, timeout=30)
                    self._sep(f"INSTALLED APPS ({pm})")
                    lines = [l for l in (out or '').strip().splitlines() if l.strip()]
                    for line in lines[:50]:
                        print(f"  {line}")
                    if len(lines) > 50:
                        print(f"  ... and {len(lines)-50} more")
                    self._sep()
                    return
            self._err('No package manager found.'); return
        self._info("Reading installed apps...")
        reg_paths = [
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
            (winreg.HKEY_LOCAL_MACHINE,
             r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
            (winreg.HKEY_CURRENT_USER,
             r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        ]
        apps = []
        for hive, path in reg_paths:
            try:
                key = winreg.OpenKey(hive, path)
                for i in range(winreg.QueryInfoKey(key)[0]):
                    try:
                        sub_name = winreg.EnumKey(key, i)
                        sub = winreg.OpenKey(key, sub_name)
                        try:
                            name = winreg.QueryValueEx(sub, 'DisplayName')[0]
                            try:
                                ver = winreg.QueryValueEx(sub, 'DisplayVersion')[0]
                            except Exception:
                                ver = ''
                            apps.append((name.strip(), ver.strip()))
                        except Exception:
                            pass
                        winreg.CloseKey(sub)
                    except Exception:
                        pass
                winreg.CloseKey(key)
            except Exception:
                pass
        apps = sorted(set(apps), key=lambda x: x[0].lower())
        self._sep(f"INSTALLED APPS  ({len(apps)} total)")
        for name, ver in apps:
            print(f"  {Fore.CYAN}{name:<45}{Fore.WHITE}{ver}")
        self._sep()

    def cmd_windows_update(self):
        try:
            self._info("Checking for Windows Updates (may take a moment)...")
            r = subprocess.run(
                ['powershell', '-Command',
                 'Get-WindowsUpdate -ErrorAction SilentlyContinue 2>&1 | '
                 'Select-Object Title,Size | Format-Table -AutoSize'],
                capture_output=True, encoding='utf-8', errors='replace', timeout=120)
            self._sep("WINDOWS UPDATES")
            out = r.stdout.strip()
            if out:
                print(f"{Fore.WHITE}{out}")
            else:
                self._ok("No pending updates found (or PSWindowsUpdate not installed).")
                self._info("Install it with:  Install-Module PSWindowsUpdate -Force")
            self._sep()
        except subprocess.TimeoutExpired:
            self._err("Update check timed out.")
        except Exception as e:
            self._err(str(e))

    def cmd_color(self, color_name: str = None):
        if not color_name or color_name.lower() == 'list':
            self._sep("AVAILABLE COLORS")
            for name, code in self.COLOR_MAP.items():
                print(f"  {code}{name}{Style.RESET_ALL}")
            self._sep()
            print(f"  {Fore.CYAN}Current color: {self.input_color}example text{Style.RESET_ALL}")
            return
        c = color_name.lower()
        if c not in self.COLOR_MAP:
            self._err(f"Unknown color '{c}'. Use: {', '.join(self.COLOR_MAP)}")
            return
        self.input_color = self.COLOR_MAP[c]
        self._ok(f"Input color set to: {self.input_color}{c}{Style.RESET_ALL}")

    def cmd_passwd(self, length: str = "16"):
        import secrets, string
        try:
            n = max(8, int(length))
        except ValueError:
            n = 16
        chars = string.ascii_letters + string.digits + "!@#$%^&*()-_=+[]{}|;:,.<>?"
        pwd = ''.join(secrets.choice(chars) for _ in range(n))
        self._sep("GENERATED PASSWORD")
        print(f"  {Fore.GREEN}{pwd}{Style.RESET_ALL}")
        print(f"  {Fore.CYAN}Length: {Fore.WHITE}{n}  |  "
              f"{Fore.CYAN}Strength: {Fore.GREEN}Strong")
        try:
            subprocess.run(['powershell', '-Command',
                            f'Set-Clipboard -Value "{pwd}"'],
                           capture_output=True, timeout=5)
            print(f"  {Fore.YELLOW}(copied to clipboard)")
        except Exception:
            pass
        self._sep()

    def cmd_uuid(self):
        import uuid
        u = str(uuid.uuid4())
        print(f"  {Fore.GREEN}{u}{Style.RESET_ALL}")
        try:
            subprocess.run(['powershell', '-Command',
                            f'Set-Clipboard -Value "{u}"'],
                           capture_output=True, timeout=5)
            print(f"  {Fore.YELLOW}(copied to clipboard)")
        except Exception:
            pass

    def cmd_base_convert(self, value: str = None, from_base: str = None, to_base: str = None):
        if not all([value, from_base, to_base]):
            self._err("Usage: base <value> <from> <to>   e.g. base FF 16 10")
            return
        try:
            fb = int(from_base)
            tb = int(to_base)
            if fb < 2 or fb > 36:
                self._err("From-base must be between 2 and 36.")
                return
            if tb < 2 or tb > 36:
                self._err("To-base must be between 2 and 36.")
                return
            dec = int(value, fb)
            if dec < 0:
                self._err("Negative values are not supported for base conversion.")
                return
            if tb == 2:
                result = bin(dec)[2:]
            elif tb == 8:
                result = oct(dec)[2:]
            elif tb == 10:
                result = str(dec)
            elif tb == 16:
                result = hex(dec)[2:].upper()
            else:
                result = ""
                n = dec
                while n:
                    result = str(n % tb) + result
                    n //= tb
                result = result or "0"
            self._sep("BASE CONVERSION")
            print(f"  {Fore.CYAN}Input  (base {fb}): {Fore.WHITE}{value}")
            print(f"  {Fore.CYAN}Output (base {tb}): {Fore.GREEN}{result}{Style.RESET_ALL}")
            if tb not in (2, 8, 10, 16):
                print(f"  {Fore.YELLOW}Dec: {dec}  Hex: {hex(dec)[2:].upper()}"
                      f"  Bin: {bin(dec)[2:]}")
            self._sep()
        except ValueError as e:
            self._err(f"Conversion error: {e}")

    def cmd_ping_latency(self, host: str = "8.8.8.8", count: str = "10"):
        try:
            n = max(3, int(count))
        except ValueError:
            n = 10
        self._info(f"Pinging {Fore.YELLOW}{host}{Fore.WHITE} x{n}...")
        latencies = []
        for _ in range(n):
            try:
                r = subprocess.run(
                    (['ping', '-n', '1', host] if IS_WINDOWS else ['ping', '-c', '1', host]),
                    capture_output=True, encoding='utf-8', errors='replace', timeout=5)
                match = re.search(r'time[=<](\d+)ms', r.stdout)
                if match:
                    latencies.append(int(match.group(1)))
            except subprocess.TimeoutExpired:
                pass
            time.sleep(0.2)
        self._sep(f"PING STATS: {host}")
        if latencies:
            print(f"  {Fore.CYAN}Sent      {Fore.WHITE}{n}")
            print(f"  {Fore.CYAN}Received  {Fore.WHITE}{len(latencies)}")
            print(f"  {Fore.CYAN}Lost      {Fore.RED}{n - len(latencies)}")
            print(f"  {Fore.CYAN}Min       {Fore.GREEN}{min(latencies)} ms")
            print(f"  {Fore.CYAN}Max       {Fore.YELLOW}{max(latencies)} ms")
            avg = sum(latencies) / len(latencies)
            print(f"  {Fore.CYAN}Avg       {Fore.WHITE}{avg:.1f} ms")
            jitter = max(latencies) - min(latencies)
            print(f"  {Fore.CYAN}Jitter    {Fore.WHITE}{jitter} ms")
        else:
            self._err("Host unreachable.")
        self._sep()

    def cmd_sys_theme(self, theme: str = None):
        reg_path = r"SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize"
        dark_val  = {"dark": 0, "light": 1}
        theme = (theme or 'show').lower()
        try:
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, reg_path,
                                 0, winreg.KEY_READ | winreg.KEY_WRITE)
            if theme == 'show':
                apps = winreg.QueryValueEx(key, 'AppsUseLightTheme')[0]
                sys_ = winreg.QueryValueEx(key, 'SystemUsesLightTheme')[0]
                self._sep("WINDOWS THEME")
                print(f"  {Fore.CYAN}Apps mode    {Fore.WHITE}{'Light' if apps else 'Dark'}")
                print(f"  {Fore.CYAN}System mode  {Fore.WHITE}{'Light' if sys_ else 'Dark'}")
                self._sep()
            elif theme in ('dark', 'light'):
                v = dark_val[theme]
                winreg.SetValueEx(key, 'AppsUseLightTheme',   0, winreg.REG_DWORD, v)
                winreg.SetValueEx(key, 'SystemUsesLightTheme', 0, winreg.REG_DWORD, v)
                self._ok(f"Switched to {theme} mode. Restart Explorer to apply.")
            else:
                self._err("Usage: theme <dark|light|show>")
            winreg.CloseKey(key)
        except Exception as e:
            self._err(str(e))

    def cmd_network_speed_live(self):
        self._info("Live network speed — Ctrl+C to stop.")
        try:
            prev   = psutil.net_io_counters()
            prev_t = time.time()
            while True:
                time.sleep(1)
                curr  = psutil.net_io_counters()
                now   = time.time()
                dt    = max(now - prev_t, 0.001)
                dl_kb = (curr.bytes_recv - prev.bytes_recv) / dt / 1024
                ul_kb = (curr.bytes_sent - prev.bytes_sent) / dt / 1024
                dl_str = f"{dl_kb/1024:.2f} MB/s" if dl_kb >= 1024 else f"{dl_kb:.1f} KB/s"
                ul_str = f"{ul_kb/1024:.2f} MB/s" if ul_kb >= 1024 else f"{ul_kb:.1f} KB/s"
                bar_max  = 1024
                dl_fill  = min(30, int(30 * dl_kb / bar_max))
                ul_fill  = min(30, int(30 * ul_kb / bar_max))
                dl_bar   = (f"{Fore.CYAN}[{Fore.GREEN}{'#'*dl_fill}"
                            f"{Fore.RED}{'-'*(30-dl_fill)}{Fore.CYAN}]")
                ul_bar   = (f"{Fore.CYAN}[{Fore.YELLOW}{'#'*ul_fill}"
                            f"{Fore.RED}{'-'*(30-ul_fill)}{Fore.CYAN}]")
                total_r  = curr.bytes_recv / (1024**3)
                total_s  = curr.bytes_sent / (1024**3)
                self._clear()
                row2 = (f"{Fore.CYAN}Total recv: {Fore.WHITE}{total_r:.2f} GB   "
                        f"{Fore.CYAN}sent: {Fore.WHITE}{total_s:.2f} GB{Style.RESET_ALL}")
                self._ux_frame("LIVE NETWORK SPEED",
                               right=datetime.now().strftime('%H:%M:%S'),
                               row2=row2)
                print(f"  {Fore.GREEN}Download  {dl_bar}  {Fore.GREEN}{dl_str}{Style.RESET_ALL}")
                print(f"  {Fore.YELLOW}Upload    {ul_bar}  {Fore.YELLOW}{ul_str}{Style.RESET_ALL}")
                print(f"\n  {Fore.LIGHTBLACK_EX}Ctrl+C to stop{Style.RESET_ALL}")
                prev   = curr
                prev_t = now
        except KeyboardInterrupt:
            self._clear()
            self._ok("Monitor stopped.")
        except Exception as e:
            self._err(str(e))

    def cmd_file_type(self, name: str):
        SIGS = {
            b'\x89PNG':             'PNG image',
            b'\xff\xd8\xff':      'JPEG image',
            b'GIF8':                 'GIF image',
            b'%PDF':                 'PDF document',
            b'PK\x03\x04':        'ZIP / Office document',
            b'MZ':                   'Windows EXE/DLL',
            b'\x7fELF':            'ELF binary (Linux)',
            b'\xca\xfe\xba\xbe':'Java class file',
            b'\x1f\x8b':          'GZIP archive',
            b'Rar!':                 'RAR archive',
            b'\xff\xfe':          'UTF-16 LE text',
            b'\xfe\xff':          'UTF-16 BE text',
            b'\xef\xbb\xbf':     'UTF-8 BOM text',
            b'RIFF':                 'RIFF (WAV/AVI)',
            b'ID3':                  'MP3 audio',
            b'BM':                   'BMP image',
            b'OTTO':                 'OpenType font',
        }
        try:
            target = self._resolve(name)
            if not target.exists() or not target.is_file():
                self._err(f"File not found: {name}")
                return
            header = target.read_bytes()[:16]
            detected = "Unknown / text"
            for sig, label in SIGS.items():
                if header.startswith(sig):
                    detected = label
                    break
            size = target.stat().st_size
            self._sep(f"FILE TYPE: {target.name}")
            print(f"  {Fore.CYAN}Extension  {Fore.WHITE}{target.suffix or '(none)'}")
            print(f"  {Fore.CYAN}Type       {Fore.GREEN}{detected}{Style.RESET_ALL}")
            print(f"  {Fore.CYAN}Size       {Fore.WHITE}{size:,} bytes")
            print(f"  {Fore.CYAN}Magic hex  {Fore.YELLOW}{header[:8].hex().upper()}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def cmd_watch(self, filename: str = None, interval: str = "2"):
        if not filename:
            self._err("Usage: watch <file> [interval]")
            return
        target = self._resolve(filename)
        if not target.exists() or not target.is_file():
            self._err(f"File not found: {filename}")
            return
        try:
            secs = max(0.5, float(interval))
        except ValueError:
            secs = 2.0
        row2 = (f"{Fore.WHITE}{target}{Style.RESET_ALL}"
                f"  {Fore.MAGENTA}│{Style.RESET_ALL}  "
                f"every {secs}s  ·  tail mode")
        self._ux_frame("LIVE FILE TAIL", right=datetime.now().strftime('%H:%M:%S'),
                       row2=row2)
        try:
            with open(target, 'r', encoding='utf-8', errors='replace') as f:
                f.seek(0, 2)
                while True:
                    line = f.readline()
                    if line:
                        print(f"{Fore.GREEN}{line}", end="", flush=True)
                    else:
                        time.sleep(secs)
        except KeyboardInterrupt:
            print()
            self._ok("Watch stopped.")
        except Exception as e:
            self._err(str(e))

    def cmd_colortest(self):
        self._sep("COLOR TEST")
        colors = [
            (Fore.RED,     'RED'),
            (Fore.GREEN,   'GREEN'),
            (Fore.YELLOW,  'YELLOW'),
            (Fore.BLUE,    'BLUE'),
            (Fore.MAGENTA, 'MAGENTA'),
            (Fore.CYAN,    'CYAN'),
            (Fore.WHITE,   'WHITE'),
        ]
        styles = [('Normal', ''), ('Bright', Style.BRIGHT)]
        for sname, scode in styles:
            row = f"  {Fore.CYAN}{sname:<8}{Style.RESET_ALL}  "
            for code, name in colors:
                row += f"{scode}{code}{'#'*8}  {Style.RESET_ALL}"
            print(row)
            row2 = f"           "
            for code, name in colors:
                row2 += f"{scode}{code}{name:<10}{Style.RESET_ALL}"
            print(row2)
        print()
        print(f"  {Fore.CYAN}Use 'color <name>' to set your input color.{Style.RESET_ALL}")
        self._sep()

    # ─────────────────────── new commands: media / display ──────────────────

    def cmd_volume(self, level: str = None):
        if not IS_WINDOWS:
            # Auto-fallback: volume → amixer/pactl on Linux
            if shutil.which('amixer'):
                if level is None:
                    rc, out, err = self._run_cmd(['amixer', 'get', 'Master'], timeout=10)
                    import re
                    m = re.search(r'\[(\d+)%\]', out)
                    if m:
                        print(f"  {Fore.CYAN}Current volume: {Fore.GREEN}{m.group(1)}%")
                        print(f"  {Fore.CYAN}Set volume    : {Fore.GREEN}volume <0-100>")
                    else:
                        print(out.strip() or err.strip())
                else:
                    try: val = int(level)
                    except ValueError: self._err(f"Invalid level: {level}"); return
                    rc, out, err = self._run_cmd(['amixer', 'set', 'Master', f'{val}%'], timeout=10)
                    self._ok(f"Volume set to {val}%")
                return
            elif shutil.which('pactl'):
                if level is None:
                    rc, out, err = self._run_cmd(['pactl', 'get-sink-volume', '@DEFAULT_SINK@'], timeout=10)
                    import re
                    m = re.search(r'(\d+)%', out)
                    pct = m.group(1) if m else '?'
                    print(f"  {Fore.CYAN}Current volume: {Fore.GREEN}{pct}%")
                else:
                    try: val = int(level)
                    except ValueError: self._err(f"Invalid level: {level}"); return
                    rc, out, err = self._run_cmd(['pactl', 'set-sink-volume', '@DEFAULT_SINK@', f'{val}%'], timeout=10)
                    self._ok(f"Volume set to {val}%")
                return
            else:
                self._err('No volume tool found. Install alsa-utils or pulseaudio.'); return
        try:
            from ctypes import windll, c_ulong, byref
            if level is None:
                buf = c_ulong()
                windll.winmm.waveOutGetVolume(0, byref(buf))
                cur = buf.value
                pct = int((cur & 0xFFFF) * 100 / 0xFFFF)
                print(f"  {Fore.CYAN}Current volume: {Fore.GREEN}{pct}%")
                print(f"  {Fore.CYAN}Set volume    : {Fore.GREEN}volume <0-100>")
                return
            try:
                val = int(level)
            except ValueError:
                self._err(f"Invalid level: {level}")
                return
            if val < 0 or val > 100:
                self._err("Volume must be between 0 and 100.")
                return
            packed = int(0xFFFF * val / 100)
            windll.winmm.waveOutSetVolume(0, packed | (packed << 16))
            self._ok(f"Volume set to {val}%")
        except Exception as e:
            self._err(str(e))

    def cmd_brightness(self, level: str = None):
        if not IS_WINDOWS:
            # Auto-fallback: brightness → brightnessctl/xbacklight on Linux
            if shutil.which('brightnessctl'):
                if level is None:
                    rc, out, err = self._run_cmd(['brightnessctl', 'get'], timeout=10)
                    rc2, out2, _ = self._run_cmd(['brightnessctl', 'max'], timeout=10)
                    try:
                        pct = int(int(out.strip()) / int(out2.strip()) * 100)
                        print(f"  {Fore.CYAN}Current brightness: {Fore.GREEN}{pct}%")
                        print(f"  {Fore.CYAN}Set brightness    : {Fore.GREEN}brightness <0-100>")
                    except Exception:
                        print(out.strip() or err.strip())
                else:
                    try: val = int(level)
                    except ValueError: self._err(f"Invalid level: {level}"); return
                    self._run_cmd(['brightnessctl', 'set', f'{val}%'], timeout=10)
                    self._ok(f"Brightness set to {val}%")
                return
            elif shutil.which('xbacklight'):
                if level is None:
                    rc, out, _ = self._run_cmd(['xbacklight', '-get'], timeout=10)
                    print(f"  {Fore.CYAN}Current brightness: {Fore.GREEN}{out.strip()}%")
                else:
                    try: val = int(level)
                    except ValueError: self._err(f"Invalid level: {level}"); return
                    self._run_cmd(['xbacklight', '-set', str(val)], timeout=10)
                    self._ok(f"Brightness set to {val}%")
                return
            else:
                self._err('No brightness tool found. Install brightnessctl or xbacklight.'); return
        try:
            if level:
                try:
                    val = int(level)
                except ValueError:
                    self._err(f"Invalid level: {level}")
                    return
                if val < 0 or val > 100:
                    self._err("Brightness must be between 0 and 100.")
                    return
                subprocess.run(
                    ['powershell', '-NoProfile', '-Command',
                     f'(Get-WmiObject -Namespace root/WMI -Class WmiMonitorBrightnessMethods)'
                     f'.WmiSetBrightness(1,{val})'],
                    capture_output=True, timeout=15)
                self._ok(f"Brightness set to {val}%")
                return
            r = subprocess.run(
                ['powershell', '-NoProfile', '-Command',
                 'Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness '
                 '| Select-Object -ExpandProperty CurrentBrightness'],
                capture_output=True, encoding='utf-8', errors='replace', timeout=10)
            val = r.stdout.strip()
            if val:
                print(f"  {Fore.CYAN}Current brightness: {Fore.GREEN}{val}%")
                print(f"  {Fore.CYAN}Set brightness    : {Fore.GREEN}brightness <0-100>")
            else:
                self._warn("Brightness is not reported on this display.")
        except Exception as e:
            self._err(str(e))

    def cmd_wallpaper(self, path: str = None):
        import ctypes as _c
        if not path:
            try:
                buf = _c.create_unicode_buffer(512)
                _c.windll.user32.SystemParametersInfoW(0x0073, 512, buf, 0)
                cur = buf.value
                print(f"  {Fore.CYAN}Current wallpaper: {Fore.GREEN}{cur if cur else '(unknown)'}")
            except Exception as e:
                self._err(str(e))
            self._info("Usage: wallpaper <image-path>")
            return
        target = self._resolve(path)
        if not target.exists():
            self._err(f"File not found: {path}")
            return
        try:
            _c.windll.user32.SystemParametersInfoW(20, 0, str(target), 3)
            self._ok(f"Desktop wallpaper set: {Fore.YELLOW}{target}")
        except Exception as e:
            self._err(str(e))

    def cmd_matrix(self):
        import random as _rand
        try:
            size = shutil.get_terminal_size((80, 24))
            width = max(20, size.columns)
            height = max(10, size.lines - 2)
            chars = '01'
            for ch in 'アイウエオカキクケコサシスセソ':
                chars += ch
            cols = [_rand.randint(0, height) for _ in range(width)]
            self._clear()
            print(f"{Fore.GREEN}{Style.BRIGHT}", end="")
            for _ in range(1500):
                sys.stdout.write('\x1b[H')
                for i in range(width):
                    if cols[i] <= 0:
                        sys.stdout.write(_rand.choice(chars))
                    else:
                        sys.stdout.write(' ')
                    cols[i] -= 1
                    if _rand.random() > 0.975:
                        cols[i] = _rand.randint(0, height)
                sys.stdout.flush()
                time.sleep(0.05)
                if self._kbhit():
                    self._getch()
                    break
            print(Style.RESET_ALL)
            self._ok("Matrix stopped. Press any key to exit mode.")
        except Exception as e:
            self._err(str(e))

    ASCII_RAMPS = {
        'simple': " .:-=+*#%@",
        'blocks': " \u2591\u2592\u2593\u2588",
        'detailed': (" .'`^\",:;Il!i><~+_-?}{1)(|\\/tfjrxnuvczXYUJCLQ0O"
                     "Zmwqpdbkhao*#MW&8%B@$"),
    }
    ASCII_MODES = ('color', 'detailed', 'simple', 'tint', 'blocks')
    ASCII_DEFAULT_MODE = 'color'
    ASCII_DEFAULT_WIDTH = 0
    ASCII_BAYER8 = (
        (0, 32, 8, 40, 2, 34, 10, 42),
        (48, 16, 56, 24, 50, 18, 58, 26),
        (12, 44, 4, 36, 14, 46, 6, 38),
        (60, 28, 52, 20, 62, 30, 54, 22),
        (3, 35, 11, 43, 1, 33, 9, 41),
        (51, 19, 59, 27, 49, 17, 57, 25),
        (15, 47, 7, 39, 13, 45, 5, 37),
        (63, 31, 55, 23, 61, 29, 53, 21),
    )

    @classmethod
    def _ascii_dither_map(cls, gh, gw, spread):
        import numpy as np
        m = np.asarray(cls.ASCII_BAYER8, dtype=np.float32) / 64.0 - 0.5
        tile = np.tile(m, (gh // 8 + 1, gw // 8 + 1))[:gh, :gw]
        return tile * float(spread)

    @staticmethod
    def _ascii_tone(arr, gamma=1.0, levels=False):
        import numpy as np
        a = np.asarray(arr, dtype=np.float32)
        if levels:
            lo = float(a.min())
            hi = float(a.max())
            if hi - lo > 1.0:
                a = (a - lo) * (255.0 / (hi - lo))
        if gamma and abs(gamma - 1.0) > 1e-6:
            a = 255.0 * np.power(np.clip(a, 0.0, 255.0) / 255.0, float(gamma))
        return np.clip(a, 0.0, 255.0)

    def _ascii_grid_size(self, img_w, img_h, width, cell_ratio=0.5):
        if img_w <= 0 or img_h <= 0:
            return width, 1
        rows = int(round(width * (img_h / img_w) * cell_ratio))
        return width, max(1, rows)

    def _ascii_mono(self, img, width, ramp="simple", invert=False,
                    tint=False, gamma=1.0, levels=False, dither=False):
        import numpy as np
        from PIL import Image
        w, h = img.size
        gw, gh = self._ascii_grid_size(w, h, width)
        g = img.convert("L").resize((gw, gh), Image.LANCZOS)
        arr = self._ascii_tone(np.asarray(g), gamma, levels)
        if dither:
            arr = arr + self._ascii_dither_map(gh, gw, 255.0 / max(2, len(ramp)))
        if invert:
            arr = 255.0 - arr
        top = len(ramp) - 1
        idx = np.clip((arr * top / 255.0).astype(np.int32), 0, top)
        out = []
        if not tint:
            for y in range(gh):
                out.append("".join(ramp[int(i)] for i in idx[y]))
            return out
        rgb = img.convert("RGB").resize((gw, gh), Image.LANCZOS)
        carr = np.asarray(rgb).astype(np.int32)
        for y in range(gh):
            parts = []
            row_i = idx[y]
            row_c = carr[y]
            for x in range(gw):
                r_, g_, b_ = row_c[x]
                parts.append(f"\033[38;2;{r_};{g_};{b_}m"
                             f"{ramp[int(row_i[x])]}{Style.RESET_ALL}")
            out.append("".join(parts))
        return out

    def _ascii_color(self, img, width, invert=False, gamma=1.0, levels=False):
        import numpy as np
        from PIL import Image
        w, h = img.size
        gw, gh = self._ascii_grid_size(w, h, width)
        small = img.convert("RGB").resize((gw, gh * 2), Image.BILINEAR)
        arr = np.asarray(small, dtype=np.float32)
        for c in range(3):
            arr[:, :, c] = self._ascii_tone(arr[:, :, c], gamma, levels)
        if invert:
            arr = 255.0 - arr
        q = np.clip(arr, 0, 255).astype(np.int32) >> 4
        top = q[0::2]
        bot = q[1::2]
        out = []
        for y in range(gh):
            t = top[y]
            b = bot[y]
            tk = (t[:, 0] << 16) | (t[:, 1] << 8) | t[:, 2]
            bk = (b[:, 0] << 16) | (b[:, 1] << 8) | b[:, 2]
            parts = []
            x = 0
            while x < gw:
                k1 = int(tk[x])
                k2 = int(bk[x])
                n = 1
                while x + n < gw and int(tk[x + n]) == k1 and int(bk[x + n]) == k2:
                    n += 1
                tr = ((k1 >> 16) & 15) * 17
                tg = ((k1 >> 8) & 15) * 17
                tb = (k1 & 15) * 17
                br = ((k2 >> 16) & 15) * 17
                bg = ((k2 >> 8) & 15) * 17
                bb = (k2 & 15) * 17
                parts.append(f"\033[38;2;{tr};{tg};{tb}m"
                             f"\033[48;2;{br};{bg};{bb}m" + "\u2580" * n)
                x += n
            out.append("".join(parts) + Style.RESET_ALL)
        return out

    def _ascii_render(self, img, width=100, mode="color", invert=False, style=None):
        st = style or {}
        gamma = st.get('gamma', 1.0)
        levels = bool(st.get('levels', False))
        dither = bool(st.get('dither', False))
        if mode == 'color':
            return self._ascii_color(img, width, invert, gamma, levels)
        if mode == 'tint':
            return self._ascii_mono(img, width, self.ASCII_RAMPS['detailed'],
                                    invert, True, gamma, levels, dither)
        ramp = self.ASCII_RAMPS.get(mode, self.ASCII_RAMPS['simple'])
        return self._ascii_mono(img, width, ramp, invert, False, gamma,
                                levels, dither)

    @staticmethod
    def _ascii_max_rows(reserve_rows=8):
        try:
            tsize = shutil.get_terminal_size(fallback=(100, 30))
        except Exception:
            tsize = (100, 30)
        return max(3, tsize.lines - reserve_rows)

    def _ascii_fit(self, img_w, img_h, requested=0, reserve_cols=2,
                   reserve_rows=8, min_w=8, max_default=120):
        try:
            tsize = shutil.get_terminal_size(fallback=(100, 30))
        except Exception:
            tsize = (100, 30)
        max_w = max(min_w, tsize.columns - reserve_cols)
        max_h = max(3, tsize.lines - reserve_rows)
        try:
            w = int(requested or 0)
        except (TypeError, ValueError):
            w = 0
        if w <= 0:
            w = self.ASCII_DEFAULT_WIDTH or min(max_default, max_w)
            w = min(w, max_w) if self.ASCII_DEFAULT_WIDTH else w
        w = max(min_w, min(w, max_w))
        if img_w > 0 and img_h > 0:
            while w > min_w and self._ascii_grid_size(img_w, img_h, w)[1] > max_h:
                w = max(min_w, w - 2)
        return w

    def _ascii_letterbox_size(self, w, h, width, max_rows):
        if w <= 0 or h <= 0:
            return w, h
        if self._ascii_grid_size(w, h, width)[1] <= max_rows:
            return w, h
        target = (max_rows * 2.0) / max(1, width)
        if h / w > target:
            return int(round(h / target)), h
        return w, int(round(w * target))

    def _ascii_letterbox(self, pil, width, max_rows):
        """Pad with black bars so an extreme aspect ratio still fits."""
        from PIL import Image
        w, h = pil.size
        nw, nh = self._ascii_letterbox_size(w, h, width, max_rows)
        if (nw, nh) == (w, h):
            return pil, width
        canvas = Image.new("RGB", (nw, nh), (0, 0, 0))
        canvas.paste(pil, ((nw - w) // 2, (nh - h) // 2))
        return canvas, self._ascii_fit(nw, nh, width,
                                       reserve_rows=max_rows)

    def _ascii_style(self, opts):
        st = {'gamma': 1.0, 'levels': False, 'dither': False}
        g = self._ascii_opt(opts, ["--gamma", "gamma"], None)
        if g is not None and g is not True:
            try:
                st['gamma'] = max(0.1, min(4.0, float(g)))
            except (TypeError, ValueError):
                pass
        st['levels'] = bool(self._ascii_opt(opts, ["--levels", "levels"], False))
        st['dither'] = bool(self._ascii_opt(opts, ["--dither", "dither"], False))
        return st

    def _ascii_width_arg(self, opts):
        w = self._ascii_opt(opts, ["--width", "--cols", "w", "width"], None)
        if w is not None and w is not True:
            try:
                return int(w)
            except (TypeError, ValueError):
                pass
        for i, o in enumerate(opts):
            if o.isdigit() and not (i > 0 and opts[i - 1].startswith('-')):
                return int(o)
        return 0

    @staticmethod
    def _ascii_opt(opts, names, default=None):
        low = [o.lower() for o in opts]
        for n in names:
            for i, o in enumerate(low):
                if o == n or o.startswith(n + "="):
                    if "=" in o:
                        return o.split("=", 1)[1]
                    nxt = opts[i + 1] if i + 1 < len(opts) else None
                    if nxt is not None and not nxt.startswith("-"):
                        return nxt
                    return True
        return default

    def _ascii_mode(self, opts, default=None):
        named = self._ascii_opt(opts, ["mode"], None)
        if isinstance(named, str) and named:
            cand = named.lower()
            if cand in self.ASCII_MODES:
                return cand
        for o in opts:
            cand = o.lower()
            if cand in self.ASCII_MODES:
                return cand
        return default or self.ASCII_DEFAULT_MODE

    @staticmethod
    @contextlib.contextmanager
    def _silence_stderr_fd():
        try:
            sys.stderr.flush()
        except Exception:
            pass
        try:
            saved = os.dup(2)
        except Exception:
            yield
            return
        devnull = None
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, 2)
            yield
        finally:
            try:
                os.dup2(saved, 2)
            except Exception:
                pass
            for fd in (devnull, saved):
                if fd is not None:
                    try:
                        os.close(fd)
                    except Exception:
                        pass

    def cmd_3d(self, sub=None, *args):
        """Dispatch `3d image|video ...` to the matching renderer."""
        if not sub:
            self._err("Usage: 3d image <file> [width] [mode] [options]")
            self._err("       3d video <file> [width] [mode] [options]")
            self._info("Tip: '3d-image' and '3d-video' also work directly.")
            return
        key = sub.lower()
        if key in ('image', 'img', 'i', 'picture'):
            return self.cmd_3d_image(args[0] if args else None, *args[1:])
        if key in ('video', 'vid', 'v', 'clip', 'movie'):
            return self.cmd_3d_video(args[0] if args else None, *args[1:])
        self._err(f"Unknown 3d mode: '{sub}'.")
        self._err("Valid modes: image (img, i) | video (vid, v)")

    def cmd_3d_image(self, path=None, *opts):
        """Render a still image as ASCII art in the terminal."""
        if not path:
            self._err("Usage: 3d-image <file> [width] [mode] [--invert] "
                      "[--gamma N] [--levels] [--dither] [--save out.txt]")
            return
        target = self._resolve(path)
        if not target.exists() or not target.is_file():
            self._err(f"Image not found: {path}")
            return
        try:
            from PIL import Image, ImageOps
        except ImportError:
            self._err("Pillow is required. Install it with: "
                      "pip install Pillow")
            return

        mode = self._ascii_mode(opts)
        invert = bool(self._ascii_opt(opts, ["--invert", "invert"], False))
        style = self._ascii_style(opts)
        save_to = self._ascii_opt(opts, ["--save", "save"], None)

        try:
            img = Image.open(target)
            img = ImageOps.exif_transpose(img)
            img.load()
        except Exception as e:
            self._err(f"Could not open image: {e}")
            return

        iw, ih = img.size
        max_rows = self._ascii_max_rows(6)
        width = self._ascii_fit(iw, ih, self._ascii_width_arg(opts),
                                reserve_rows=6)
        img, width = self._ascii_letterbox(img, width, max_rows)

        try:
            rows = self._ascii_render(img, width, mode, invert, style)
        except Exception as e:
            self._err(f"Render failed: {e}")
            return

        plain = re.sub(r'\x1b\[[0-9;]*m', '', "\n".join(rows))
        extras = []
        if invert:
            extras.append("inverted")
        if style['levels']:
            extras.append("levels")
        if style['dither']:
            extras.append("dither")
        if abs(style['gamma'] - 1.0) > 1e-6:
            extras.append(f"gamma {style['gamma']:g}")
        header = (f"{Fore.CYAN}{target.name}{Style.RESET_ALL}  "
                  f"{Fore.LIGHTBLACK_EX}{iw}x{ih} px"
                  f"  ->  {width}x{len(rows)} chars  mode={mode}"
                  f"{'  ' + '  '.join(extras) if extras else ''}"
                  f"{Style.RESET_ALL}")
        if save_to and isinstance(save_to, str):
            dest = self._resolve(save_to)
            try:
                dest.write_text(plain, encoding="utf-8")
                self._ok(f"ASCII saved: {Fore.YELLOW}{dest} "
                         f"({len(plain)} chars)")
                return
            except OSError as e:
                self._err(f"Could not save: {e}")
                return

        print()
        print(f"  {header}")
        print()
        for r in rows:
            print(r)
        print()
        self._ok(f"Rendered {target.name} at {width}x{len(rows)} "
                 f"({mode}).")

    def cmd_3d_video(self, path=None, *opts):
        """Play a video as live ASCII art in the terminal."""
        if not path:
            self._err("Usage: 3d-video <file> [width] [mode] "
                      "[--fps N] [--loop] [--invert] [--gamma N] "
                      "[--levels] [--dither] [--save out.txt]")
            return
        target = self._resolve(path)
        if not target.exists() or not target.is_file():
            self._err(f"Video not found: {path}")
            return
        try:
            import cv2
            from PIL import Image
        except ImportError:
            self._err("OpenCV and Pillow are required. Install with: "
                      "pip install opencv-python Pillow")
            return
        try:
            cv2.utils.logging.setLogLevel(cv2.utils.logging.LOG_LEVEL_SILENT)
        except Exception:
            pass

        mode = self._ascii_mode(opts)
        invert = bool(self._ascii_opt(opts, ["--invert", "invert"], False))
        style = self._ascii_style(opts)
        loop = bool(self._ascii_opt(opts, ["--loop"], False))
        save_to = self._ascii_opt(opts, ["--save", "save"], None)
        max_fps = self._ascii_opt(opts, ["--fps", "fps"], None)
        try:
            max_fps = float(max_fps) if max_fps not in (None, True) else 0.0
        except (TypeError, ValueError):
            max_fps = 0.0
        if max_fps <= 0:
            max_fps = 30.0

        if not self._interactive():
            self._err("3d-video needs a real terminal to play in "
                      "(stdin/stdout is not interactive).")
            return

        with self._silence_stderr_fd():
            cap = cv2.VideoCapture(str(target))
            opened = cap.isOpened()
            first = cap.read() if opened else (False, None)
        if not opened:
            self._err(f"Could not open video: {target.name}")
            return
        if not first[0]:
            cap.release()
            self._err(f"Not a video OpenCV can decode: {target.name}")
            return
        cap.set(cv2.CAP_PROP_POS_FRAMES, 0)

        src_fps = cap.get(cv2.CAP_PROP_FPS) or 0
        if not src_fps or src_fps <= 0 or src_fps > 240:
            src_fps = 24.0
        total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        vw = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
        vh = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
        if vw <= 0 or vh <= 0:
            cap.release()
            self._err(f"Video reports no usable frame size: {target.name}")
            return
        fps = min(src_fps, max_fps)
        max_rows = self._ascii_max_rows(10)
        width = self._ascii_fit(vw, vh, self._ascii_width_arg(opts),
                                reserve_rows=10)
        grid_w, grid_h = self._ascii_grid_size(
            *self._ascii_letterbox_size(vw, vh, width, max_rows), width)

        dur_txt = ""
        if total > 0 and src_fps > 0:
            dur_txt = f"  {total / src_fps:.1f}s"
        print()
        self._sep("ASCII VIDEO")
        print(f"  {Fore.CYAN}{target.name}{Style.RESET_ALL}  "
              f"{Fore.LIGHTBLACK_EX}{vw}x{vh} -> {grid_w}x{grid_h} chars  "
              f"mode={mode}  {fps:.0f} fps"
              f"{'  loop' if loop else ''}"
              f"{f'  {total} frames' if total else ''}{dur_txt}"
              f"{Style.RESET_ALL}")
        self._sep()
        self._info("Press Enter to play it as ASCII"
                   + (" (Ctrl+C or any key stops)" if not loop else
                      " (any key stops, it will loop)"))
        try:
            input()
        except (EOFError, KeyboardInterrupt):
            cap.release()
            print()
            self._warn("Cancelled.")
            return
        print()

        self._clear()
        print('\033[?25l', end='', flush=True)
        frames = 0
        start = time.time()
        fails = 0
        saved_frames = [] if (save_to and isinstance(save_to, str)) else None
        try:
            while True:
                loop_start = time.time()
                ok, frame = cap.read()
                if not ok:
                    if not loop:
                        break
                    cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                    ok, frame = cap.read()
                    if not ok:
                        break
                try:
                    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                    pil = Image.fromarray(rgb)
                    pil, gw = self._ascii_letterbox(pil, width, max_rows)
                    rows = self._ascii_render(pil, gw, mode, invert, style)
                    fails = 0
                except Exception:
                    fails += 1
                    if fails >= 30:
                        self._err("Rendering keeps failing — stopping.")
                        break
                    if self._kbhit():
                        self._getch()
                        break
                    time.sleep(0.05)
                    continue

                frames += 1
                if saved_frames is not None:
                    saved_frames.append("\n".join(rows))

                elapsed = time.time() - start
                bar_w = 24
                prog = (frames / total) if total else 0
                filled = int(round(bar_w * min(1.0, prog)))
                bar = (f"{Fore.GREEN}{'█' * filled}"
                       f"{Fore.LIGHTBLACK_EX}{'░' * (bar_w - filled)}"
                       f"{Style.RESET_ALL}")
                head = (f"{Fore.CYAN}{target.name}{Style.RESET_ALL} "
                        f"{Fore.LIGHTBLACK_EX}{vw}x{vh}  {grid_w} cols  "
                        f"{fps:.0f} fps  frame {frames}"
                        f"{'/' + str(total) if total else ''}  "
                        f"{elapsed:5.1f}s{Style.RESET_ALL}")
                foot = (f" {bar} {int(prog * 100):3d}%   "
                        f"{Fore.LIGHTBLACK_EX}any key = stop"
                        f"{'  looping' if loop else ''}{Style.RESET_ALL}")

                sys.stdout.write("\033[H\033[J")
                sys.stdout.write(head + "\n\n")
                for r in rows:
                    sys.stdout.write(r + "\n")
                sys.stdout.write("\n" + foot)
                sys.stdout.flush()

                if self._kbhit():
                    self._getch()
                    break

                delay = 1.0 / fps - (time.time() - loop_start)
                if delay > 0:
                    time.sleep(delay)
        except KeyboardInterrupt:
            pass
        finally:
            cap.release()
            print('\033[?25h', end='', flush=True)
            self._clear()
            dur = time.time() - start
            avg = frames / dur if dur > 0 else 0
            if saved_frames is not None and saved_frames:
                dest = self._resolve(save_to)
                try:
                    dest.write_text(
                        "\033[H\033[2J".join(saved_frames),
                        encoding="utf-8")
                    self._ok(f"ASCII frames saved: {Fore.YELLOW}{dest} "
                             f"({len(saved_frames)} frames)")
                except OSError as e:
                    self._err(f"Could not save frames: {e}")
            self._ok(f"ASCII video stopped. {frames} frame(s) "
                     f"in {dur:.1f}s ({avg:.1f} fps rendered).")

    # ────────────────────────────────────────────────────────────────────────
    #  VIDEO PLAYER + VIDEO MANAGER (truecolour half-block playback + audio)
    # ────────────────────────────────────────────────────────────────────────

    VIDEO_EXTS = {'.mp4', '.m4v', '.mkv', '.avi', '.mov', '.webm', '.wmv',
                  '.flv', '.mpg', '.mpeg', '.ts', '.ogv', '.3gp'}
    VP_BAYER4 = ((0, 8, 2, 10), (12, 4, 14, 6), (3, 11, 1, 9), (15, 7, 13, 5))

    @staticmethod
    def _ffmpeg_exe():
        exe = shutil.which('ffmpeg')
        if exe:
            return exe
        try:
            import imageio_ffmpeg
            return imageio_ffmpeg.get_ffmpeg_exe()
        except Exception:
            return None

    @staticmethod
    def _fmt_hms(sec, force_hours=False):
        sec = max(0, int(sec))
        m, s = divmod(sec, 60)
        h, m = divmod(m, 60)
        if h or force_hours:
            return f"{h}:{m:02d}:{s:02d}"
        return f"{m:02d}:{s:02d}"

    @staticmethod
    def _fmt_size_mb(n):
        try:
            n = float(n)
        except (TypeError, ValueError):
            return "n/a"
        if n >= 1024 * 1024 * 1024:
            return f"{n / 1024 / 1024 / 1024:.1f} GB"
        if n >= 1024 * 1024:
            return f"{n / 1024 / 1024:.1f} MB"
        return f"{max(1, int(n / 1024))} KB"

    @classmethod
    def _vp_encode(cls, rgb, gamma=1.0, dither=0.0):
        """RGB frame -> list of ANSI row strings (truecolour half-blocks).

        Each cell renders two stacked pixels with U+2580 (upper half block):
        foreground = top pixel, background = bottom pixel. Runs of identical
        colour pairs share one escape pair, so output stays small and fast.
        """
        import numpy as np
        a = rgb.astype(np.float32)
        if abs(gamma - 1.0) > 1e-6:
            a = 255.0 * np.power(np.clip(a, 0.0, 255.0) / 255.0, float(gamma))
        if dither > 0.0:
            h, w = a.shape[:2]
            b = (np.asarray(cls.VP_BAYER4, dtype=np.float32) / 16.0) - 0.5
            tile = np.tile(b, (h // 4 + 1, w // 4 + 1))[:h, :w]
            a = a + tile * dither
        a = np.clip(a, 0.0, 255.0).astype(np.uint8)
        top, bot = a[0::2], a[1::2]
        H, W = top.shape[:2]
        tk = ((top[:, :, 0].astype(np.uint32) << 16) |
              (top[:, :, 1].astype(np.uint32) << 8) | top[:, :, 2])
        bk = ((bot[:, :, 0].astype(np.uint32) << 16) |
              (bot[:, :, 1].astype(np.uint32) << 8) | bot[:, :, 2])
        half = '\u2580'
        rows = []
        for y in range(H):
            t = tk[y]
            b = bk[y]
            diff = np.flatnonzero((t[1:] != t[:-1]) | (b[1:] != b[:-1]))
            starts = [0]
            if diff.size:
                starts.extend((diff + 1).tolist())
            ends = (diff + 1).tolist()
            ends.append(W)
            parts = []
            last_t = -1
            last_b = -1
            for s, e in zip(starts, ends):
                tv = int(t[s])
                bv = int(b[s])
                if tv != last_t:
                    parts.append(f"\x1b[38;2;{tv >> 16};{(tv >> 8) & 255};"
                                 f"{tv & 255}m")
                    last_t = tv
                if bv != last_b:
                    parts.append(f"\x1b[48;2;{bv >> 16};{(bv >> 8) & 255};"
                                 f"{bv & 255}m")
                    last_b = bv
                if e > s:
                    parts.append(half * (e - s))
            parts.append('\x1b[0m')
            rows.append(''.join(parts))
        return rows

    # ── sixel graphics: real-pixel video in supporting terminals ────────────
    # Windows Terminal 1.22+, xterm, mlterm, mintty, iTerm2 … render these as
    # actual bitmaps at cell-pixel resolution instead of character cells.

    def _sixel_probe(self):
        """Detect sixel support (DA1 flag 4) + cell pixel size. Cached."""
        cached = getattr(self, '_sixel_probe_cache', None)
        if cached is not None:
            return cached
        ok, cw, ch = False, 8, 16
        if self._interactive() and msvcrt is not None:
            try:
                while msvcrt.kbhit():          # drain type-ahead
                    msvcrt.getch()
                sys.stdout.write('\x1b[c\x1b[16t')   # DA1 + cell size
                sys.stdout.flush()
                buf = bytearray()
                got_da = got_cell = False
                deadline = time.perf_counter() + 0.35
                last_byte = time.perf_counter()
                while time.perf_counter() < deadline:
                    if msvcrt.kbhit():
                        buf += msvcrt.getch()
                        last_byte = time.perf_counter()
                        if not got_da and re.search(rb'\x1b\[\?[0-9;]*c', bytes(buf)):
                            got_da = True
                        if not got_cell and re.search(rb'\x1b\[6;\d+;\d+t', bytes(buf)):
                            got_cell = True
                        if got_da and got_cell:
                            break
                    elif buf and time.perf_counter() - last_byte > 0.08:
                        break
                    else:
                        time.sleep(0.008)
                resp = bytes(buf)
                m1 = re.search(rb'\x1b\[\?([0-9;]*)c', resp)
                if m1 and b'4' in m1.group(1).split(b';'):
                    ok = True
                m2 = re.search(rb'\x1b\[6;(\d+);(\d+)t', resp)
                if m2:
                    h, w = int(m2.group(1)), int(m2.group(2))
                    if 0 < w <= 64 and 0 < h <= 64:
                        cw, ch = w, h
            except Exception:
                pass
        self._sixel_probe_cache = (ok, cw, ch)
        return self._sixel_probe_cache

    @staticmethod
    def _sixel_rle(data: bytes) -> str:
        """Run-length encode sixel column bytes; compress runs of 4+ only."""
        n = len(data)
        if n < 4:
            return data.decode('ascii')
        import numpy as np
        a = np.frombuffer(data, dtype=np.uint8)
        if n > 1:
            change = np.flatnonzero(a[1:] != a[:-1]) + 1
        else:
            change = np.empty(0, dtype=np.int64)
        starts = np.empty(change.size + 1, dtype=np.int64)
        starts[0] = 0
        starts[1:] = change
        lens = np.empty_like(starts)
        lens[:-1] = np.diff(starts)
        lens[-1] = n - starts[-1]
        out = []
        ap = out.append
        for v, ln in zip(a[starts].tolist(), lens.tolist()):
            if ln >= 4:
                ap('!' + str(ln) + chr(v))
            else:
                ap(chr(v) * ln)
        return ''.join(out)

    @classmethod
    def _sixel_encode(cls, rgb, colors=64, dither=False, gamma=1.0):
        """RGB uint8 frame (H,W,3) -> sixel DCS string at full pixel size."""
        import numpy as np
        from PIL import Image
        a = rgb
        if abs(gamma - 1.0) > 1e-6:
            a = np.clip(rgb.astype(np.float32), 0.0, 255.0)
            a = (255.0 * np.power(a / 255.0, float(gamma))).astype(np.uint8)
        H, W = a.shape[:2]
        im = Image.fromarray(a)
        q = im.quantize(colors=max(4, min(256, int(colors))),
                        method=Image.FASTOCTREE,
                        dither=Image.FLOYDSTEINBERG if dither else Image.NONE)
        idx = np.asarray(q)
        pal = np.asarray(q.getpalette() or [0, 0, 0], dtype=np.uint8)
        pal = pal.reshape(-1, 3)
        pad = (-H) % 6
        if pad:
            idx = np.pad(idx, ((0, pad), (0, 0)), mode='edge')
            H += pad
        out = [b'\x1bP0;0;8q']
        used = np.unique(idx)
        for c in used.tolist():                       # palette registers
            ci = int(c)
            if ci >= pal.shape[0]:
                continue
            r, g, b = int(pal[ci, 0]), int(pal[ci, 1]), int(pal[ci, 2])
            out.append(f'#{ci};2;{r * 100 // 255};{g * 100 // 255};'
                       f'{b * 100 // 255}'.encode())
        shifts = np.array([1, 2, 4, 8, 16, 32], dtype=np.uint16)
        for y0 in range(0, H, 6):                     # bands of 6 pixel rows
            band = idx[y0:y0 + 6, :]
            cols = np.unique(band)
            oh = band[None, :, :] == cols[:, None, None]      # (C,6,W)
            bits = (oh.astype(np.uint16) * shifts[None, :, None]).sum(axis=1)
            chars = (bits + 63).astype(np.uint8)
            first = True
            for i in range(cols.size):
                if not first:
                    out.append(b'$')
                first = False
                out.append(f'#{int(cols[i])}'.encode())
                out.append(cls._sixel_rle(chars[i].tobytes()).encode('ascii'))
            out.append(b'-')
        if out and out[-1] == b'-':
            out.pop()
        out.append(b'\x1b\\')
        return b''.join(out).decode('ascii')

    class _VPAudio:
        """ffmpeg decodes the audio track to PCM, sounddevice streams it.

        A feeder thread keeps a byte buffer filled; the PortAudio callback
        consumes it. Pausing stops consumption (pipe backpressure pauses
        ffmpeg), muting consumes but outputs silence so the clock keeps
        running. If the file has no audio track, playback degrades silently.
        """

        def __init__(self, path, exe, start=0.0, volume=0.8):
            import threading
            self.rate = 48000
            self.channels = 2
            self.volume = max(0.0, min(2.0, float(volume)))
            self.muted = False
            self.paused = False
            self.buf = bytearray()
            self.lock = threading.Lock()
            self.eof = False
            self.no_audio = False
            self.total_read = 0
            self.proc = None
            self.stream = None
            self.path = str(path)
            self.exe = exe
            self._spawn(start)
            threading.Thread(target=self._feed, daemon=True).start()

        def _spawn(self, start):
            self.proc = subprocess.Popen(
                [self.exe, '-v', 'error', '-ss', f'{max(0.0, start):.3f}',
                 '-i', self.path, '-vn', '-f', 's16le',
                 '-acodec', 'pcm_s16le', '-ar', str(self.rate),
                 '-ac', str(self.channels), 'pipe:1'],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                stdin=subprocess.DEVNULL)

        def _feed(self):
            try:
                while True:
                    # while paused, stop draining once buffered >1MB — the full
                    # pipe then backpressures ffmpeg instead of eating RAM
                    if self.paused:
                        with self.lock:
                            heavy = len(self.buf) > (1 << 20)
                        if heavy and self.proc.poll() is None:
                            time.sleep(0.05)
                            continue
                    chunk = self.proc.stdout.read(65536)
                    if not chunk:
                        break
                    with self.lock:
                        self.buf.extend(chunk)
                        self.total_read += len(chunk)
            except Exception:
                pass
            finally:
                try:
                    self.proc.stdout.close()
                except Exception:
                    pass
                with self.lock:
                    self.eof = True
                    if self.total_read == 0 and self.proc.poll() is not None:
                        self.no_audio = True

        def _cb(self, outdata, frames, tinfo, status):
            import numpy as np
            need = frames * self.channels * 2
            chunk = None
            if not self.paused and not self.no_audio:
                with self.lock:
                    if len(self.buf) >= need:
                        chunk = bytes(self.buf[:need])
                        del self.buf[:need]
                    elif self.buf:
                        chunk = bytes(self.buf)
                        del self.buf[:]
            flat = outdata.reshape(-1)
            if chunk:
                arr = np.frombuffer(chunk, dtype=np.int16)
                take = min(arr.size, flat.size)
                flat[:take] = arr[:take]
            else:
                take = 0
            flat[take:] = 0
            if take == 0:
                return
            if self.muted or self.volume <= 0.0:
                outdata[:] = 0
            elif abs(self.volume - 1.0) > 1e-3:
                scaled = np.clip(outdata.astype(np.float32) * self.volume,
                                 -32768, 32767).astype(np.int16)
                outdata[:] = scaled

        def start(self):
            try:
                import sounddevice as sd
                self.stream = sd.OutputStream(
                    samplerate=self.rate, channels=self.channels,
                    dtype='int16', blocksize=0, callback=self._cb)
                self.stream.start()
            except Exception:
                self.stream = None

        def seek(self, t):
            with self.lock:
                self.buf.clear()
                self.eof = False
            try:
                self.proc.kill()
                self.proc.wait()
            except Exception:
                pass
            self._spawn(max(0.0, float(t)))

        def stop(self):
            try:
                if self.stream:
                    self.stream.stop()
                    self.stream.close()
            except Exception:
                pass
            try:
                self.proc.kill()
            except Exception:
                pass

    def _video_probe(self, target):
        """Cheap metadata probe (resolution/duration/fps/size) for the manager."""
        try:
            import cv2
        except ImportError:
            return None
        try:
            with self._silence_stderr_fd():
                cap = cv2.VideoCapture(str(target))
                if not cap.isOpened():
                    return None
                fps = cap.get(cv2.CAP_PROP_FPS) or 0
                n = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
                w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
                h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
                cap.release()
            if fps <= 0 or n <= 0 or w <= 0 or h <= 0:
                return None
            return {'w': w, 'h': h, 'dur': round(n / fps, 1),
                    'fps': round(fps, 2), 'size': target.stat().st_size}
        except Exception:
            return None

    def _video_lib_path(self):
        return self.data_dir / "videos.json"

    def _video_lib_load(self):
        try:
            data = json.loads(
                self._video_lib_path().read_text(encoding="utf-8"))
            return data if isinstance(data, list) else []
        except Exception:
            return []

    def _video_lib_save(self, entries):
        try:
            self.data_dir.mkdir(parents=True, exist_ok=True)
            self._video_lib_path().write_text(
                json.dumps(entries, indent=2), encoding="utf-8")
        except OSError as e:
            self._err(f"Could not save video library: {e}")

    def _video_render_row(self, n, entry, name_w):
        """One colored library row (used by vman list)."""
        C, W, G, R, Y, LB = (Fore.CYAN, Fore.WHITE, Fore.GREEN, Fore.RED,
                             Fore.YELLOW, Fore.LIGHTBLACK_EX)
        rst = Style.RESET_ALL
        p = Path(entry.get('path', ''))
        meta = entry.get('meta')
        missing = not p.exists()
        title = p.name or str(p)
        if len(title) > name_w:
            title = title[:name_w - 1] + '…'
        pad = ' ' * (name_w - len(title))
        if missing:
            title_c = f"{R}{title}{rst}{pad}"
            dur = f"{R}{'—':>8}{rst}"
            res = f"{R}{'—':>9}{rst}"
            size = f"{R}{'—':>8}{rst}"
        else:
            title_c = f"{W}{title}{rst}{pad}"
            dur = f"{Y}{self._fmt_hms(meta['dur']) if meta else '—':>8}{rst}"
            res = f"{G}{(str(meta['w']) + 'x' + str(meta['h'])) if meta else '—':>9}{rst}"
            size = f"{LB}{self._fmt_size_mb(meta['size']) if meta else '—':>8}{rst}"
        return (f"  {C}{n:>2}{rst}│{title_c}│{dur}│{res}│{size}")

    def cmd_vman(self, *args):
        """Video manager: add / list / play / remove / info / clear."""
        entries = self._video_lib_load()
        sub = (args[0].lower() if args else 'list')
        rest = list(args[1:])

        if sub in ('add', 'scan', 'a'):
            if not rest:
                self._err("Usage: vman add <file|folder>")
                return
            try:
                t = self._resolve(rest[0])
            except ValueError as e:
                self._err(f"vman add: {e}")
                return
            if t.is_dir():
                files = sorted(
                    f for f in t.rglob('*')
                    if f.is_file() and f.suffix.lower() in self.VIDEO_EXTS)
            elif t.is_file():
                files = [t]
            else:
                self._err(f"Not found: {rest[0]}")
                return
            if not files:
                self._warn("No video files found there.")
                return
            known = {str(Path(e.get('path', '')).resolve()).lower()
                     for e in entries}
            added = dup = failed = 0
            for f in files:
                try:
                    key = str(f.resolve()).lower()
                except OSError:
                    key = str(f).lower()
                if key in known:
                    dup += 1
                    continue
                meta = self._video_probe(f)
                if meta is None:
                    failed += 1
                    continue
                entries.append({'path': str(f), 'meta': meta,
                                'added': datetime.now().isoformat(timespec='seconds')})
                known.add(key)
                added += 1
                print(f"  {Fore.GREEN}+{Style.RESET_ALL} {f.name}  "
                      f"{Fore.LIGHTBLACK_EX}{meta['w']}x{meta['h']}  "
                      f"{self._fmt_hms(meta['dur'])}{Style.RESET_ALL}")
            self._video_lib_save(entries)
            msg = f"Added {added} video(s) to the library."
            if dup:
                msg += f" {dup} duplicate(s) skipped."
            if failed:
                msg += f" {failed} unreadable file(s) skipped."
            self._ok(msg)
            return

        if sub in ('remove', 'rm', 'delete', 'del'):
            if rest and rest[0].lower() in ('all', 'clear'):
                self._video_lib_save([])
                self._ok("Video library cleared.")
                return
            try:
                n = self._parse_int(rest[0] if rest else None, "index",
                                    minimum=1, maximum=max(len(entries), 1))
            except ValueError as e:
                self._err(f"vman remove: {e}")
                return
            if not entries or n > len(entries):
                self._err("vman remove: no such entry (try 'vman list').")
                return
            gone = entries.pop(n - 1)
            self._video_lib_save(entries)
            self._ok(f"Removed #{n}: {Fore.YELLOW}"
                     f"{Path(gone.get('path', '')).name}{Style.RESET_ALL}")
            return

        if sub in ('clear', 'empty'):
            self._video_lib_save([])
            self._ok("Video library cleared.")
            return

        if sub in ('play', 'p'):
            self.cmd_vplay(rest[0] if rest else None)
            return

        if sub == 'info':
            try:
                n = self._parse_int(rest[0] if rest else None, "index",
                                    minimum=1)
            except ValueError as e:
                self._err(f"vman info: {e}")
                return
            if not entries or n > len(entries):
                self._err("vman info: no such entry (try 'vman list').")
                return
            e = entries[n - 1]
            p = Path(e['path'])
            meta = e.get('meta')
            C, W, LB, rst = Fore.CYAN, Fore.WHITE, Fore.LIGHTBLACK_EX, Style.RESET_ALL
            self._sep(f"VIDEO #{n}")
            fps_note = f"  ({meta['fps']:g} fps)" if meta else ''
            rows = [
                ('File', f"{W}{p.name}{rst}"),
                ('Path', f"{LB}{p}{rst}"),
                ('Size', f"{self._fmt_size_mb(meta['size']) if meta else '—'}"),
                ('Duration', f"{self._fmt_hms(meta['dur'], True) if meta else '—'}"
                             f"{fps_note}"),
                ('Resolution', f"{meta['w']}x{meta['h']}" if meta else '—'),
                ('Added', e.get('added', '—')),
                ('Status', f"{Fore.GREEN}ready{rst}" if p.exists()
                           else f"{Fore.RED}missing on disk{rst}"),
            ]
            for label, val in rows:
                print(f"  {C}{label:<12}{rst} {val}")
            print()
            return

        if sub in ('list', 'ls', 'library'):
            pass
        else:
            self._err(f"Unknown vman subcommand: {sub}")
            self._info("Subcommands: list · add <file|folder> · play <n> · "
                       "info <n> · remove <n|all> · clear")
            return

        # ── vman list ──
        if not entries:
            self._warn("Video library is empty.")
            self._info("Add some: vman add <file|folder>   "
                       "(folder = scans recursively)")
            return
        # lazy metadata for older entries
        changed = False
        for e in entries:
            if e.get('meta') is None and Path(e.get('path', '')).exists():
                e['meta'] = self._video_probe(Path(e['path']))
                changed = True
        if changed:
            self._video_lib_save(entries)

        C, H, W, G, R, Y, LB = (Fore.CYAN, self.C['header'], Fore.WHITE,
                                Fore.GREEN, Fore.RED, Fore.YELLOW,
                                Fore.LIGHTBLACK_EX)
        rst = Style.RESET_ALL
        name_w = 36
        # column widths: # (4) | title (name_w) | time (8) | res (9) | size (8)
        seg = (4, name_w, 8, 9, 8)
        sep_h = '┬'.join('─' * s for s in seg)
        sep_m = '┼'.join('─' * s for s in seg)
        sep_b = '┴'.join('─' * s for s in seg)

        total = sum((e.get('meta') or {}).get('dur', 0) for e in entries
                    if Path(e.get('path', '')).exists())
        banner = (f"{G}{Style.BRIGHT}VIDEO LIBRARY{rst}  {LB}·  {len(entries)} "
                  f"title(s)  ·  total {self._fmt_hms(total, True)}{rst}")
        banner_len = len(f"VIDEO LIBRARY  ·  {len(entries)} title(s)  ·  "
                         f"total {self._fmt_hms(total, True)}")
        inner = 4 + 1 + name_w + 1 + 8 + 1 + 9 + 1 + 8 + 2   # row width inside
        print()
        print(f"  {H}╔{'═' * inner}╗{rst}")
        print(f"  {H}║{rst} {banner}{' ' * max(1, inner - banner_len - 3)}"
              f"{H}║{rst}")
        print(f"  {H}╚{'═' * inner}╝{rst}")
        print(f"  {H}┌{sep_h}┐{rst}")
        hdr = (f"  {LB}{'#':<4}{H}│{rst}{LB}{'Title':<{name_w}}{H}│{rst}"
               f"{LB}{'Time':>8}{H}│{rst}{LB}{'Resolution':>9}{H}│{rst}"
               f"{LB}{'Size':>8}{rst}")
        print(hdr)
        print(f"  {H}├{sep_m}┤{rst}")
        for i, e in enumerate(entries, 1):
            print(self._video_render_row(i, e, name_w))
        print(f"  {H}└{sep_b}┘{rst}")
        print(f"  {LB}play with: vplay <#>   ·  add more: vman add <file|folder>"
              f"  ·  remove: vman remove <#>{rst}")
        print()

    def cmd_vplay(self, idx=None):
        """Play an entry from the video library by index."""
        entries = self._video_lib_load()
        if not entries:
            self._err("Video library is empty. Add videos with: vman add <file|folder>")
            return
        try:
            n = self._parse_int(idx, "index", minimum=1)
        except ValueError as e:
            self._err(f"vplay: {e}")
            return
        if n > len(entries):
            self._err(f"vplay: #{n} is out of range "
                      f"(library has {len(entries)} title(s)).")
            return
        e = entries[n - 1]
        p = Path(e.get('path', ''))
        if not p.exists():
            self._err(f"vplay: file is missing on disk: {p}")
            return
        self.cmd_play(str(p))

    def cmd_play(self, path=None, *opts):
        """Play a video in the terminal: truecolour video + audio + controls."""
        if not path:
            self._err("Usage: play <file> [--volume N] [--mute] [--no-audio] "
                      "[--width N] [--fps N]")
            self._err("                [--gamma N] [--levels] [--dither] "
                      "[--loop] [--start S]")
            self._err("                [--sixel | --half] [--colors N]")
            self._info("Tip: vman add <file|folder> builds a library; "
                       "vplay <#> plays from it.")
            return
        target = self._resolve(path)
        if not target.exists() or not target.is_file():
            self._err(f"Video not found: {path}")
            return
        try:
            import cv2
        except ImportError:
            self._err("OpenCV is required. Install it with: pip install opencv-python")
            return
        try:
            cv2.utils.logging.setLogLevel(cv2.utils.logging.LOG_LEVEL_SILENT)
        except Exception:
            pass

        o = self._ascii_opt
        mute = bool(o(opts, ["--mute", "mute"], False))
        no_audio = bool(o(opts, ["--no-audio", "no-audio"], False)) or mute
        vol_opt = o(opts, ["--volume", "volume"], 80)
        try:
            if vol_opt is True:      # bare "--volume" with no value
                raise ValueError
            vol = min(2.0, max(0.0, float(vol_opt)) / 100.0)
        except (TypeError, ValueError):
            vol = 0.8
        start_t = o(opts, ["--start", "start"], 0)
        try:
            start_t = max(0.0, float(start_t))
        except (TypeError, ValueError):
            start_t = 0.0
        loop = bool(o(opts, ["--loop"], False))
        style = self._ascii_style(opts)
        dither = 10.0 if style['dither'] else 0.0
        fps_arg = o(opts, ["--fps", "fps"], None)
        try:
            fps_arg = float(fps_arg) if fps_arg not in (None, True) else 0.0
        except (TypeError, ValueError):
            fps_arg = 0.0
        width_req = self._ascii_width_arg(opts)
        want_sixel = bool(o(opts, ["--sixel"], False))
        force_half = bool(o(opts, ["--half", "--halfblock", "--no-sixel"], False))
        colors = o(opts, ["--colors", "colors"], 64)
        try:
            colors = int(colors) if colors is not True else 64
        except (TypeError, ValueError):
            colors = 64
        colors = max(4, min(256, colors))

        with self._silence_stderr_fd():
            cap = cv2.VideoCapture(str(target))
            opened = cap.isOpened()
            first = cap.read() if opened else (False, None)
        if not opened:
            self._err(f"Could not open video: {target.name}")
            return
        if not first[0]:
            cap.release()
            self._err(f"Not a video OpenCV can decode: {target.name}")
            return
        src_fps = cap.get(cv2.CAP_PROP_FPS) or 0
        if not src_fps or src_fps <= 0 or src_fps > 240:
            src_fps = 24.0
        total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        vw = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
        vh = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
        if vw <= 0 or vh <= 0:
            cap.release()
            self._err(f"Video reports no usable frame size: {target.name}")
            return
        play_fps = min(src_fps, fps_arg) if fps_arg > 0 else src_fps
        duration = (total / src_fps) if total > 0 else 0.0
        if start_t and duration:
            start_t = min(start_t, max(0.0, duration - 0.5))

        # ── renderer: sixel (real pixels) when the terminal speaks it ──
        use_sixel = False
        cw, ch = 8, 16
        if not force_half and self._interactive():
            try:
                ok_sx, cw, ch = self._sixel_probe()
                if ok_sx:
                    use_sixel = True
                elif want_sixel:
                    use_sixel = True
                    self._warn("Terminal did not advertise sixel — "
                               "trying anyway (--half forces half-blocks).")
            except Exception:
                pass
        if use_sixel:
            try:
                from PIL import Image as _PILImage  # noqa: F401
            except ImportError:
                use_sixel = False
                self._warn("Pillow missing for sixel — pip install Pillow "
                           "(using half-blocks).")
        term = shutil.get_terminal_size((120, 30))
        if use_sixel:
            img_rows = max(6, term.lines - 4)      # title·blank·hud·keys
            width = max(20, term.columns)
            max_w_px = width * cw
            if width_req > 0:
                max_w_px = min(max_w_px, width_req * cw)
            max_h_px = img_rows * ch
            scale = min(max_w_px / vw, max_h_px / vh)
            pw = max(8, int(round(vw * scale)))
            ph = max(6, int(round(vh * scale)))
            ph -= ph % 6                            # whole sixel bands
            if ph < 6:
                ph = 6
            pw = min(pw, max_w_px)
            img_cell_rows = (ph + ch - 1) // ch
            render_tag = 'sixel'
        else:
            max_rows = self._ascii_max_rows(5)
            width = self._ascii_fit(vw, vh, width_req, reserve_rows=5)
            lb_w, lb_h = self._ascii_letterbox_size(vw, vh, width, max_rows)
            gw, gh = self._ascii_grid_size(lb_w, lb_h, width)
            pw, ph = gw, gh * 2
            render_tag = 'half-block'

        audio = None
        if not no_audio:
            exe = self._ffmpeg_exe()
            if exe:
                try:
                    audio = self._VPAudio(target, exe, start_t, vol)
                except Exception:
                    audio = None
        if audio is None:
            self._warn(no_audio and "Audio disabled (--no-audio/--mute) — silent playback."
                       or "No audio engine (need ffmpeg + sounddevice) — silent playback.")

        C, H, W, G, Y, R, LB = (Fore.CYAN, self.C['header'], Fore.WHITE,
                                Fore.GREEN, Fore.YELLOW, Fore.RED,
                                Fore.LIGHTBLACK_EX)
        rst = Style.RESET_ALL
        if use_sixel:
            render_desc = f"sixel · {pw}x{ph} px · {colors} colors"
        else:
            render_desc = f"half-block · {pw}x{ph} px on {width} cols"
        if audio:
            audio_desc = f"on · ffmpeg → sounddevice · {int(vol * 100)}%"
        elif no_audio:
            audio_desc = "disabled (--mute / --no-audio) · silent"
        else:
            audio_desc = "unavailable (need ffmpeg + sounddevice) · silent"
        rows_box = [
            ("source", f"{vw}x{vh} · {play_fps:.0f} fps · "
                       f"{self._fmt_hms(duration, True) if duration else 'live'}"
                       f" · {self._fmt_size_mb(target.stat().st_size)}"),
            ("render", render_desc),
            ("audio", audio_desc),
            ("keys", "SPACE pause · ←→ seek · ↑↓ vol · M mute · 0-9 jump · Q stop"),
        ]
        iw = min(max(10 + len(v) for _, v in rows_box), max(34, width - 4))
        print()
        print(f"  {H}╭{'─' * iw}╮{rst}")
        hdr = f"play · {target.name}"
        if len(hdr) + 2 > iw:
            hdr = hdr[:iw - 3] + '…'
        print(f"  {H}│{rst} {G}{Style.BRIGHT}{hdr}{rst}"
              f"{' ' * (iw - 1 - len(hdr))}{H}│{rst}")
        print(f"  {H}├{'─' * iw}┤{rst}")
        for key, val in rows_box:
            vis = 10 + len(val)
            if vis > iw:
                val = val[:max(4, iw - 11)] + '…'
                vis = 10 + len(val)
            print(f"  {H}│{rst} {C}{key:<8}{rst} {val}"
                  f"{' ' * (iw - vis)}{H}│{rst}")
        print(f"  {H}╰{'─' * iw}╯{rst}")
        if not self._interactive():
            self._err("play needs a real terminal (stdin/stdout is not interactive).")
            if audio:
                audio.stop()
            cap.release()
            return
        try:
            input(f"  {G}▶{rst} {LB}press ENTER to start{rst}  ")
        except (EOFError, KeyboardInterrupt):
            print()
            if audio:
                audio.stop()
            cap.release()
            self._warn("Cancelled.")
            return

        if audio:
            audio.start()
            if audio.stream is None:
                audio.stop()
                audio = None
                self._warn("Audio device unavailable — playing silent.")
        if start_t > 0:
            cap.set(cv2.CAP_PROP_POS_MSEC, start_t * 1000.0)

        self._clear()
        sys.stdout.write('\x1b[?25l')
        start_wall = time.perf_counter()
        cur_f = int(start_t * play_fps)
        base = start_t
        t0 = time.perf_counter()
        pause_at = None
        paused = False
        quit_flag = False
        last_rows = []
        last_sixel = ''
        have_frame = False
        redraw = True
        muted_ui = bool(audio and audio.muted)
        frames_shown = 0

        def seek_to(t):
            nonlocal base, t0, pause_at, cur_f
            t = max(0.0, min(t, max(0.0, duration - 0.25) if duration else t))
            base = t
            t0 = time.perf_counter()
            if paused:
                pause_at = t0
            cur_f = int(t * play_fps) - 1   # -1 forces the next tick to read
            cap.set(cv2.CAP_PROP_POS_MSEC, t * 1000.0)
            if audio:
                audio.seek(t)

        def vol_nudge(delta):
            nonlocal vol, muted_ui
            if audio:
                audio.volume = max(0.0, min(2.0, audio.volume + delta))
                vol = audio.volume
                muted_ui = audio.muted

        try:
            while True:
                now = time.perf_counter()
                clock_t = base + ((pause_at if paused else now) - t0)
                target_f = int(clock_t * play_fps)

                # ── keyboard ──
                while self._kbhit():
                    ch = self._getch()
                    if ch in (b'\x00', b'\xe0'):
                        ch2 = self._getch()
                        if ch2 == b'K':
                            seek_to(clock_t - 10.0)
                            redraw = True
                        elif ch2 == b'M':
                            seek_to(clock_t + 10.0)
                            redraw = True
                        elif ch2 == b'H':
                            vol_nudge(+0.05)
                            redraw = True
                        elif ch2 == b'P':
                            vol_nudge(-0.05)
                            redraw = True
                        elif ch2 == b'G':              # Home
                            seek_to(0.0)
                            redraw = True
                        elif ch2 == b'O' and duration:  # End
                            seek_to(duration - 1.0)
                            redraw = True
                    elif ch in (b' ', b's', b'S'):
                        paused = not paused
                        if paused:
                            pause_at = time.perf_counter()
                        else:
                            t0 += time.perf_counter() - pause_at
                            pause_at = None
                        if audio:
                            audio.paused = paused
                        redraw = True
                    elif ch in (b'm', b'M'):
                        if audio:
                            audio.muted = not audio.muted
                            muted_ui = audio.muted
                        redraw = True
                    elif ch in (b'+', b'='):
                        vol_nudge(+0.05)
                        redraw = True
                    elif ch in (b'-', b'_'):
                        vol_nudge(-0.05)
                        redraw = True
                    elif ch in (b',', b'<'):           # step −1 frame
                        seek_to(clock_t - 1.0 / play_fps)
                        redraw = True
                    elif ch in (b'.', b'>'):           # step +1 frame
                        seek_to(clock_t + 1.0 / play_fps)
                        redraw = True
                    elif len(ch) == 1 and ch in b'0123456789' and duration:
                        seek_to(duration * int(ch) / 10.0)
                        redraw = True
                    elif ch in (b'q', b'Q', b'\x1b', b'\x03'):
                        quit_flag = True
                if quit_flag:
                    break

                # ── end / loop ──
                if duration and clock_t >= duration - 0.05:
                    if loop:
                        seek_to(0.0)
                        clock_t = 0.0
                        target_f = 0
                    else:
                        break

                # ── fetch the frame that belongs on screen ──
                new_frame = False
                if total and target_f >= total:
                    break
                if target_f > cur_f:
                    gap = target_f - cur_f - 1
                    if gap > play_fps * 0.75:
                        cap.set(cv2.CAP_PROP_POS_FRAMES, target_f)
                    elif gap > 0:
                        for _ in range(min(gap, 24)):
                            cap.read()
                    ok, frame = cap.read()
                    if not ok:
                        break
                    cur_f = target_f
                    new_frame = True
                elif target_f < cur_f:
                    cap.set(cv2.CAP_PROP_POS_FRAMES, target_f)
                    ok, frame = cap.read()
                    if not ok:
                        break
                    cur_f = target_f
                    new_frame = True

                if new_frame:
                    interp = (cv2.INTER_AREA
                              if (vw > pw and vh > ph) else cv2.INTER_CUBIC)
                    small = cv2.resize(frame, (pw, ph),
                                       interpolation=interp)
                    rgb = cv2.cvtColor(small, cv2.COLOR_BGR2RGB)
                    if use_sixel:
                        last_sixel = self._sixel_encode(
                            rgb, colors, bool(dither), style['gamma'])
                    else:
                        last_rows = self._vp_encode(rgb, style['gamma'], dither)
                    have_frame = True
                    frames_shown += 1

                # ── draw ──
                if have_frame and (new_frame or redraw):
                    redraw = False
                    t_show = clock_t
                    prog = (t_show / duration) if duration else 0.0
                    prog = max(0.0, min(1.0, prog))
                    bar_w = max(10, min(38, width - 58))
                    filled = int(round(bar_w * prog))
                    icon = f"{Y}❚❚{rst}" if paused else f"{G}▶{rst}"
                    times = (f"{W}{self._fmt_hms(t_show, True)}{rst}"
                             f"{LB}/{self._fmt_hms(duration, True) if duration else '--:--'}{rst}")
                    bar = f"{G}{'█' * filled}{LB}{'░' * (bar_w - filled)}{rst}"
                    pct = f"{W}{int(prog * 100):>3d}%{rst}"
                    if audio is None:
                        volp = f"{LB}VOL –{rst}"
                    elif muted_ui:
                        volp = f"{R}VOL MUTED{rst}"
                    else:
                        vfill = int(round(8 * min(1.0, vol / 1.5)))
                        volp = (f"{LB}VOL{rst} {G}{'▮' * vfill}"
                                f"{LB}{'▯' * (8 - vfill)}{rst} "
                                f"{int(vol * 100):>3d}%")
                    hud = f" {icon} {times} {bar} {pct}  {volp}"
                    if paused:
                        hud += f"  {Y}{Style.BRIGHT}PAUSED{rst}"
                    if loop:
                        hud += f"  {Y}LOOP{rst}"
                    parts = [f"{LB}SPACE{rst} pause", f"{LB}←→{rst} ±10s",
                             f"{LB}↑↓{rst} vol", f"{LB}M{rst} mute"]
                    if width >= 66:
                        parts.append(f"{LB}0-9{rst} jump")
                    if width >= 84:
                        parts.append(f"{LB}, .{rst} frame")
                    parts.append(f"{LB}Q{rst} stop")
                    while (len(parts) > 2
                           and self._vis("  " + "  ·  ".join(parts)) > width):
                        parts.pop(len(parts) - 2)
                    ctrl = "  " + "  ·  ".join(parts)
                    rest = (f"{vw}x{vh} → {pw}x{ph} {render_tag} "
                            f"@ {play_fps:.0f}fps")
                    nm = target.name
                    if len(f"─ {nm} ── {rest}") > width - 1:
                        rest = f"{pw}x{ph} {render_tag}"
                    if len(f"─ {nm} ── {rest}") > width - 1:
                        room = width - 7 - len(rest) - 5
                        nm = (nm[:max(6, room)] + '…') if room > 6 else nm[:6] + '…'
                    head = (f" {H}─ {C}{Style.BRIGHT}{nm}{rst}{H} ──{rst}"
                            f"{LB} {rest}{rst}")
                    sys.stdout.write('\x1b[H\x1b[J')
                    sys.stdout.write(head + '\n\n')
                    if use_sixel:
                        sys.stdout.write(last_sixel)
                        sys.stdout.write(f'\x1b[{3 + img_cell_rows};1H')
                    else:
                        for r in last_rows:
                            sys.stdout.write(r + '\n')
                        sys.stdout.write('\n')
                    sys.stdout.write(hud + '\n' + ctrl)
                    sys.stdout.flush()

                # ── pacing ──
                if paused:
                    time.sleep(0.2)
                else:
                    delay = ((t0 + (cur_f + 1) / play_fps - base)
                             - time.perf_counter())
                    if delay > 0:
                        time.sleep(min(delay, 0.25))
        except KeyboardInterrupt:
            pass
        finally:
            if audio:
                audio.stop()
            cap.release()
            sys.stdout.write('\x1b[0m\x1b[?25h')
            sys.stdout.flush()
            self._clear()
            wall = time.perf_counter() - start_wall
            fps_act = frames_shown / wall if wall > 0.01 else 0.0
            self._ok(f"Playback stopped. {frames_shown} frame(s) · "
                     f"{fps_act:.0f} fps · {wall:.1f}s"
                     f"{'  ·  looped' if loop else ''}.")

    def cmd_google(self, query: str = None):
        import webbrowser as _wb
        try:
            if not query:
                _wb.open('https://www.google.com')
                self._ok("Opened Google.")
                return
            url = 'https://www.google.com/search?q=' + quote(query)
            _wb.open(url)
            self._ok(f"Searching Google for: {Fore.YELLOW}{query}")
        except Exception as e:
            self._err(str(e))

    def cmd_datetime(self):
        now = datetime.now()
        self._sep("DATE / TIME")
        print(f"  {Fore.CYAN}Date      {Fore.WHITE}{now.strftime('%A, %B %d, %Y')}")
        print(f"  {Fore.CYAN}Time      {Fore.WHITE}{now.strftime('%I:%M:%S %p')}")
        print(f"  {Fore.CYAN}ISO       {Fore.WHITE}{now.isoformat()}")
        print(f"  {Fore.CYAN}Epoch     {Fore.WHITE}{int(now.timestamp())}")
        self._sep()

    def cmd_shortcut(self, name: str = None, target: str = None):
        if not name:
            self._err("Usage: shortcut <name> [target-path]")
            return
        tgt = self._resolve(target or name)
        if not tgt.exists():
            self._err(f"Target not found: {tgt}")
            return
        lnk = self.current_path / (name if name.lower().endswith('.lnk') else name + '.lnk')
        try:
            ps = (f'$s=(New-Object -ComObject WScript.Shell).CreateShortcut("{lnk}"); '
                  f'$s.TargetPath="{tgt}"; $s.Save()')
            subprocess.run(['powershell', '-NoProfile', '-Command', ps],
                           capture_output=True, timeout=15)
            self._ok(f"Shortcut created: {Fore.YELLOW}{lnk}")
        except Exception as e:
            self._err(str(e))

    def cmd_powercfg(self, action: str = None):
        if not IS_WINDOWS:
            # Auto-fallback: powercfg → powerprofilesctl/tlp on Linux
            act = (action or '').lower()
            if shutil.which('powerprofilesctl'):
                if act in ('best', 'performance', 'high'):
                    self._run_cmd(['powerprofilesctl', 'set', 'performance'], timeout=10)
                    self._ok("Power profile: performance")
                elif act in ('balanced', 'default'):
                    self._run_cmd(['powerprofilesctl', 'set', 'balanced'], timeout=10)
                    self._ok("Power profile: balanced")
                elif act in ('saver', 'power-saver', 'powersaver'):
                    self._run_cmd(['powerprofilesctl', 'set', 'power-saver'], timeout=10)
                    self._ok("Power profile: power-saver")
                else:
                    rc, out, _ = self._run_cmd(['powerprofilesctl', 'get'], timeout=10)
                    print(f"  {Fore.CYAN}Active profile: {Fore.GREEN}{out.strip()}")
                    print(f"  {Fore.CYAN}Set profile    : {Fore.GREEN}powercfg <best|balanced|saver>")
                return
            elif shutil.which('tlp-stat'):
                self._run_cmd(['tlp-stat', '-s'], timeout=10); return
            else:
                self._err('No power tool found. Install power-profiles-daemon or tlp.'); return
        if not action:
            r = subprocess.run(['powercfg', '/list'], capture_output=True,
                               encoding='utf-8', errors='replace', timeout=15)
            self._sep("POWER PLANS")
            print(r.stdout.strip() or r.stderr.strip() or "(none)")
            self._sep()
            self._info("Usage: powercfg <best|balanced|saver|config>")
            return
        act = action.lower()
        try:
            if act in ('best', 'performance', 'high'):
                subprocess.run(['powercfg', '/setactive', 'SCHEME_MIN'],
                               capture_output=True, timeout=15)
                self._ok("Active plan: High performance.")
            elif act in ('balanced', 'default'):
                subprocess.run(['powercfg', '/setactive', 'SCHEME_BALANCED'],
                               capture_output=True, timeout=15)
                self._ok("Active plan: Balanced.")
            elif act in ('saver', 'power-saver', 'powersaver'):
                subprocess.run(['powercfg', '/setactive', 'SCHEME_MAX'],
                               capture_output=True, timeout=15)
                self._ok("Active plan: Power saver.")
            elif act == 'config':
                r = subprocess.run(['powercfg', '/getactivescheme'],
                                   capture_output=True, encoding='utf-8', errors='replace', timeout=15)
                self._sep("ACTIVE POWER PLAN")
                print(r.stdout.strip() or r.stderr.strip() or "(unknown)")
                self._sep()
            else:
                self._err("Usage: powercfg <best|balanced|saver|config>")
        except Exception as e:
            self._err(str(e))

    # ─────────────────────── new commands: system info ──────────────────────

    def cmd_bluetooth(self):
        if not IS_WINDOWS:
            # Auto-fallback: bluetooth → bluetoothctl on Linux
            if shutil.which('bluetoothctl'):
                rc, out, err = self._run_cmd(['bluetoothctl', 'devices'], timeout=15)
                self._sep("BLUETOOTH DEVICES")
                lines = [l for l in (out or '').strip().splitlines() if l.strip()]
                if lines:
                    for i, n in enumerate(lines[:30], 1):
                        print(f"  {Fore.CYAN}{i}. {Fore.WHITE}{n}")
                    if len(lines) > 30:
                        print(f"  {Fore.YELLOW}... {len(lines)-30} more")
                else:
                    print("  (none found)")
                self._sep()
            else:
                self._err('bluetoothctl not found. Install bluez.'); return
            return
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             'Get-PnpDevice -Class Bluetooth | Where-Object {$_.Status -eq "OK"} '
             '| Select-Object -ExpandProperty FriendlyName'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=30)
        names = [l for l in r.stdout.splitlines() if l.strip()]
        if not names:
            self._warn("No Bluetooth devices found.")
            return
        self._sep("BLUETOOTH DEVICES")
        for i, n in enumerate(names[:30], 1):
            print(f"  {Fore.CYAN}{i}. {Fore.WHITE}{n}")
        if len(names) > 30:
            print(f"  {Fore.YELLOW}... {len(names)-30} more")
        self._sep()

    def cmd_event_log(self, count: str = None):
        try:
            n = int(count) if count else 20
            n = max(1, min(n, 100))
        except ValueError:
            self._err(f"Invalid count: {count}")
            return
        if not IS_WINDOWS:
            if shutil.which('journalctl'):
                r = subprocess.run(['journalctl', '-n', str(n), '--no-pager', '-q'],
                                   capture_output=True, encoding='utf-8', errors='replace', timeout=20)
                self._sep("SYSTEM LOG (journalctl)")
                print(r.stdout.strip()[:2000] or "(no entries)")
                self._sep()
            else:
                try:
                    lines = Path('/var/log/syslog').read_text(
                        encoding='utf-8', errors='replace').splitlines()[-n:]
                    self._sep("SYSTEM LOG (/var/log/syslog)")
                    for l in lines:
                        print(f"  {l}")
                    self._sep()
                except PermissionError:
                    self._err("Permission denied — try 'root' first.")
                except FileNotFoundError:
                    self._err("No journalctl or /var/log/syslog found.")
            return
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             f'Get-WinEvent -LogName System -MaxEvents {n} '
             f'| Select-Object TimeCreated, Id, LevelDisplayName, ProviderName '
             f'| Format-Table -AutoSize'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=30)
        if r.stdout.strip():
            self._sep("SYSTEM EVENT LOG")
            print(r.stdout.strip()[:1600])
            self._sep()
        elif r.stderr.strip():
            self._err(r.stderr.strip()[:300])
        else:
            self._warn("No system events available.")

    def cmd_windows_key(self):
        try:
            key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                                 r"SOFTWARE\Microsoft\Windows NT\CurrentVersion")
            pkid = winreg.QueryValueEx(key, "DigitalProductId")[0]
            winreg.CloseKey(key)
            key_str = self._decode_product_key(pkid)
            self._sep("WINDOWS PRODUCT KEY")
            print(f"  {Fore.GREEN}{key_str}")
            self._sep()
        except Exception as e:
            self._err(str(e))

    def _decode_product_key(self, key) -> str:
        try:
            key_data = bytes(key)
        except Exception:
            return "N/A"
        if len(key_data) < 67:
            return "N/A"
        chars = 'BCDFGHJKMPQRTVWXY2346789'
        bkey = bytearray(key_data[52:67])
        if not any(bkey):
            return "N/A"
        result = []
        for i in range(24):
            acc = 0
            mod = 0
            for j in range(len(bkey) - 1, -1, -1):
                acc = (acc << 8) | bkey[j]
                bkey[j] = acc // 24
                acc %= 24
                mod = acc
            result.insert(0, chars[mod])
        text = ''.join(result)
        return f"{text[:5]}-{text[5:10]}-{text[10:15]}-{text[15:20]}-{text[20:25]}"

    def cmd_driver_list(self):
        r = subprocess.run(['driverquery', '/FO', 'TABLE'],
                           capture_output=True, encoding='utf-8', errors='replace', timeout=30)
        if r.stdout.strip():
            self._sep("INSTALLED DRIVERS")
            lines = [l for l in r.stdout.splitlines() if l.strip()]
            for line in lines[:40]:
                print(f"  {Fore.WHITE}{line}")
            if len(lines) > 40:
                print(f"  {Fore.YELLOW}... {len(lines)-40} more")
            self._sep()
        else:
            self._err(r.stderr.strip()[:300] or "Could not list drivers.")

    def cmd_cpu_temps(self):
        temps = {}
        try:
            temps = psutil.sensors_temperatures()
        except Exception:
            pass
        if temps:
            self._sep("CPU TEMPERATURES")
            for sensor, readings in temps.items():
                for r in readings:
                    print(f"  {Fore.CYAN}{sensor:<15} {Fore.GREEN}{r.current}°C")
            self._sep()
            return
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             'Get-CimInstance -Namespace root/WMI -ClassName MSAcpi_ThermalZoneTemperature '
             '| Select-Object -ExpandProperty CurrentTemperature'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=15)
        vals = [l for l in r.stdout.splitlines() if l.strip()]
        if vals:
            self._sep("CPU TEMPERATURES")
            for v in vals:
                try:
                    c = float(v) / 10 - 273.15
                    print(f"  {Fore.CYAN}Thermal zone {Fore.GREEN}{c:.1f}°C")
                except Exception:
                    pass
            self._sep()
            return
        self._warn("Temperature sensors not available on this system.")

    def cmd_ram_details(self):
        vm = psutil.virtual_memory()
        self._sep("RAM DETAILS")
        bar_len = 30
        filled = int(vm.percent / 100 * bar_len)
        bar = '█' * filled + '░' * (bar_len - filled)
        color = Fore.GREEN if vm.percent < 50 else Fore.YELLOW if vm.percent < 80 else Fore.RED
        print(f"  {Fore.CYAN}Total     {Fore.WHITE}{vm.total/(1024**3):.2f} GB")
        print(f"  {Fore.CYAN}Available {Fore.WHITE}{vm.available/(1024**3):.2f} GB")
        print(f"  {Fore.CYAN}Used      {color}{bar} {vm.percent:.1f}%{Style.RESET_ALL}  ({vm.used/(1024**3):.2f} GB)")
        if not IS_WINDOWS:
            # Auto-fallback: memory modules via dmidecode on Linux
            if shutil.which('dmidecode') and os.geteuid() == 0:
                rc, out, _ = self._run_cmd(['dmidecode', '-t', 'memory'], timeout=15)
                modules = []
                for block in (out or '').split('Memory Device\n'):
                    mfr = re.search(r'Manufacturer:\s*(.+)', block)
                    part = re.search(r'Part Number:\s*(.+)', block)
                    size = re.search(r'Size:\s*(\d+)\s*MB', block)
                    speed = re.search(r'Speed:\s*(\d+)\s*MT/s', block)
                    if size:
                        modules.append((mfr.group(1).strip() if mfr else '?',
                                        part.group(1).strip() if part else '?',
                                        f"{int(size.group(1))//1024} GB",
                                        f"{speed.group(1)} MT/s" if speed else '?'))
                if modules:
                    print(f"\n  {Fore.YELLOW}Memory modules:{Style.RESET_ALL}")
                    print(f"  {Fore.CYAN}  {'Manufacturer':<14} {'Part':<20} {'Size':>8} {'Speed':>12}")
                    print(f"  {Fore.LIGHTBLACK_EX}  {'─'*14} {'─'*20} {'─'*8} {'─'*12}")
                    for mfr, part, size, speed in modules:
                        print(f"  {Fore.WHITE}  {mfr:<14} {part:<20} {size:>8} {speed:>12}")
        else:
            r = subprocess.run(
                ['powershell', '-NoProfile', '-Command',
                 'Get-CimInstance Win32_PhysicalMemory '
                 '| Select-Object Manufacturer, PartNumber, Capacity, Speed | ConvertTo-Csv -NoTypeInformation'],
                capture_output=True, encoding='utf-8', errors='replace', timeout=20)
            if r.stdout.strip():
                print(f"\n  {Fore.YELLOW}Memory modules:{Style.RESET_ALL}")
                lines = [l for l in r.stdout.strip().splitlines() if l.strip()]
                if len(lines) >= 2:
                    headers = [h.strip('"') for h in lines[0].split(',')]
                    print(f"  {Fore.CYAN}  {headers[0]:<14} {headers[1]:<20} {headers[2]:>12} {headers[3]:>8}")
                    print(f"  {Fore.LIGHTBLACK_EX}  {'─'*14} {'─'*20} {'─'*12} {'─'*8}")
                    for line in lines[1:]:
                        vals = [v.strip('"') for v in line.split(',')]
                        if len(vals) >= 4:
                            try:
                                cap_gb = int(vals[2]) / (1024**3)
                                cap_str = f"{cap_gb:.0f} GB"
                            except (ValueError, IndexError):
                                cap_str = vals[2]
                            print(f"  {Fore.WHITE}  {vals[0]:<14} {vals[1]:<20} {cap_str:>12} {vals[3]:>8}")
        self._sep()

    def cmd_bios_info(self):
        if not IS_WINDOWS:
            # Auto-fallback: bios-info → dmidecode on Linux
            if shutil.which('dmidecode') and os.geteuid() == 0:
                rc, out, _ = self._run_cmd(['dmidecode', '-t', 'bios'], timeout=15)
                self._sep("BIOS / UEFI INFO")
                for line in (out or '').splitlines():
                    line = line.strip()
                    if any(k in line for k in ('Vendor:', 'Version:', 'Release Date:', 'BIOS Revision:', 'Manufacturer:')):
                        k, _, v = line.partition(':')
                        print(f"  {Fore.CYAN}{k.strip():<14}{Fore.WHITE}{v.strip()}")
                self._sep()
            else:
                self._err('dmidecode requires root. Use "root" first, or install dmidecode.')
            return
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             'Get-CimInstance Win32_BIOS '
             '| Select-Object Manufacturer, Name, Version, SerialNumber, ReleaseDate | ConvertTo-Csv -NoTypeInformation'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=20)
        if r.stdout.strip():
            self._sep("BIOS / UEFI INFO")
            lines = [l for l in r.stdout.strip().splitlines() if l.strip()]
            if len(lines) >= 2:
                headers = [h.strip('"') for h in lines[0].split(',')]
                vals = [v.strip('"') for v in lines[1].split(',')]
                labels = ['Manufacturer', 'Name', 'Version', 'Serial', 'Released']
                for i, label in enumerate(labels):
                    if i < len(vals) and vals[i]:
                        print(f"  {Fore.CYAN}{label:<14}{Fore.WHITE}{vals[i]}")
            self._sep()
        else:
            self._err(r.stderr.strip()[:300] or "Could not read BIOS info.")

    def cmd_usb_devices(self):
        if not IS_WINDOWS:
            # Auto-fallback: usb-devices → lsusb on Linux
            if shutil.which('lsusb'):
                rc, out, err = self._run_cmd(['lsusb'], timeout=15)
                self._sep("USB DEVICES")
                lines = [l for l in (out or '').strip().splitlines() if l.strip()]
                for i, n in enumerate(lines[:40], 1):
                    print(f"  {Fore.CYAN}{i}. {Fore.WHITE}{n}")
                if len(lines) > 40:
                    print(f"  {Fore.YELLOW}... {len(lines)-40} more")
                self._sep()
            else:
                self._err('lsusb not found. Install usbutils.'); return
            return
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             'Get-PnpDevice -Class USB | Where-Object {$_.Status -eq "OK"} '
             '| Select-Object -ExpandProperty FriendlyName'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=30)
        names = [l for l in r.stdout.splitlines() if l.strip()]
        if not names:
            self._warn("No USB devices found.")
            return
        self._sep("USB DEVICES")
        for i, n in enumerate(names[:40], 1):
            print(f"  {Fore.CYAN}{i}. {Fore.WHITE}{n}")
        if len(names) > 40:
            print(f"  {Fore.YELLOW}... {len(names)-40} more")
        self._sep()

    def cmd_monitor_info(self):
        r = subprocess.run(
            ['powershell', '-NoProfile', '-Command',
             'Get-CimInstance Win32_DesktopMonitor '
             '| Select-Object Name, ScreenWidth, ScreenHeight, Status | Format-Table -AutoSize'],
            capture_output=True, encoding='utf-8', errors='replace', timeout=20)
        if r.stdout.strip():
            self._sep("MONITOR INFO")
            print(r.stdout.strip())
            self._sep()
            return
        try:
            import ctypes as _c
            count = _c.windll.user32.GetSystemMetrics(80)
            print(f"  {Fore.CYAN}Monitors detected: {Fore.GREEN}{count}")
        except Exception:
            self._warn("Could not read monitor info.")

    # ─────────────────────── new commands: network / tools ──────────────────

    def cmd_dns_lookup(self, host: str = None):
        import socket as _s
        host = host or "localhost"
        if host in ('localhost', '127.0.0.1', '::1'):
            self._sep(f"DNS LOOKUP: {host}")
            print(f"  {Fore.CYAN}IPv4  {Fore.GREEN}127.0.0.1")
            print(f"  {Fore.CYAN}IPv6  {Fore.GREEN}::1")
            self._sep()
            self._ok("Resolved.")
            return
        try:
            infos = _s.getaddrinfo(host, None, proto=_s.IPPROTO_TCP)
            self._sep(f"DNS LOOKUP: {host}")
            seen = set()
            for family, _, _, _, sockaddr in infos:
                ip = sockaddr[0]
                if ip in seen:
                    continue
                seen.add(ip)
                kind = 'IPv4' if family == _s.AF_INET else 'IPv6'
                print(f"  {Fore.CYAN}{kind:<5}{Fore.GREEN}{ip}")
            self._sep()
            self._ok(f"Resolved to {len(seen)} address(es).")
        except Exception as e:
            self._err(f"Could not resolve '{host}': {e}")

    def cmd_subnet_calc(self, cidr: str = None):
        import ipaddress
        if not cidr:
            self._err("Usage: subnet-calc <ip/cidr>  e.g. subnet-calc 192.168.1.1/24")
            return
        try:
            net = ipaddress.ip_network(cidr, strict=False)
            if net.num_addresses > 2:
                first_host = net.network_address + 1
                last_host = net.broadcast_address - 1
            else:
                first_host = last_host = net.network_address
            self._sep(f"SUBNET: {net}")
            print(f"  {Fore.CYAN}Network     {Fore.WHITE}{net.network_address}")
            print(f"  {Fore.CYAN}Broadcast   {Fore.WHITE}{net.broadcast_address}")
            print(f"  {Fore.CYAN}Netmask     {Fore.WHITE}{net.netmask}")
            print(f"  {Fore.CYAN}Hosts       {Fore.WHITE}{net.num_addresses}")
            print(f"  {Fore.CYAN}First host  {Fore.WHITE}{first_host}")
            print(f"  {Fore.CYAN}Last host   {Fore.WHITE}{last_host}")
            self._sep()
        except ValueError as e:
            self._err(f"Invalid CIDR: {e}")
        except Exception as e:
            self._err(str(e))

    def cmd_wol(self, mac: str = None, ip: str = None, port: str = None):
        if not mac:
            self._err("Usage: wol <mac-address> [ip|255.255.255.255] [port|9]")
            return
        clean = mac.replace('-', '').replace(':', '')
        if len(clean) != 12:
            self._err("Invalid MAC address. Expected 6 bytes (e.g. AA-BB-CC-DD-EE-FF).")
            return
        try:
            mac_bytes = bytes.fromhex(clean)
        except ValueError:
            self._err("Invalid MAC address.")
            return
        payload = b'\xff' * 6 + mac_bytes * 16
        dest = ip or '255.255.255.255'
        try:
            p = int(port) if port else 9
        except ValueError:
            self._err(f"Invalid port: {port}")
            return
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
                s.sendto(payload, (dest, p))
            self._ok(f"Magic packet sent to {mac} @ {dest}:{p}")
        except Exception as e:
            self._err(f"Failed to send magic packet: {e}")

    def cmd_adapter(self, name: str = None):
        if not IS_WINDOWS:
            # Auto-fallback: adapter → ip link on Linux
            if shutil.which('ip'):
                rc, out, _ = self._run_cmd(['ip', '-o', 'link'], timeout=15)
                self._sep(f"NETWORK ADAPTERS{f' ({name})' if name else ''}")
                print(f"  {Fore.CYAN}{'Name':<16} {'MAC':<20} {'State'}")
                print(f"  {Fore.LIGHTBLACK_EX}{'─'*16} {'─'*20} {'─'*10}")
                for line in (out or '').strip().splitlines():
                    parts = line.split(':')
                    if len(parts) >= 4:
                        iface = parts[1].strip()
                        if name and name.lower() not in iface.lower(): continue
                        mac = parts[3].strip() if len(parts) > 3 else '?'
                        state = 'UP' if 'UP' in line.lower() else 'DOWN'
                        sc = Fore.GREEN if state == 'UP' else Fore.RED
                        print(f"  {Fore.WHITE}{iface:<16} {Fore.LIGHTBLACK_EX}{mac:<20} {sc}{state}{Style.RESET_ALL}")
                self._sep()
            else:
                self._err('ip command not found.'); return
            return
        cmd = ('Get-NetAdapter | Select-Object Name, Status, MacAddress, LinkSpeed | ConvertTo-Csv -NoTypeInformation')
        if name:
            cmd = (f'Get-NetAdapter -Name "*{name}*" | Select-Object Name, Status, MacAddress, LinkSpeed | ConvertTo-Csv -NoTypeInformation')
        r = subprocess.run(['powershell', '-NoProfile', '-Command', cmd],
                           capture_output=True, encoding='utf-8', errors='replace', timeout=20)
        self._sep(f"NETWORK ADAPTERS{f' ({name})' if name else ''}")
        lines = [l for l in (r.stdout or '').strip().splitlines() if l.strip()]
        if len(lines) >= 2:
            print(f"  {Fore.CYAN}{'Name':<24} {'Status':<12} {'MAC':<20} {'Speed'}")
            print(f"  {Fore.LIGHTBLACK_EX}{'─'*24} {'─'*12} {'─'*20} {'─'*12}")
            for line in lines[1:]:
                vals = [v.strip('"') for v in line.split(',')]
                if len(vals) >= 4:
                    status_color = Fore.GREEN if vals[1].lower() == 'up' else Fore.RED
                    print(f"  {Fore.WHITE}{vals[0]:<24} {status_color}{vals[1]:<12} {Fore.LIGHTBLACK_EX}{vals[2]:<20} {Fore.WHITE}{vals[3]}")
        elif r.stderr.strip():
            print(f"  {Fore.YELLOW}{r.stderr.strip().splitlines()[0]}")
        else:
            print("  (none)")
        self._sep()

    def cmd_shares(self):
        if not IS_WINDOWS:
            # Auto-fallback: shares → exportfs/smbstatus on Linux
            if shutil.which('exportfs'):
                rc, out, _ = self._run_cmd(['exportfs', '-v'], timeout=15)
                self._sep("NETWORK SHARES")
                print(out.strip() or "(no NFS shares)")
                self._sep()
            elif shutil.which('smbstatus'):
                rc, out, _ = self._run_cmd(['smbstatus', '--shares'], timeout=15)
                self._sep("NETWORK SHARES (Samba)")
                print(out.strip() or "(no Samba shares)")
                self._sep()
            else:
                self._err('No share tool found. Install nfs-utils or samba.'); return
            return
        r = subprocess.run(['net', 'share'], capture_output=True,
                           encoding='utf-8', errors='replace', timeout=15)
        out = r.stdout.strip() or r.stderr.strip()
        self._sep("NETWORK SHARES")
        print(out[:1200] if out else "No shares found.")
        self._sep()

