    def cmd_ssh(self, host: str = None, port: str = None):
        if not host:
            self._err("Usage: ssh <user@host> [port]")
            return
        host = host.strip()
        args = ['ssh', host] if not port else ['ssh', '-p', port, host]
        self._info(f"Connecting: {' '.join(args)}")
        try:
            subprocess.call(args)
            self._ok("SSH session ended.")
        except FileNotFoundError:
            self._err("ssh client not found on PATH.")
        except KeyboardInterrupt:
            print()
            self._ok("SSH session ended.")
        except Exception as e:
            self._err(str(e))

    def cmd_rdp(self, host: str = None):
        try:
            if host:
                subprocess.Popen(['mstsc', f'/v:{host}'])
                self._ok(f"Remote Desktop to {host} launched.")
            else:
                subprocess.Popen(['mstsc'])
                self._ok("Remote Desktop launched.")
        except Exception as e:
            self._err(str(e))

    def cmd_http_server(self, port: str = None):
        import http.server as _hs
        import functools as _functools
        try:
            p = int(port) if port else 8000
        except ValueError:
            self._err(f"Invalid port: {port}")
            return
        handler = _functools.partial(_hs.SimpleHTTPRequestHandler,
                                     directory=str(self.current_path))
        try:
            server = _hs.ThreadingHTTPServer(("127.0.0.1", p), handler)
        except OSError as e:
            self._err(f"Could not bind port {p}: {e}")
            return
        self._info(f"Serving {self.current_path} on http://localhost:{p}")
        self._info("Press Ctrl+C to stop.")
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()
            self._ok("Server stopped.")

    def cmd_hosts_edit(self, action: str = None, arg1: str = None, arg2: str = None):
        if IS_WINDOWS:
            hosts_file = Path(os.environ.get('SystemRoot', r'C:\Windows')) / \
                'System32' / 'drivers' / 'etc' / 'hosts'
        else:
            hosts_file = Path('/etc/hosts')
        if not action or action.lower() in ('list', 'show'):
            try:
                txt = hosts_file.read_text(encoding='utf-8', errors='replace')
            except Exception as e:
                self._err(f"Could not read hosts file: {e}")
                return
            self._sep("HOSTS FILE")
            for line in txt.splitlines():
                if line.strip() and not line.lstrip().startswith('#'):
                    print(f"  {Fore.WHITE}{line}")
            print(f"\n  {Fore.CYAN}Location: {Fore.GREEN}{hosts_file}")
            self._sep()
            self._info("Usage: hosts-edit add <ip> <domain> | hosts-edit remove <domain>")
            return
        act = action.lower()
        try:
            if act == 'add' and arg1 and arg2:
                entry = f"{arg1}\t{arg2}"
                with open(hosts_file, 'a', encoding='utf-8') as f:
                    f.write(entry + "\n")
                self._ok(f"Added hosts entry: {Fore.YELLOW}{entry}")
            elif act == 'remove' and arg1:
                txt = hosts_file.read_text(encoding='utf-8', errors='replace')
                kept = [l for l in txt.splitlines() if arg1 not in l]
                hosts_file.write_text('\n'.join(kept) + '\n', encoding='utf-8')
                self._ok(f"Removed hosts entries containing: {Fore.YELLOW}{arg1}")
            else:
                self._err("Usage: hosts-edit add <ip> <domain> | hosts-edit remove <domain>")
        except PermissionError:
            self._err("Permission denied. Run as administrator for this.")
        except Exception as e:
            self._err(str(e))

