    def cmd_vssadmin(self, action: str = "list", *args):
        """Shadow copies: vssadmin [list shadows|list writers|list providers|...]"""
        argv = ['vssadmin', action] + list(args) if action else ['vssadmin', 'list', 'shadows']
        if not self._is_admin():
            self._warn("vssadmin usually needs admin.")
        self._info(f"Running: {' '.join(argv)}")
        rc, out, err = self._run_cmd(argv, timeout=120)
        if out.strip(): print(out, end='')
        if err.strip(): print(f"{Fore.RED}{err}{Style.RESET_ALL}", end='')

    def cmd_wevtutil(self, *args):
        """Event log: wevtutil [el|enum-publishers|qe|qgli|cl|cp] [log] [path]"""
        if not args:
            self._info("Available logs:")
            rc, out, err = self._run_cmd(['wevtutil', 'el'], timeout=20)
            if rc == 0:
                for line in out.splitlines()[:30]:
                    print(f"  {line}")
                if len(out.splitlines()) > 30:
                    print(f"  {Fore.YELLOW}... and more{Style.RESET_ALL}")
            return
        argv = ['wevtutil'] + list(args)
        if any(a in ('el', 'ep', 'gli', 'qe', 'query', 'cl', 'cp') for a in argv[1:3]):
            pass  # ok
        rc, out, err = self._run_cmd(argv, timeout=60)
        if out.strip(): print(out, end='')
        if err.strip(): print(f"{Fore.RED}{err}{Style.RESET_ALL}", end='')

    def cmd_certutil(self, action: str = None, *args):
        """certutil [hash <file> | urldecode <str> | verify <url> | store]"""
        if not action:
            self._err("Usage: certutil [hash <file> | urldecode <str> | urlcache | store]"); return
        action = action.lower()
        if action == 'hash' and args:
            argv = ['certutil', '-hashfile', args[0]]
            self._sep(f"CertUtil hash: {args[0]}")
            rc, out, err = self._run_cmd(argv, timeout=30)
            if out.strip(): print(out, end='')
            if err.strip(): print(f"{Fore.YELLOW}{err}{Style.RESET_ALL}", end='')
            return
        if action == 'urldecode' and args:
            s = ' '.join(args)
            ps = f"[Uri]::UnescapeDataString('{s}')"
            rc, out, err = self._run_cmd(
                ['powershell', '-NoProfile', '-Command', ps], timeout=15)
            print(out.strip())
            return
        if action == 'urlcache':
            ps = ('Get-ChildItem -Path Cert:\\CurrentUser\\Root | '
                  'Select-Object Subject,NotAfter,Thumbprint | Format-Table -AutoSize')
            rc, out, err = self._run_cmd(
                ['powershell', '-NoProfile', '-Command', ps], timeout=30)
            if out.strip(): print(out, end='')
            return
        if action == 'store':
            ps = ('Get-ChildItem -Path Cert:\\CurrentUser\\My | '
                  'Select-Object Subject,NotAfter,Thumbprint | Format-Table -AutoSize')
            rc, out, err = self._run_cmd(
                ['powershell', '-NoProfile', '-Command', ps], timeout=30)
            if out.strip(): print(out, end='')
            return
        # passthrough
        argv = ['certutil'] + [action] + list(args)
        rc, out, err = self._run_cmd(argv, timeout=60)
        if out.strip(): print(out, end='')
        if err.strip(): print(f"{Fore.YELLOW}{err}{Style.RESET_ALL}", end='')

    def cmd_assoc(self, ext: str = None, prog: str = None):
        """File associations: assoc [.ext | .ext=progID]"""
        if not ext:
            self._info("Listing common extensions & their programs:")
            rc, out, err = self._run_legacy('assoc', timeout=15)
            if rc != 0:
                self._err(f"{err.strip() or 'assoc failed'}"); return
            exts = ['.txt', '.pdf', '.exe', '.jpg', '.png', '.zip', '.html',
                    '.mp4', '.mp3', '.docx', '.xlsx', '.json', '.py']
            shown = 0
            for line in out.splitlines():
                ext_l = line.split('=')[0].strip().lower()
                if ext_l in exts:
                    progm = line.split('=', 1)[1].strip()
                    print(f"  {Fore.CYAN}{ext_l:<10} -> {progm}{Style.RESET_ALL}")
                    shown += 1
            if shown == 0:
                print(out[:500])
            return
        # Set if prog given
        if '=' in ext or prog:
            arg = ext if prog is None else f"{ext}={prog}"
            if not self._is_admin():
                self._warn("Setting assoc may need admin.")
            rc, out, err = self._run_legacy(f'assoc {arg}', timeout=15)
            if rc == 0:
                self._ok(f"assoc {arg} done")
            else:
                self._err(f"{err.strip() or 'assoc failed'}")
            return
        # Lookup specific
        rc, out, err = self._run_legacy(f'assoc {ext}', timeout=10)
        if rc == 0 and out.strip():
            print(f"  {Fore.CYAN}{ext} -> {out.strip()}{Style.RESET_ALL}")
            chk = self._run_legacy(f'ftype {out.strip()}', timeout=10)
            if chk[0] == 0 and chk[1].strip():
                print(f"  {Fore.WHITE}ftype: {chk[1].strip()}{Style.RESET_ALL}")
        else:
            self._err(f"No association for {ext}")

    def cmd_recover(self, drive: str = None):
        """Recover readable sectors: recover <drive:>  (deprecated but still shipped)"""
        if not drive:
            self._err("Usage: recover <drive:>"); return
        self._info(f"Reading readable sectors from {drive} (may take long)...")
        rc, out, err = self._run_cmd(['recover', drive], timeout=300)
        if out.strip(): print(out, end='')
        if err.strip(): print(f"{Fore.YELLOW}{err}{Style.RESET_ALL}", end='')

    def cmd_lodctr(self, action: str = "query"):
        """Perf counter loader: lodctr [query|enable|disable|<file>]"""
        argv = ['lodctr', action]
        self._info(f"Running: lodctr {action}")
        rc, out, err = self._run_cmd(argv, timeout=60)
        if rc == 0 and 'query' in action.lower():
            hits = 0
            for line in out.splitlines():
                if '\\' in line:
                    print(f"  {Fore.CYAN}{line.strip()}{Style.RESET_ALL}")
                    hits += 1
                    if hits >= 60:
                        print(f"  {Fore.YELLOW}... output truncated{Style.RESET_ALL}")
                        break
        else:
            if out.strip(): print(out, end='')
            if err.strip(): print(f"{Fore.YELLOW}{err}{Style.RESET_ALL}", end='')

    def cmd_git(self, *args):
        """git wrapper: git [status|log -n|diff|branch|stash|pull|push|fetch]"""
        if not self._need('git'):
            return
        if not args:
            args = ('status',)
        argv = ['git'] + list(args)
        self._info(f"git {' '.join(args)}")
        try:
            subprocess.call(argv, cwd=str(self.current_path))
        except KeyboardInterrupt:
            print(f"\n{self.C['warning']}Stopped.")

    def cmd_docker(self, *args):
        """docker wrapper: docker [ps|images|logs <c>|stop <c>|rm <c>]"""
        if not self._need('docker'):
            return
        if not args:
            args = ('ps', '-a')
        argv = ['docker'] + list(args)
        self._info(f"docker {' '.join(args)}")
        try:
            subprocess.call(argv)
        except KeyboardInterrupt:
            print(f"\n{self.C['warning']}Stopped.")

    def cmd_ollama(self, *args):
        """ollama wrapper: ollama [list|run <model>|pull <model>|ps|rm <model>]"""
        if not self._need('ollama'):
            return
        if not args:
            args = ('list',)
        argv = ['ollama'] + list(args)
        self._info(f"ollama {' '.join(args)}")
        try:
            subprocess.call(argv)
        except KeyboardInterrupt:
            print(f"\n{self.C['warning']}Stopped.")

