    def _bookmarks_file(self):
        d = self.euf_path / "euf"
        d.mkdir(parents=True, exist_ok=True)
        return d / "bookmarks.json"

    def _bookmarks_load(self):
        f = self._bookmarks_file()
        if not f.exists():
            return []
        try:
            items = json.loads(f.read_text(encoding='utf-8'))
            return items if isinstance(items, list) else []
        except Exception:
            return []

    def _bookmarks_save(self, items):
        self._bookmarks_file().write_text(
            json.dumps(items, indent=2), encoding='utf-8')

    def _bookmark_pick(self, items, token):
        try:
            idx = int(token) - 1
            if 0 <= idx < len(items):
                return idx
            return None
        except ValueError:
            for i, b in enumerate(items):
                if str(b.get('name', '')).lower() == token.lower():
                    return i
            return None

    def cmd_bookmark(self, action: str = None, *args):
        action = (action or 'list').lower()
        items = self._bookmarks_load()
        if action in ('add', 'new'):
            if not args:
                self._err("Usage: bookmark add <url> [name]")
                return
            url = args[0]
            if not url.startswith(('http://', 'https://')):
                url = 'https://' + url
            from urllib.parse import urlparse
            name = args[1] if len(args) > 1 else (urlparse(url).netloc or url)
            items.append({'name': name, 'url': url})
            self._bookmarks_save(items)
            self._ok(f"Bookmarked '{name}'.")
        elif action == 'list':
            if not items:
                self._info("No bookmarks yet. Add one: bookmark add <url> [name]")
                return
            self._sep("BOOKMARKS")
            for i, b in enumerate(items, 1):
                print(f"  {Fore.CYAN}{i:>3}. {str(b.get('name', '')):<28}{Fore.WHITE}{b.get('url', '')}")
            self._sep()
        elif action == 'open':
            if not args:
                self._err("Usage: bookmark open <n|name>")
                return
            idx = self._bookmark_pick(items, args[0])
            if idx is None:
                self._err(f"No bookmark '{args[0]}'. Try 'bookmark list'.")
                return
            self._open_url(items[idx]['url'], items[idx]['name'])
        elif action in ('remove', 'del', 'rm'):
            if not args:
                self._err("Usage: bookmark remove <n|name>")
                return
            idx = self._bookmark_pick(items, args[0])
            if idx is None:
                self._err(f"No bookmark '{args[0]}'.")
                return
            name = items.pop(idx)['name']
            self._bookmarks_save(items)
            self._ok(f"Removed '{name}'.")
        else:
            self._err("Usage: bookmark [add <url> [name] | list | open <n> | remove <n>]")

    # ─────────────────────── benchmarks / monitors ───────────────────────────

    def cmd_benchmark(self):
        self._info("Running quick benchmark (~5 seconds)...")
        # CPU: integer math loops for 1 second
        t0 = time.time()
        n = 0
        x = 123456789
        while time.time() - t0 < 1.0:
            x = (x * 48271 + 1) % 2147483647
            n += 1
        cpu_mops = n / 1e6
        # RAM: write 256 MB
        t0 = time.time()
        buf = bytearray(256 * 1024 * 1024)
        buf[::4096] = b'\x01' * ((len(buf) + 4095) // 4096)
        ram_t = time.time() - t0
        ram_mbs = 256 / ram_t if ram_t else 0
        del buf
        # Disk: write + read 64 MB
        tmp = Path(tempfile.gettempdir()) / 'euf_bench.bin'
        blob = os.urandom(1024 * 1024)
        try:
            t0 = time.time()
            with open(tmp, 'wb') as f:
                for _ in range(64):
                    f.write(blob)
                f.flush()
                os.fsync(f.fileno())
            w_t = time.time() - t0
            t0 = time.time()
            with open(tmp, 'rb') as f:
                while f.read(1024 * 1024):
                    pass
            r_t = time.time() - t0
        finally:
            try:
                tmp.unlink()
            except OSError:
                pass
        self._sep("BENCHMARK RESULTS")
        print(f"  {Fore.CYAN}CPU  math loop :{Fore.WHITE} {cpu_mops:.1f} M ops/s")
        print(f"  {Fore.CYAN}RAM  write 256M:{Fore.WHITE} {ram_mbs:.0f} MB/s")
        print(f"  {Fore.CYAN}Disk write 64M :{Fore.WHITE} {64 / w_t:.0f} MB/s")
        print(f"  {Fore.CYAN}Disk read  64M :{Fore.WHITE} {64 / r_t:.0f} MB/s")
        self._sep()
        self._info("For a detailed disk test use 'disk-bench'. For internet speed use 'speedtest'.")

    def cmd_network_monitor(self):
        self._info("Live network monitor — Ctrl+C to stop.")
        last = psutil.net_io_counters()
        last_t = time.time()

        def rate(bps):
            if bps >= 1024 * 1024:
                return f"{bps / (1024 * 1024):6.1f} MB/s"
            return f"{bps / 1024:6.1f} KB/s"

        try:
            while True:
                time.sleep(1)
                cur = psutil.net_io_counters()
                now = time.time()
                dt = now - last_t or 1
                dl = (cur.bytes_recv - last.bytes_recv) / dt
                up = (cur.bytes_sent - last.bytes_sent) / dt
                try:
                    conns = len(psutil.net_connections(kind='inet'))
                except (psutil.AccessDenied, PermissionError):
                    conns = -1
                self._clear()
                self._ux_frame("NETWORK MONITOR",
                               right=datetime.now().strftime('%H:%M:%S'))
                dl_pct = min(100.0, dl / (10 * 1024 * 1024) * 100)
                up_pct = min(100.0, up / (10 * 1024 * 1024) * 100)
                print(f"  {Fore.CYAN}Download:{Fore.WHITE} {rate(dl)}  {self._ux_bar(dl_pct)}")
                print(f"  {Fore.CYAN}Upload  :{Fore.WHITE} {rate(up)}  {self._ux_bar(up_pct)}")
                print(f"\n  {Fore.CYAN}Total RX:{Fore.WHITE} {self._fmt_size(cur.bytes_recv)}"
                      f"    {Fore.CYAN}TX:{Fore.WHITE} {self._fmt_size(cur.bytes_sent)}")
                if conns >= 0:
                    print(f"  {Fore.CYAN}Active connections:{Fore.WHITE} {conns}")
                else:
                    print(f"  {Fore.YELLOW}Active connections: run as admin ('root') to see")
                print(f"\n  {Fore.LIGHTBLACK_EX}bars scaled to 10 MB/s · Ctrl+C to stop{Style.RESET_ALL}")
                last, last_t = cur, now
        except KeyboardInterrupt:
            print()
            self._ok("Network monitor stopped.")

    def cmd_clipboard_history(self):
        self._sep("CLIPBOARD")
        try:
            r = subprocess.run(['powershell', '-NoProfile', '-Command', 'Get-Clipboard'],
                               capture_output=True, encoding='utf-8', errors='replace', timeout=10)
            content = (r.stdout or '').strip()
            print(f"{Fore.WHITE}{content if content else '(empty)'}")
        except Exception as e:
            self._err(str(e))
        self._sep()
        self._info("Clipboard HISTORY: press Win+V to open it")
        self._info("(enable it once in: Settings > System > Clipboard > Clipboard history)")

    # ─────────────────────── text / file tools (cross-platform) ───────────────

    def cmd_nl(self, file: str = None, start: str = "1"):
        if not file:
            self._err("Usage: nl <file> [start_number]")
            return
        p = self._resolve(file)
        if not p.is_file():
            self._err(f"Not found: {file}")
            return
        try:
            n0 = int(start)
        except ValueError:
            n0 = 1
        for i, line in enumerate(self._read_lines(p), n0):
            print(f"  {Fore.CYAN}{i:>5}{Style.RESET_ALL}\t{line}")

    def cmd_rev(self, text: str = None, *rest):
        if text is None:
            self._err("Usage: rev <text>  |  rev <file>")
            return
        p = self._resolve(text)
        if p.is_file():
            for line in self._read_lines(p):
                print(line[::-1])
        else:
            print(' '.join([text] + list(rest))[::-1])

    def cmd_shuffle(self, file: str = None):
        if not file:
            self._err("Usage: shuffle <file>")
            return
        p = self._resolve(file)
        if not p.is_file():
            self._err(f"Not found: {file}")
            return
        lines = self._read_lines(p)
        random.shuffle(lines)
        for l in lines:
            print(l)

    def cmd_sample(self, file: str = None, n: str = "10"):
        if not file:
            self._err("Usage: sample <file> [n]")
            return
        p = self._resolve(file)
        if not p.is_file():
            self._err(f"Not found: {file}")
            return
        try:
            k = max(1, int(n))
        except ValueError:
            k = 10
        lines = self._read_lines(p)
        for l in random.sample(lines, min(k, len(lines))):
            print(l)

    def cmd_slugify(self, *text):
        if not text:
            self._err("Usage: slugify <text>")
            return
        import unicodedata
        s = ' '.join(text).lower()
        s = unicodedata.normalize('NFKD', s)
        s = s.encode('ascii', 'ignore').decode('ascii')
        s = re.sub(r'[^a-z0-9]+', '-', s).strip('-')
        print(f"  {Fore.GREEN}{s}{Style.RESET_ALL}")
        self._clip(s) and self._info("Copied to clipboard.")

    def cmd_lorem(self, n: str = "1"):
        try:
            paras = max(1, min(int(n), 10))
        except ValueError:
            paras = 1
        words = ("lorem ipsum dolor sit amet consectetur adipiscing elit sed do "
                 "eiusmod tempor incididunt ut labore et dolore magna aliqua ut "
                 "enim ad minim veniam quis nostrud exercitation ullamco laboris "
                 "nisi ut aliquip ex ea commodo consequat duis aute irure dolor "
                 "in reprehenderit in voluptate velit esse cillum dolore eu fugiat "
                 "nulla pariatur excepteur sint occaecat cupidatat non proident "
                 "sunt in culpa qui officia deserunt mollit anim id est laborum").split()
        for pi in range(paras):
            count = random.randint(40, 70)
            sent = random.sample(words, min(count, len(words)))
            text = ' '.join(sent)
            text = text[0].upper() + text[1:] + '.'
            print(f"\n  {Fore.WHITE}{text}{Style.RESET_ALL}")

    def cmd_entropy(self, *text):
        if not text:
            self._err("Usage: entropy <text>")
            return
        s = ' '.join(text)
        if not s:
            return
        from collections import Counter
        import math
        counts = Counter(s)
        ent = -sum((c / len(s)) * math.log2(c / len(s)) for c in counts.values())
        self._sep("SHANNON ENTROPY")
        print(f"  {Fore.CYAN}Length :{Fore.WHITE} {len(s)} chars")
        print(f"  {Fore.CYAN}Unique :{Fore.WHITE} {len(counts)} distinct")
        print(f"  {Fore.CYAN}Entropy:{Fore.GREEN} {ent:.4f} bits/char")
        verdict = ("very low (predictable)" if ent < 3 else
                   "low" if ent < 3.5 else
                   "decent" if ent < 4.5 else
                   "high (random-looking)" if ent < 5.5 else "very high")
        print(f"  {Fore.CYAN}Verdict:{Fore.YELLOW} {verdict}")
        self._sep()

    def cmd_hashid(self, h: str = None):
        if not h:
            self._err("Usage: hashid <hash>")
            return
        h = h.strip()
        length = len(h)
        looks_hex = bool(re.fullmatch(r'[0-9a-fA-F]+', h))
        known = {32: 'MD5', 40: 'SHA1', 56: 'SHA224', 64: 'SHA256',
                 96: 'SHA384', 128: 'SHA512'}
        self._sep("HASH ID")
        print(f"  {Fore.CYAN}Length :{Fore.WHITE} {length}")
        print(f"  {Fore.CYAN}Charset:{Fore.WHITE} {'hexadecimal' if looks_hex else 'other'}")
        if h.startswith('$2a$') or h.startswith('$2b$') or h.startswith('$2y$'):
            print(f"  {Fore.CYAN}Likely :{Fore.GREEN} bcrypt")
        elif h.startswith('$argon2'):
            print(f"  {Fore.CYAN}Likely :{Fore.GREEN} Argon2")
        elif h.startswith('$6$'):
            print(f"  {Fore.CYAN}Likely :{Fore.GREEN} sha512crypt")
        elif length in known and looks_hex:
            print(f"  {Fore.CYAN}Likely :{Fore.GREEN} {known[length]}")
        elif h.startswith('sha1$') or h.startswith('sha256$'):
            print(f"  {Fore.CYAN}Likely :{Fore.GREEN} Django-style {h.split('$')[0]}")
        else:
            print(f"  {Fore.CYAN}Likely :{Fore.YELLOW} unknown")
        self._sep()

    def cmd_jwt_decode(self, jwt: str = None):
        if not jwt:
            self._err("Usage: jwt-decode <token>")
            return
        parts = jwt.strip().split('.')
        if len(parts) < 2:
            self._err("Not a valid JWT (need header.payload.signature).")
            return

        def b64url(s):
            s += '=' * (-len(s) % 4)
            return base64.urlsafe_b64decode(s.encode())

        self._sep("JWT (signature NOT verified)")
        for label, part in (('HEADER', parts[0]), ('PAYLOAD', parts[1])):
            try:
                obj = json.loads(b64url(part))
                print(f"  {Fore.CYAN}{label}:{Style.RESET_ALL}")
                for k, v in obj.items():
                    if k == 'iat' or k == 'exp' or k == 'nbf':
                        try:
                            v = f"{v}  ({datetime.fromtimestamp(v):%Y-%m-%d %H:%M})"
                        except Exception:
                            pass
                    print(f"    {Fore.YELLOW}{k}{Style.RESET_ALL}: {v}")
            except Exception as e:
                print(f"  {Fore.CYAN}{label}:{Fore.RED} decode error: {e}")
        if len(parts) >= 3:
            sig = parts[2]
            print(f"  {Fore.CYAN}SIGNATURE:{Fore.WHITE} {sig[:64]}{'...' if len(sig) > 64 else ''}")
        self._sep()

    def cmd_csv2json(self, file: str = None, out: str = None):
        if not file:
            self._err("Usage: csv2json <file.csv> [out.json]")
            return
        p = self._resolve(file)
        if not p.is_file():
            self._err(f"Not found: {file}")
            return
        import csv as _csv
        with open(p, newline='', encoding='utf-8', errors='replace') as f:
            rows = list(_csv.DictReader(f))
        text = json.dumps(rows, indent=2, ensure_ascii=False)
        if out:
            op = self._resolve(out)
            op.write_text(text, encoding='utf-8')
            self._ok(f"Wrote {len(rows)} rows to {op}")
        else:
            print(f"{Fore.WHITE}{text[:4000]}")
            if len(text) > 4000:
                self._info("... truncated — pass an output file for full JSON.")

    def cmd_json2csv(self, file: str = None, out: str = None):
        if not file:
            self._err("Usage: json2json <file.json> [out.csv]".replace('json2json', 'json2csv'))
            return
        p = self._resolve(file)
        if not p.is_file():
            self._err(f"Not found: {file}")
            return
        import csv as _csv
        data = json.loads(p.read_text(encoding='utf-8', errors='replace'))
        if isinstance(data, dict):
            data = [data]
        if not isinstance(data, list):
            self._err("Expected a JSON array of objects.")
            return
        if not data:
            self._err("JSON array is empty; no CSV columns are available.")
            return
        if not all(isinstance(row, dict) for row in data):
            self._err("Expected a JSON array of objects.")
            return
        fields = list(dict.fromkeys(k for row in data for k in row))
        target = self._resolve(out) if out else None
        buf = open(target, 'w', newline='', encoding='utf-8') if target else None
        try:
            w = _csv.DictWriter(buf or sys.stdout, fieldnames=fields)
            w.writeheader()
            for row in data[:1000]:
                w.writerow({k: row.get(k, '') for k in fields})
        finally:
            if buf:
                buf.close()
        if target:
            self._ok(f"Wrote {len(data)} rows to {target}")
        elif len(data) > 1000:
            self._info("... truncated at 1000 rows — pass an output file.")

    def cmd_dotenv(self, action: str = None, file: str = None):
        fname = file if file and action != 'load' else (action if action not in (None, 'load', 'list', 'show') else None)
        p = self._resolve(fname) if fname else (self.current_path / '.env')
        if not p.is_file():
            self._err(f"No .env file at {p}")
            self._info("Usage: dotenv [file]  |  dotenv load [file]")
            return
        pairs = []
        for line in p.read_text(encoding='utf-8', errors='replace').splitlines():
            line = line.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            k, _, v = line.partition('=')
            pairs.append((k.strip(), v.strip().strip('"').strip("'")))
        do_load = (action or '').lower() == 'load'
        self._sep(f".env: {p.name}  ({len(pairs)} variables)")
        for k, v in pairs:
            mark = ''
            if do_load:
                os.environ[k] = v
                mark = f"  {Fore.GREEN}(loaded)"
            print(f"  {Fore.CYAN}{k}={Fore.WHITE}{v[:70]}{mark}")
        self._sep()
        if do_load:
            self._ok("Variables loaded into this session.")

    def cmd_archive(self, path: str = None, fmt: str = None):
        if not path:
            self._err("Usage: archive <file|dir> [zip|tar.gz|tar.bz2]")
            return
        src = self._resolve(path)
        if not src.exists():
            self._err(f"Not found: {path}")
            return
        fmt = (fmt or 'zip').lower()
        if fmt == 'zip':
            out = src.with_suffix('.zip') if src.is_file() else src.parent / f"{src.name}.zip"
            with zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as z:
                if src.is_file():
                    z.write(src, src.name)
                else:
                    for f in src.rglob('*'):
                        if f.is_file():
                            z.write(f, f.relative_to(src.parent))
        elif fmt in ('tar.gz', 'tgz', 'tar.bz2'):
            import tarfile as _tar
            mode = 'w:gz' if fmt in ('tar.gz', 'tgz') else 'w:bz2'
            out = src.parent / f"{src.name}.{fmt if fmt != 'tgz' else 'tar.gz'}"
            with _tar.open(out, mode) as t:
                t.add(src, arcname=src.name)
        else:
            self._err("Formats: zip, tar.gz, tar.bz2")
            return
        self._ok(f"Created {out} ({self._fmt_size(out.stat().st_size)})")

    def cmd_chmod(self, file: str = None, mode: str = None):
        if not file or not mode:
            self._err("Usage: chmod <file> <mode>   e.g. chmod script.py +x")
            self._info("Modes: +x -x +w -w +r -r   or octal like 755 (Linux)")
            return
        p = self._resolve(file)
        if not p.exists():
            self._err(f"Not found: {file}")
            return
        if IS_WINDOWS:
            if mode in ('+w', 'a+w'):
                os.chmod(p, os.stat(p).st_mode | 0o222)
                self._ok(f"Write permission granted: {p.name}")
            elif mode in ('-w', 'a-w'):
                os.chmod(p, os.stat(p).st_mode & ~0o222)
                self._ok(f"Write protection on: {p.name}")
            else:
                self._err("On Windows use +w/-w (or 'protect'/'unprotect' for read-only).")
            return
        cur = p.stat().st_mode
        if re.fullmatch(r'[0-7]{3,4}', mode):
            os.chmod(p, int(mode, 8))
        elif mode.startswith('+'):
            bits = 0
            if 'r' in mode: bits |= 0o444
            if 'w' in mode: bits |= 0o222
            if 'x' in mode: bits |= 0o111
            os.chmod(p, cur | bits)
        elif mode.startswith('-'):
            bits = 0
            if 'r' in mode: bits |= 0o444
            if 'w' in mode: bits |= 0o222
            if 'x' in mode: bits |= 0o111
            os.chmod(p, cur & ~bits)
        else:
            self._err(f"Bad mode: {mode}")
            return
        self._ok(f"chmod {mode} {p.name} → {oct(os.stat(p).st_mode & 0o777)}")

    def cmd_permissions(self, file: str = None):
        if not file:
            self._err("Usage: permissions <file>")
            return
        p = self._resolve(file)
        if not p.exists():
            self._err(f"Not found: {file}")
            return
        st = p.stat()
        self._sep(f"PERMISSIONS: {p.name}")
        if IS_WINDOWS:
            attrs = getattr(st, 'st_file_attributes', 0)
            flags = []
            for bit, label in [(0x1, 'READONLY'), (0x2, 'HIDDEN'), (0x4, 'SYSTEM'),
                               (0x20, 'ARCHIVE')]:
                if attrs & bit:
                    flags.append(label)
            print(f"  {Fore.CYAN}Attributes:{Fore.WHITE} {', '.join(flags) or 'NORMAL'}")
            print(f"  {Fore.CYAN}Owner    :{Fore.WHITE} {os.stat(p).st_uid} (use file-info for full owner)")
        else:
            m = st.st_mode & 0o777
            simple = ''
            for triple, chars in ((m >> 6, 'rwx'), (m >> 3, 'rwx'), (m, 'rwx')):
                simple += ''.join(ch if triple & (4 >> j) else '-' for j, ch in enumerate(chars))
            print(f"  {Fore.CYAN}Mode :{Fore.WHITE} {oct(m)}  ({simple})")
            print(f"  {Fore.CYAN}UID  :{Fore.WHITE} {st.st_uid}    GID: {st.st_gid}")
        self._sep()

    # ─────────────────────── math / fun (cross-platform) ──────────────────────

    def cmd_roman(self, n: str = None):
        if not n:
            self._err("Usage: roman <number-or-numeral>")
            return
        vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        if re.fullmatch(r'[ivxlcdmIVXLCDM]+', n) and not n.isdigit():
            total = 0
            prev = 0
            for ch in reversed(n.upper()):
                v = vals[ch]
                total += -v if v < prev else v
                prev = max(prev, v)
            print(f"  {Fore.GREEN}{n.upper()} = {total}{Style.RESET_ALL}")
            return
        try:
            x = int(n)
        except ValueError:
            self._err("Give a number (1-3999) or a roman numeral.")
            return
        if x < 1 or x > 3999:
            self._err("Roman numerals support 1..3999.")
            return
        table = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'),
                 (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'),
                 (5, 'V'), (4, 'IV'), (1, 'I')]
        out = ''
        for v, sym in table:
            while x >= v:
                out += sym
                x -= v
        print(f"  {Fore.GREEN}{n} = {out}{Style.RESET_ALL}")

    def cmd_fib(self, n: str = "10"):
        try:
            k = max(1, min(int(n), 94))
        except ValueError:
            k = 10
        a, b = 0, 1
        seq = []
        for _ in range(k):
            seq.append(a)
            a, b = b, a + b
        print(f"  {Fore.GREEN}{'  '.join(map(str, seq))}{Style.RESET_ALL}")

    def cmd_prime(self, n: str = None):
        if not n:
            self._err("Usage: prime <n>")
            return
        try:
            x = int(n)
        except ValueError:
            self._err("Need an integer.")
            return

        def is_p(v):
            if v < 2:
                return False
            if v % 2 == 0:
                return v == 2
            i = 3
            while i * i <= v:
                if v % i == 0:
                    return False
                i += 2
            return True
        if x < 0:
            self._err("Need a positive integer.")
            return
        self._sep(f"PRIME: {x}")
        print(f"  {Fore.CYAN}Prime? {Fore.GREEN if is_p(x) else Fore.RED}"
              f"{'YES' if is_p(x) else 'NO'}{Style.RESET_ALL}")
        nxt = x + 1 if is_p(x) else x
        found = []
        while len(found) < 5:
            if is_p(nxt):
                found.append(nxt)
            nxt += 1
        print(f"  {Fore.CYAN}Next primes:{Fore.WHITE} {', '.join(map(str, found))}")
        self._sep()

    def cmd_dice(self, spec: str = "1d6"):
        m = re.fullmatch(r'(\d*)[dD](\d+)', spec.strip())
        if not m:
            self._err("Usage: dice [NdM]   e.g. dice, dice 2d20")
            return
        count = int(m.group(1) or 1)
        sides = int(m.group(2))
        count = max(1, min(count, 20))
        sides = max(2, min(sides, 1000))
        rolls = [random.randint(1, sides) for _ in range(count)]
        total = sum(rolls)
        print(f"  {Fore.CYAN}{count}d{sides}: {Fore.GREEN}{' + '.join(map(str, rolls))}"
              f" = {Style.BRIGHT}{total}{Style.RESET_ALL}")

    def cmd_coin(self, n: str = "1"):
        try:
            k = max(1, min(int(n), 50))
        except ValueError:
            k = 1
        flips = [random.choice(('H', 'T')) for _ in range(k)]
        print(f"  {Fore.CYAN}Flips: {Fore.GREEN}{' '.join(flips)}{Style.RESET_ALL}")
        print(f"  {Fore.CYAN}Result:{Fore.WHITE} {flips.count('H')} Heads / {flips.count('T')} Tails")

    def cmd_choose(self, *args):
        if not args:
            self._err("Usage: choose <a> <b> <c> ...   (or: choose \"a | b | c\")")
            return
        if len(args) == 1 and '|' in args[0]:
            options = [o.strip() for o in args[0].split('|') if o.strip()]
        else:
            options = list(args)
        pick = random.choice(options)
        print(f"  {Fore.GREEN}{pick}{Style.RESET_ALL}")
        self._clip(pick)

    def cmd_age(self, date: str = None):
        if not date:
            self._err("Usage: age <YYYY-MM-DD>")
            return
        try:
            born = datetime.strptime(date.strip(), "%Y-%m-%d")
        except ValueError:
            self._err("Bad date — use YYYY-MM-DD.")
            return
        today = datetime.now()
        if born > today:
            self._err("That date is in the future.")
            return
        years = today.year - born.year - ((today.month, today.day) < (born.month, born.day))
        months = (today.year - born.year) * 12 + (today.month - born.month)
        if today.day < born.day:
            months -= 1
        days_total = (today - born).days
        self._sep("AGE")
        print(f"  {Fore.CYAN}Born    :{Fore.WHITE} {born:%Y-%m-%d} ({born:%A})")
        print(f"  {Fore.CYAN}Age     :{Fore.GREEN} {years} years, {months % 12} months")
        print(f"  {Fore.CYAN}Total   :{Fore.WHITE} {days_total:,} days")
        self._sep()

    def cmd_units(self, value: str = None, frm: str = None, to: str = None):
        if not value or not frm or not to:
            self._err("Usage: units <value> <from> <to>")
            self._info("Temp: C F K · Length: m km cm mm ft in mi yd · Weight: kg g lb oz")
            return
        try:
            v = float(value)
        except ValueError:
            self._err(f"Not a number: {value}")
            return
        f, t = frm.lower(), to.lower()
        temp = {'c': 1, 'celsius': 1, 'f': 2, 'fahrenheit': 2, 'k': 3, 'kelvin': 3}
        length = {'m': 1, 'meter': 1, 'metre': 1, 'km': 2, 'cm': 3, 'mm': 4,
                  'ft': 5, 'feet': 5, 'foot': 5, 'in': 6, 'inch': 6,
                  'mi': 7, 'mile': 7, 'yd': 8, 'yard': 8}
        weight = {'kg': 1, 'kilo': 1, 'g': 2, 'gram': 2, 'lb': 3, 'lbs': 3, 'pound': 3, 'oz': 4, 'ounce': 4}
        if f in temp and t in temp:
            celsius = {1: v, 2: (v - 32) * 5 / 9, 3: v - 273.15}[temp[f]]
            out = {1: celsius, 2: celsius * 9 / 5 + 32, 3: celsius + 273.15}[temp[t]]
        elif f in length and t in length:
            to_meters = {1: 1, 2: 1000, 3: 0.01, 4: 0.001, 5: 0.3048,
                         6: 0.0254, 7: 1609.344, 8: 0.9144}
            base = v * to_meters[length[f]]
            out = base / to_meters[length[t]]
        elif f in weight and t in weight:
            grams = {1: 1000, 2: 1, 3: 453.59237, 4: 28.349523}[weight[f]]
            out = v * grams / {1: 1000, 2: 1, 3: 453.59237, 4: 28.349523}[weight[t]]
        else:
            self._err("Unknown units. Try: C F K · m km ft in mi · kg lb oz g")
            return
        print(f"  {Fore.GREEN}{v:g} {frm} = {out:g} {to}{Style.RESET_ALL}")

