    def cmd_port_id(self, port: str = None):
        if not port:
            self._err("Usage: port-id <port|service>")
            return
        if port.isdigit():
            p = int(port)
            name = self._PORT_SERVICES.get(p)
            if name:
                print(f"  {Fore.CYAN}Port {p}:{Fore.GREEN} {name}")
            else:
                print(f"  {Fore.CYAN}Port {p}:{Fore.YELLOW} unknown / not in IANA common list")
        else:
            matches = [(n, s) for n, s in self._PORT_SERVICES.items()
                       if port.lower() in s.lower()]
            if matches:
                for n, s in matches:
                    print(f"  {Fore.CYAN}{s:<20}{Fore.WHITE}port {n}")
            else:
                self._err(f"No known service matches '{port}'.")

