    def cmd_listen(self, port: str = None):
        if not port or not port.isdigit():
            self._err("Usage: listen <port>   (Ctrl+C to stop)")
            return
        import socket as _s
        srv = _s.socket(_s.AF_INET, _s.SOCK_STREAM)
        srv.setsockopt(_s.SOL_SOCKET, _s.SO_REUSEADDR, 1)
        try:
            srv.bind(('0.0.0.0', int(port)))
        except OSError as e:
            self._err(f"Cannot bind: {e}")
            return
        srv.listen(5)
        self._ux_frame("TCP LISTENER", right=f"port {port}",
                       row2=f"{Fore.WHITE}waiting for connections · Ctrl+C to stop")
        try:
            while True:
                srv.settimeout(1.0)
                try:
                    client, addr = srv.accept()
                except _s.timeout:
                    if self._kbhit():
                        self._getch()
                        break
                    continue
                print(f"  {Fore.GREEN}[+]{Style.RESET_ALL} connection from "
                      f"{Fore.YELLOW}{addr[0]}:{addr[1]}{Style.RESET_ALL}")
                client.settimeout(2)
                try:
                    data = client.recv(512)
                    if data:
                        print(f"    {Fore.CYAN}{data[:200]!r}{Style.RESET_ALL}")
                except Exception:
                    pass
                client.close()
        except KeyboardInterrupt:
            pass
        finally:
            srv.close()
        print()
        self._ok("Listener stopped.")

    def cmd_timesync(self):
        self._info("Syncing system clock...")
        if IS_WINDOWS:
            rc, out, err = self._run_cmd(['w32tm', '/resync'], timeout=30)
            print((out or err).strip())
            if rc != 0:
                self._err("Time sync failed (try running as admin).")
            else:
                self._ok("Clock synced.")
        else:
            if shutil.which('timedatectl'):
                subprocess.run(['timedatectl', 'set-ntp', 'true'],
                               capture_output=True, timeout=15)
                rc, out, err = self._run_cmd(['timedatectl', 'status'], timeout=15)
                print(out.strip())
                self._ok("NTP enabled / clock synced.")
            elif shutil.which('chronyc'):
                rc, out, err = self._run_cmd(['chronyc', 'makestep'], timeout=15)
                print(out.strip() or err.strip())
            elif shutil.which('ntpdate'):
                subprocess.call(['sudo', 'ntpdate', 'pool.ntp.org'])
            else:
                self._err("No time-sync tool found (timedatectl/chronyc/ntpdate).")

    def cmd_forecast(self, city: str = None):
        city = city or 'auto:me'
        self._info(f"Getting weather for {Fore.YELLOW}{city}{Fore.WHITE}...")
        try:
            r = _lazy_requests().get(f"https://wttr.in/{quote(city)}",
                             params={'format': 'j1'}, timeout=15,
                             headers={'User-Agent': 'curl'})
            data = r.json()
            cur = data['current_condition'][0]
            today = data['weather'][0]
            area = data.get('nearest_area', [{}])[0].get('areaName', [{'value': city}])[0]['value']
            desc = cur['weatherDesc'][0]['value']
            self._sep(f"WEATHER: {area}")
            print(f"  {Fore.CYAN}Now     :{Fore.GREEN} {desc}, {cur['temp_C']}°C "
                  f"(feels {cur['FeelsLikeC']}°C)")
            print(f"  {Fore.CYAN}Humidity:{Fore.WHITE} {cur['humidity']}%   "
                  f"Wind: {cur['windspeedKmph']} km/h")
            print(f"  {Fore.CYAN}Today   :{Fore.WHITE} {today['mintempC']}°C / "
                  f"{today['maxtempC']}°C")
            self._sep()
        except Exception as e:
            self._err(f"Weather failed: {e}")

    def cmd_online(self):
        self._info("Checking internet connectivity...")
        ok = False
        for host in ('1.1.1.1', '8.8.8.8'):
            try:
                socket.create_connection((host, 53), timeout=3)
                print(f"  {Fore.GREEN}[OK]{Style.RESET_ALL} {host} reachable")
                ok = True
                break
            except OSError:
                print(f"  {Fore.RED}[FAIL]{Style.RESET_ALL} {host} unreachable")
        try:
            socket.gethostbyname('google.com')
            print(f"  {Fore.GREEN}[OK]{Style.RESET_ALL} DNS resolution works")
            ok = True
        except OSError:
            print(f"  {Fore.RED}[FAIL]{Style.RESET_ALL} DNS resolution broken")
        print()
        if ok:
            self._ok("You are online.")
        else:
            self._err("No internet connection detected.")

