        print(f"  {Fore.CYAN}Release :{Fore.WHITE} {platform.release()}")
        print(f"  {Fore.CYAN}Version :{Fore.WHITE} {platform.version()[:80]}")
        print(f"  {Fore.CYAN}Machine :{Fore.WHITE} {platform.machine()}")
