    def cmd_distro(self):
        self._sep("DISTRIBUTION")
        if IS_WINDOWS:
            print(f"  {Fore.CYAN}OS      :{Fore.GREEN} {self._get_windows_version()}")
            print(f"  {Fore.CYAN}Edition :{Fore.WHITE} {platform.win32_edition() if hasattr(platform, 'win32_edition') else 'n/a'}")
        else:
            info = {}
            try:
                for line in Path('/etc/os-release').read_text().splitlines():
                    if '=' in line:
                        k, _, v = line.partition('=')
                        info[k] = v.strip().strip('"')
            except FileNotFoundError:
                pass
            print(f"  {Fore.CYAN}Distro  :{Fore.GREEN} {info.get('PRETTY_NAME', platform.system())}")
            print(f"  {Fore.CYAN}ID      :{Fore.WHITE} {info.get('ID', '?')}  "
                  f"family: {info.get('ID_LIKE', '-')}")
            print(f"  {Fore.CYAN}Kernel  :{Fore.WHITE} {platform.release()}")
        self._sep()

    def cmd_cron(self, action: str = None):
        if IS_WINDOWS:
            # Auto-fallback: crontab → schtasks on Windows
            self.cmd_schtasks('list')
            self._info("Use 'schtasks create <name> <time> <cmd>' to add tasks.")
            return
        if not shutil.which('crontab'):
            self._err("crontab not found.")
            return
        if action in ('edit', 'e'):
            shell = os.environ.get('SHELL') or shutil.which('sh') or '/bin/sh'
            if not Path(shell).is_absolute() or not Path(shell).exists():
                self._err('Configured shell is not a valid executable.')
                return
            subprocess.run([shell, '-c', 'crontab -e'], check=False)
            return
        rc, out, err = self._run_cmd(['crontab', '-l'], timeout=10)
        self._sep("CRONTAB")
        if rc == 0 and out.strip():
            for line in out.splitlines():
                print(f"  {Fore.WHITE}{line}")
        else:
            print(f"  {Fore.YELLOW}(empty crontab)")
        self._sep()
        self._info("Add jobs with: cron edit")

