    def cmd_mounts(self):
        self._sep("MOUNTED FILESYSTEMS")
        if IS_WINDOWS:
            r = subprocess.run(
                ['powershell', '-NoProfile', '-Command',
                 'Get-Volume | Select-Object DriveLetter,FileSystem,SizeRemaining,Size '
                 '| ConvertTo-Csv -NoTypeInformation'],
                capture_output=True, encoding='utf-8', errors='replace', timeout=20)
            lines = [l for l in (r.stdout or '').strip().splitlines() if l.strip()]
            if len(lines) >= 2:
                print(f"  {Fore.CYAN}{'Drive':<8} {'FS':<8} {'Free':>12} {'Total':>12}  {'Usage'}")
                print(f"  {Fore.LIGHTBLACK_EX}{'─'*8} {'─'*8} {'─'*12} {'─'*12}  {'─'*10}")
                for line in lines[1:]:
                    vals = [v.strip('"') for v in line.split(',')]
                    if len(vals) >= 4:
                        try:
                            free = self._fmt_size(int(vals[2]))
                            total = self._fmt_size(int(vals[3]))
                            pct = (1 - int(vals[2]) / int(vals[3])) * 100 if int(vals[3]) > 0 else 0
                            color = Fore.GREEN if pct < 70 else Fore.YELLOW if pct < 90 else Fore.RED
                            print(f"  {Fore.WHITE}{(vals[0] or '?')+':':<8} {vals[1]:<8} {free:>12} {total:>12}  {color}{pct:5.1f}%{Style.RESET_ALL}")
                        except (ValueError, IndexError, ZeroDivisionError):
                            pass
            else:
                print("  (none)")
        else:
            for part in psutil.disk_partitions(all=False):
                try:
                    u = psutil.disk_usage(part.mountpoint)
                    print(f"  {Fore.CYAN}{part.mountpoint:<20}{Fore.WHITE}"
                          f"{part.fstype:<8} {u.percent:5.1f}%  "
                          f"{self._fmt_size(u.used)} / {self._fmt_size(u.total)}")
                except (PermissionError, OSError):
                    pass
        self._sep()

    def cmd_top(self, mode: str = None):
        mode = (mode or 'cpu').lower()
        plist = list(psutil.process_iter(['pid', 'name', 'memory_percent']))
        for p in plist:
            try:
                p.cpu_percent(None)
            except Exception:
                pass
        time.sleep(0.6)
        rows = []
        for p in plist:
            try:
                cpu = p.cpu_percent(None)
                mem = p.info.get('memory_percent') or 0.0
                rows.append((cpu, mem, p.info['pid'], p.info['name'] or '?'))
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        key = 1 if mode in ('mem', 'memory', 'ram') else 0
        rows.sort(key=lambda r: r[key], reverse=True)
        self._ux_frame(f"TOP PROCESSES ({'MEMORY' if key else 'CPU'})",
                       right=datetime.now().strftime('%H:%M:%S'))
        print(f"  {Fore.CYAN}{'PID':<8}{'CPU%':>7}{'MEM%':>7}  NAME{Style.RESET_ALL}")
        for cpu, mem, pid, name in rows[:14]:
            c = Fore.RED if cpu > 80 else Fore.YELLOW if cpu > 30 else Fore.GREEN
            print(f"  {Fore.WHITE}{pid:<8}{c}{cpu:6.1f}%{Fore.MAGENTA}{mem:6.1f}%"
                  f"  {Fore.WHITE}{name[:45]}{Style.RESET_ALL}")
        print(f"\n  {Fore.LIGHTBLACK_EX}{len(rows)} processes total · "
              f"usage: top cpu | top mem{Style.RESET_ALL}")

    def cmd_lsof(self, name: str = None):
        if name:
            target = str(self._resolve(name)).lower()
            hits = 0
            self._sep(f"OPEN HANDLES: {name}")
            for p in psutil.process_iter(['pid', 'name']):
                try:
                    for f in p.open_files():
                        if target in f.path.lower():
                            print(f"  {Fore.CYAN}PID {p.pid:<8}{Fore.WHITE}"
                                  f"{p.info['name']:<25} {f.path}")
                            hits += 1
                except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                    pass
            if not hits:
                self._info("No process has this file open.")
            self._sep()
            return
        self._info("Top processes by open file count...")
        rows = []
        for p in psutil.process_iter(['pid', 'name']):
            try:
                n = len(p.open_files())
                if n:
                    rows.append((n, p.pid, p.info['name'] or '?'))
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        rows.sort(reverse=True)
        self._sep("OPEN FILES BY PROCESS")
        for n, pid, pname in rows[:15]:
            print(f"  {Fore.CYAN}{n:>5} files  PID {pid:<8}{Fore.WHITE}{pname}")
        self._sep()

