            print(f"  {Fore.CYAN}Total :{Fore.WHITE} {self._fmt_size(sw.total)}")
            print(f"  {Fore.CYAN}Used  :{Fore.WHITE} {self._fmt_size(sw.used)} ({sw.percent}%)")
