    def _build_command_index(self):
        """Resolve canonical names before aliases, then keep the first alias."""
        index = {}
        for name in self.cmd_aliases:
            index.setdefault(name.lower(), name)
        for name, aliases in self.cmd_aliases.items():
            for alias in aliases:
                index.setdefault(alias.lower(), name)
        return index

