            if name == 'ulimit':
                self._info(f'Open files limit: {psutil.Process().rlimit(psutil.RLIMIT_NOFILE) if hasattr(psutil.Process(), "rlimit") else "N/A"}'); return
            if name == 'umask':
                val = f'{os.umask(0):04o}'
                os.umask(0o022)
                self._sep("UMASK")
                print(f"  {Fore.CYAN}Current : {Fore.WHITE}{val}")
                print(f"  {Fore.CYAN}Meaning : {Fore.WHITE}owner rw, group r, other r")
                self._sep()
                return
            if name == 'type':
                if not args: raise ValueError('Usage: type <command>')
                cmd = args[0]
                self._sep(f"TYPE: {cmd}")
                if cmd in self.cmd_aliases:
                    canonical = self._command_index.get(cmd, cmd)
                    print(f"  {Fore.CYAN}Kind  : {Fore.GREEN}EUF built-in command")
                    print(f"  {Fore.CYAN}Maps  : {Fore.WHITE}{canonical}")
                elif shutil.which(cmd):
                    print(f"  {Fore.CYAN}Kind  : {Fore.YELLOW}External binary")
                    print(f"  {Fore.CYAN}Path  : {Fore.WHITE}{shutil.which(cmd)}")
                else:
                    print(f"  {Fore.CYAN}Kind  : {Fore.RED}Not found")
                self._sep()
                return
            if name == 'hash':
                self._info('Command hash cache is managed internally.'); return
            if name == 'which':
                if not args: raise ValueError('Usage: which <command>')
                path = shutil.which(args[0])
                if path:
                    print(f"  {Fore.GREEN}{args[0]}{Style.RESET_ALL} -> {Fore.CYAN}{path}")
                else:
                    print(f"  {Fore.RED}{args[0]} not found")
                return
            if name == 'whereis':
                if not args: raise ValueError('Usage: whereis <command>')
                path = shutil.which(args[0])
                self._sep(f"WHEREIS: {args[0]}")
                print(f"  {Fore.CYAN}Binary : {Fore.GREEN}{path}" if path else f"  {Fore.CYAN}Binary : {Fore.RED}not found")
                self._sep()
                return
            if name == 'man':
                if not args: raise ValueError('Usage: man <command>')
                entry = self.COMMAND_HELP.get(args[0].lower())
                if entry: self.cmd_help(args[0])
                else: self._info(f'No manual entry for {args[0]}')
                return
            if name == 'whatis':
                if not args: raise ValueError('Usage: whatis <command>')
                entry = self.COMMAND_HELP.get(args[0].lower())
                if entry: print(f'{args[0]} — {entry.get("description", "?")}')
                else: print(f'{args[0]}: nothing known')
                return
            if name == 'apropos':
                if not args: raise ValueError('Usage: apropos <keyword>')
                q = args[0].lower()
                for k, v in self.COMMAND_HELP.items():
                    if q in v.get('description', '').lower(): print(f'{k} — {v.get("description", "")[:60]}')
                return
            if name == 'less':
                if args: self._try_native_shell(' '.join(['less'] + args), 'less')
                else: self._err('Usage: less <file>')
                return
            if name == 'more':
                if args: self._try_native_shell(' '.join(['more'] + args), 'more')
                else: self._err('Usage: more <file>')
                return
            if name == 'od':
                if not args: raise ValueError('Usage: od <file>')
                raw = self._extended_path(args[0]).read_bytes()[:512]
                self._sep(f"HEX DUMP: {args[0]} ({len(raw)} bytes)")
                print(f"  {Fore.CYAN}{'OFFSET':<10} {'HEX':<48} ASCII")
                print(f"  {Fore.LIGHTBLACK_EX}{'─'*10} {'─'*48} {'─'*16}")
                for i in range(0, len(raw), 16):
                    chunk = raw[i:i+16]
                    hex_part = ' '.join(f'{b:02x}' for b in chunk)
                    ascii_part = ''.join(chr(b) if 32 <= b < 127 else '.' for b in chunk)
                    print(f"  {Fore.LIGHTBLACK_EX}{i:08x}{Style.RESET_ALL}  {Fore.WHITE}{hex_part:<48} {Fore.GREEN}{ascii_part}")
                self._sep()
                return
            if name == 'xxd':
                if not args: raise ValueError('Usage: xxd <file>')
                self.cmd_extended('od', args); return
            if name == 'seq':
                start, step, end = 1, 1, 10
                if len(args) == 1: end = int(args[0])
                elif len(args) == 2: start, end = int(args[0]), int(args[1])
                elif len(args) >= 3: start, step, end = int(args[0]), int(args[1]), int(args[2])
                for i in range(start, end + 1, step): print(i)
                return
            if name == 'yes':
                word = args[0] if args else 'y'
                for _ in range(100): print(word)
