            if name == 'tr':
                if len(args) < 2: raise ValueError('Usage: tr <from> <to>')
                text = sys.stdin.read() if not sys.stdin.isatty() else ''
                if not text and len(args) > 2: text = args[2]
                trans = str.maketrans(args[0], args[1]); print(text.translate(trans)); return
            if name == 'cut':
                if not args: raise ValueError('Usage: cut <file> [-d delim] [-f fields]')
                delim = '\t'; fields = [0]
                i = 1
                while i < len(args):
                    if args[i] == '-d' and i + 1 < len(args): delim = args[i + 1]; i += 2
                    elif args[i] == '-f' and i + 1 < len(args): fields = [int(x) - 1 for x in args[i + 1].split(',')]; i += 2
                    else: i += 1
                for line in self._extended_read_text(self._extended_path(args[0])).splitlines():
                    parts = line.split(delim)
                    print(delim.join(parts[f] for f in fields if f < len(parts)))
                return
            if name == 'sort':
                if not args: raise ValueError('Usage: sort <file> [-r] [-n] [-u]')
                lines = self._extended_read_text(self._extended_path(args[0])).splitlines()
                reverse = '-r' in args; numeric = '-n' in args; unique = '-u' in args
                try: lines.sort(key=float, reverse=reverse) if numeric else lines.sort(reverse=reverse)
                except ValueError: lines.sort(reverse=reverse)
                if unique: lines = list(dict.fromkeys(lines))
                for l in lines: print(l)
                return
            if name == 'uniq':
                if not args: raise ValueError('Usage: uniq <file>')
                prev = None
                for line in self._extended_read_text(self._extended_path(args[0])).splitlines():
                    if line != prev: print(line); prev = line
                return
            if name == 'head':
                if not args: raise ValueError('Usage: head <file> [lines]')
                n = int(args[1]) if len(args) > 1 else 10
                for line in self._extended_read_text(self._extended_path(args[0])).splitlines()[:n]: print(line)
                return
            if name == 'tail':
                if not args: raise ValueError('Usage: tail <file> [lines]')
