                s2 = set(self._extended_read_text(self._extended_path(args[1])).splitlines())
                for l in sorted(s1 & s2): print(f'\t\t{l}')
                for l in sorted(s1 - s2): print(f'{l}')
                for l in sorted(s2 - s1): print(f'\t{l}')
