                cmd = shutil.which('tcpdump')
                if not cmd: self._err('tcpdump not found. Install tcpdump/libpcap.'); return
                if not args: raise ValueError('Usage: tcpdump <options> [filter]')
                rc, out, err = self._run_cmd([cmd] + list(args), timeout=15)
