            if name == 'gpg':
                self._info('gpg commands: gpg --version, gpg --verify, gpg --encrypt'); return
            if name == 'strings':
                if not args: raise ValueError('Usage: strings <file>')
                raw = self._extended_path(args[0]).read_bytes()
                current = []
                for b in raw:
                    if 32 <= b < 127: current.append(chr(b))
                    else:
                        if len(current) >= 4: print(''.join(current))
